// Class 9 Science Preloaded Chapter Data
window.CHAPTER_DATA = {"1":"<section class=\"chapter-section\" id=\"ch1\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">1</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 1: Matter in Our Surroundings</h2>\r\n      <p>NCERT Intext Questions & Chapter-End Exercises — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 3)</div>\r\n\r\n  <div class=\"q-card\" id=\"q1_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_1')\">\r\n      <div class=\"q-num\">Page 3 — Q1</div>\r\n      <div class=\"q-text\">Which of the following are matter?<br>Chair, air, love, smell, hate, almonds, thought, cold, lemon water, smell of perfume.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<p><strong>Definition of Matter:</strong> In science, <em>matter</em> is defined as anything that has mass and occupies space (volume).</p>\r\n<div class=\"step\">\r\n  <strong>Classification:</strong><br>\r\n  • <strong>Matter:</strong> <strong>Chair, air, almonds, lemon water, smell of perfume.</strong><br>\r\n  <em>Justification:</em> These entities possess a measurable mass and occupy physical volume. (Note: While 'smell' as a pure sensation is not matter, the 'smell of perfume' represents volatile physical odorant particles/molecules dispersed in the air that enter our olfactory receptors, hence it is physical matter).<br><br>\r\n  • <strong>Not Matter:</strong> <strong>Love, hate, thought, cold.</strong><br>\r\n  <em>Justification:</em> These represent human emotions, thoughts, feelings, or temperature sensations. They do not have mass and do not occupy physical space.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct definition of matter (mass and volume)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing physical matter items correctly</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying non-matter items (emotions/sensations)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_2')\">\r\n      <div class=\"q-num\">Page 3 — Q2</div>\r\n      <div class=\"q-text\">Give reasons for the following observation:<br>The smell of hot sizzling food reaches you several metres away, but to get the smell from cold food you have to go close.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Explanation:</strong><br>\r\n  1. The particles of aroma (gaseous vapours) released from food diffuse through air molecules to reach our nose.<br>\r\n  2. The rate of diffusion of particles is directly proportional to temperature. At higher temperatures, the kinetic energy of particles increases significantly (<span class=\"math\">KE ∝ T</span>).<br>\r\n  3. In hot sizzling food, the particles have high kinetic energy, move at high speeds, and diffuse rapidly across large distances in air in a fraction of a second.<br>\r\n  4. In cold food, the kinetic energy of particles is very low. Consequently, the rate of vaporization and diffusion is minimal, requiring us to go close to detect the smell.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Relationship between temperature and kinetic energy of particles</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Faster diffusion rate at high temperature explaining hot vs cold food</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_3')\">\r\n      <div class=\"q-num\">Page 3 — Q3</div>\r\n      <div class=\"q-text\">A diver is able to cut through water in a swimming pool. Which property of matter does this observation show?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Observation & Properties Demonstrated:</strong><br>\r\n  This observation demonstrates two fundamental characteristics of particles of liquids:\r\n  <ol>\r\n    <li><strong>Presence of Intermolecular Spaces:</strong> The particles of liquid (water) have relatively large spaces between them compared to solids. This allows external objects like a diver's body to displace water particles and move through them.</li>\r\n    <li><strong>Intermediate Force of Attraction:</strong> The intermolecular forces of attraction between water molecules are weak enough to be easily overcome by the muscular force exerted by the diver.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying intermolecular spaces between liquid particles</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying relatively weaker intermolecular force of attraction in liquids</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_4')\">\r\n      <div class=\"q-num\">Page 3 — Q4</div>\r\n      <div class=\"q-text\">What are the characteristics of the particles of matter?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Fundamental Characteristics of Particles of Matter:</strong>\r\n  <ol>\r\n    <li><strong>Particles of matter have spaces between them:</strong> When substances like sugar, salt, or potassium permanganate dissolve in water, their particles get accommodated into the empty inter-particle spaces between water molecules without increasing overall volume.</li>\r\n    <li><strong>Particles of matter are continuously moving:</strong> Particles possess kinetic energy which increases with rise in temperature. This continuous random motion causes diffusion and Brownian movement.</li>\r\n    <li><strong>Particles of matter attract each other:</strong> An attractive cohesive force holds particles together. The strength of this force is maximum in solids, intermediate in liquids, and minimum in gases.</li>\r\n    <li><strong>Particles of matter are extremely small:</strong> Particles are unimaginably minute, far beyond our microscopic visibility. A single tiny crystal of potassium permanganate contains millions of tiny particles that can tint litres of water.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Points 1 & 2 (spaces between particles & continuous motion)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Points 3 & 4 (intermolecular attraction & microscopic size)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 6)</div>\r\n\r\n  <div class=\"q-card\" id=\"q1_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_5')\">\r\n      <div class=\"q-num\">Page 6 — Q1</div>\r\n      <div class=\"q-text\">The mass per unit volume of a substance is called density (density = mass/volume). Arrange the following in order of increasing density:<br>air, exhaust from chimneys, honey, water, chalk, cotton and iron.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Analysis of Density:</strong><br>\r\n  Density (<span class=\"math\">ρ = Mass / Volume</span>) depends on mass of particles and how tightly packed they are in a given volume.<br>\r\n  • Gases have lowest density (air, chimney exhaust containing hot gases and soot particles).<br>\r\n  • Liquids have intermediate density (water, honey which is viscous and denser than water).<br>\r\n  • Solids have highest density (cotton with trapped air is least dense solid, chalk, iron has most tightly packed atoms).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Order of Increasing Density:</strong><br>\r\n  <span class=\"math\">Air &lt; Exhaust from chimneys &lt; Cotton &lt; Water &lt; Honey &lt; Chalk &lt; Iron</span>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct placement of gaseous phase (air < exhaust)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct placement of cotton and liquids (cotton < water < honey)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct placement of dense solids (chalk < iron)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_6')\">\r\n      <div class=\"q-num\">Page 6 — Q2</div>\r\n      <div class=\"q-text\">(a) Tabulate the differences in the characteristics of states of matter.<br>(b) Comment upon the following: rigidity, compressibility, fluidity, filling a gas container, shape, kinetic energy and density.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) Differences between States of Matter:</strong><br>\r\n  <table class=\"data-table\">\r\n    <tr><th>Characteristic</th><th>Solid</th><th>Liquid</th><th>Gas</th></tr>\r\n    <tr><td><strong>Shape</strong></td><td>Definite fixed shape</td><td>No fixed shape (takes shape of container)</td><td>No fixed shape</td></tr>\r\n    <tr><td><strong>Volume</strong></td><td>Definite fixed volume</td><td>Definite fixed volume</td><td>No fixed volume (expands)</td></tr>\r\n    <tr><td><strong>Intermolecular Space</strong></td><td>Very closely packed (minimum)</td><td>Loosely packed (intermediate)</td><td>Very large spaces (maximum)</td></tr>\r\n    <tr><td><strong>Intermolecular Force</strong></td><td>Strongest</td><td>Intermediate</td><td>Negligible / weakest</td></tr>\r\n    <tr><td><strong>Compressibility</strong></td><td>Incompressible</td><td>Negligible compressibility</td><td>Highly compressible</td></tr>\r\n    <tr><td><strong>Fluidity / Rigidity</strong></td><td>Rigid, cannot flow</td><td>Fluid, flows from higher to lower</td><td>Fluid, flows in all directions</td></tr>\r\n  </table>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Detailed Comments on Properties:</strong><br>\r\n  • <strong>Rigidity:</strong> Tendency of a substance to maintain its shape when subjected to external force. Solids are highly rigid.<br>\r\n  • <strong>Compressibility:</strong> The property of decreasing volume when external pressure is applied. Gases are highly compressible because of large inter-particle voids.<br>\r\n  • <strong>Fluidity:</strong> The ability of a substance to flow. Liquids and gases are fluids.<br>\r\n  • <strong>Filling a gas container:</strong> Due to negligible intermolecular attraction and high kinetic energy, gas particles move in all directions and occupy the entire container.<br>\r\n  • <strong>Shape:</strong> Structural geometry. Solids have fixed boundaries; liquids and gases adopt container shape.<br>\r\n  • <strong>Kinetic Energy:</strong> Energy possessed due to particle motion. Gases have maximum KE, solids minimum.<br>\r\n  • <strong>Density:</strong> Mass per unit volume (<span class=\"math\">M/V</span>). Generally, <span class=\"math\">Solid &gt; Liquid &gt; Gas</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Comprehensive comparison table covering shape, volume, force, space</span><span class=\"marking-marks\">2½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Accurate scientific explanations of all 7 physical properties</span><span class=\"marking-marks\">2½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_7')\">\r\n      <div class=\"q-num\">Page 6 — Q3</div>\r\n      <div class=\"q-text\">Give reasons:<br>(a) A gas fills completely the vessel in which it is kept.<br>(b) A gas exerts pressure on the walls of the container.<br>(c) A wooden table should be called a solid.<br>(d) We can easily move our hand in air but to do the same through a solid block of wood we need a karate expert.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) Why gas fills container completely:</strong><br>\r\n  The intermolecular forces of attraction between gas molecules are negligible, and particles possess very high kinetic energy. Hence, gas particles move randomly at high speeds in all possible directions and distribute themselves uniformly, filling the vessel completely.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Why gas exerts pressure on container walls:</strong><br>\r\n  Due to continuous random high-speed motion, gas particles constantly collide with one another and bombard the inner walls of the container. The force exerted by these particles per unit area of the wall constitutes <strong>gas pressure</strong> (<span class=\"math\">P = F/A</span>).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(c) Why a wooden table is called a solid:</strong><br>\r\n  A wooden table has a definite fixed shape, distinct boundaries, fixed volume, high rigidity, negligible compressibility, and cannot flow. These are all quintessential defining properties of a solid.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(d) Moving hand in air vs wood:</strong><br>\r\n  In air (gas), particles are widely separated with negligible intermolecular forces; our hand easily displaces air molecules. In a block of wood (solid), atoms are tightly bound by extremely strong cohesive forces with no free space. To overcome these intense binding forces, a massive localized force (like a karate strike) is required.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Reason (a) High kinetic energy and negligible forces</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Reason (b) Particle collision and force per unit area</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Reason (c) Fixed shape, volume, and rigidity</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Reason (d) Comparison of intermolecular forces and spaces</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_8')\">\r\n      <div class=\"q-num\">Page 6 — Q4</div>\r\n      <div class=\"q-text\">Liquids generally have lower density as compared to solids. But you must have observed that ice floats on water. Find out why.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Anomalous Behavior and Cage-like Structure of Ice:</strong><br>\r\n  1. In liquid water, molecules are constantly moving and relatively compact.<br>\r\n  2. When water freezes at 0°C (273 K) to form ice, water molecules arrange themselves into an open, tetrahedral three-dimensional crystal lattice held by extensive intermolecular hydrogen bonding.<br>\r\n  3. This crystal lattice contains a large amount of empty space (cage-like structure), making the volume of ice greater than the volume of an equal mass of liquid water.<br>\r\n  4. Since density is inversely proportional to volume (<span class=\"math\">Density = Mass / Volume</span>), the density of ice is <strong>lower than the density of liquid water</strong> (<span class=\"math\">0.917 g/cm³ &lt; 1.0 g/cm³</span>).<br>\r\n  5. Any substance with lower density than a liquid floats on it. Hence, ice floats on water.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of cage-like open crystal structure with empty spaces due to H-bonding</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Volume increases upon freezing ⟹ density decreases below water ⟹ floats</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 9)</div>\r\n\r\n  <div class=\"q-card\" id=\"q1_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_9')\">\r\n      <div class=\"q-num\">Page 9 — Q1</div>\r\n      <div class=\"q-text\">Convert the following temperature to Celsius scale:<br>(a) 300 K<br>(b) 573 K</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<p><strong>Conversion Formula:</strong> <span class=\"math\">Temperature in °C = Temperature in K - 273.15 ≈ K - 273</span></p>\r\n<div class=\"step\">\r\n  <strong>(a) 300 K:</strong><br>\r\n  <span class=\"math\">T(°C) = 300 - 273 = 27°C</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) 573 K:</strong><br>\r\n  <span class=\"math\">T(°C) = 573 - 273 = 300°C</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> (a) <strong>27°C</strong>, (b) <strong>300°C</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion formula °C = K - 273</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) 300 - 273 = 27°C</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) 573 - 273 = 300°C</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_10')\">\r\n      <div class=\"q-num\">Page 9 — Q2</div>\r\n      <div class=\"q-text\">What is the physical state of water at:<br>(a) 250°C<br>(b) 100°C?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) At 250°C:</strong><br>\r\n  The boiling point of pure water under standard atmospheric pressure is 100°C. Since 250°C is far above the boiling point, water exists entirely in the <strong>gaseous state (water vapour / steam)</strong>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) At 100°C:</strong><br>\r\n  100°C is the boiling point (transition temperature) of water. At this temperature, liquid water absorbs latent heat of vaporization to convert into steam.<br>\r\n  Therefore, water exists in a dynamic equilibrium in <strong>both liquid and gaseous states (liquid water and steam coexist)</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Gaseous state / steam at 250°C with reasoning</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Coexistence of liquid and gaseous states at 100°C</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_11')\">\r\n      <div class=\"q-num\">Page 9 — Q3</div>\r\n      <div class=\"q-text\">For any substance, why does the temperature remain constant during the change of state?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Concept of Latent Heat:</strong><br>\r\n  1. When heat is supplied to a substance at its melting point or boiling point, the temperature does not rise because the supplied thermal energy is entirely absorbed as <strong>Latent Heat</strong> ('hidden heat').<br>\r\n  2. Instead of increasing the kinetic energy of particles (which would raise temperature), this energy is utilized to overcome and break the strong intermolecular forces of attraction holding the particles together in that state.<br>\r\n  3. Once the phase transformation is 100% complete, any further supplied heat begins to increase the kinetic energy of particles again, causing the temperature to rise.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of Latent heat of fusion / vaporization</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Energy used to overcome intermolecular attraction without increasing KE</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_12')\">\r\n      <div class=\"q-num\">Page 9 — Q4</div>\r\n      <div class=\"q-text\">Suggest a method to liquefy atmospheric gases.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Method to Liquefy Gases:</strong><br>\r\n  Atmospheric gases can be liquefied by a combination of two processes:\r\n  <ol>\r\n    <li><strong>Applying High Pressure:</strong> Compressing the gas brings its widely spaced molecules closer together, reducing intermolecular distances so cohesive forces can take hold.</li>\r\n    <li><strong>Lowering Temperature (Cooling):</strong> Reducing temperature decreases the kinetic energy of gas molecules, slowing them down so they cannot resist intermolecular attractive forces.</li>\r\n  </ol>\r\n</div>\r\n<p><strong>Conclusion:</strong> Atmospheric gases are liquefied by <strong>increasing pressure and reducing temperature</strong> simultaneously (e.g. Linde's process for liquid nitrogen/oxygen).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying two essential conditions: High pressure & Low temperature</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanistic explanation (bringing particles close and reducing kinetic energy)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 10)</div>\r\n\r\n  <div class=\"q-card\" id=\"q1_in_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_13')\">\r\n      <div class=\"q-num\">Page 10 — Q1</div>\r\n      <div class=\"q-text\">Why does a desert cooler cool better on a hot dry day?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Explanation:</strong><br>\r\n  1. A desert cooler operates on the principle of <strong>evaporative cooling</strong> (evaporation causes cooling).<br>\r\n  2. On a hot dry day:<br>\r\n     • High temperature provides abundant thermal energy, accelerating the rate of evaporation.<br>\r\n     • Low humidity (dry air) means air can hold much more moisture, dramatically increasing the evaporation rate of water from cooler pads.<br>\r\n  3. As water evaporates rapidly, it absorbs large quantities of latent heat of vaporization from the incoming air, lowering the air temperature significantly.<br>\r\n  4. Hence, a desert cooler cools far more effectively on a hot, dry day than on a humid day.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Principle of evaporative cooling</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of high temperature and low humidity increasing evaporation rate</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Absorption of latent heat lowering air temperature</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_14')\">\r\n      <div class=\"q-num\">Page 10 — Q2</div>\r\n      <div class=\"q-text\">How does the water kept in an earthen pot (matka) become cold during summer?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Evaporative Cooling in Porous Clay Pots:</strong><br>\r\n  1. An earthen pot (matka) has millions of extremely fine microscopic pores on its clay surface.<br>\r\n  2. Water seeps out continuously through these pores to the outer surface of the pot.<br>\r\n  3. This thin film of water on the outer wall evaporates into the surrounding warm summer air.<br>\r\n  4. For evaporation to occur, the water molecules absorb the required <em>latent heat of vaporization</em> from the pot and the remaining water inside.<br>\r\n  5. As heat is continually extracted from the internal water, its temperature drops, making the water pleasantly cold.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Porous nature of earthen pot allowing water seepage</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaporation of water absorbing latent heat from inside water to lower temperature</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_15')\">\r\n      <div class=\"q-num\">Page 10 — Q3</div>\r\n      <div class=\"q-text\">Why does our palm feel cold when we put some acetone or petrol or perfume on it?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Volatile Liquids & Latent Heat Absorption:</strong><br>\r\n  1. Acetone, petrol, and alcohol-based perfumes are highly <strong>volatile organic liquids</strong> with very low boiling points.<br>\r\n  2. When placed on our palm, their particles evaporate very rapidly.<br>\r\n  3. During this rapid evaporation, the molecules absorb the required <em>latent heat of vaporization</em> directly from our skin (palm).<br>\r\n  4. Due to this loss of thermal energy, the temperature of our palm drops locally, producing a cooling sensation.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of volatile nature of acetone/petrol/perfume</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Extraction of latent heat of vaporization from the skin causing cooling</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_16')\">\r\n      <div class=\"q-num\">Page 10 — Q4</div>\r\n      <div class=\"q-text\">Why are we able to sip hot tea or milk faster from a saucer rather than a cup?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Surface Area Effect on Evaporation:</strong><br>\r\n  1. Evaporation is a <strong>surface phenomenon</strong>; its rate is directly proportional to the exposed surface area of the liquid.<br>\r\n  2. A saucer has a significantly larger exposed surface area compared to a cylindrical tea cup.<br>\r\n  3. When hot tea or milk is poured into a saucer, the increased surface area accelerates the rate of evaporation tremendously.<br>\r\n  4. More evaporation causes rapid loss of latent heat, allowing the hot tea to cool down much faster and be sipped easily without burning the mouth.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaporation is a surface phenomenon (Rate ∝ Surface Area)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Larger surface area in saucer causes faster cooling due to rapid evaporation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_in_17\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_in_17')\">\r\n      <div class=\"q-num\">Page 10 — Q5</div>\r\n      <div class=\"q-text\">What type of clothes should we wear in summer?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Recommended Clothing: Light-coloured Cotton Clothes.</strong><br>\r\n  <strong>Scientific Reasons:</strong>\r\n  <ol>\r\n    <li><strong>Sweat Absorption:</strong> During hot summers, our body perspires heavily to regulate internal temperature. Cotton is a natural, porous fabric and a good absorber of water; it quickly absorbs sweat and exposes it to the atmosphere.</li>\r\n    <li><strong>Evaporative Cooling:</strong> As sweat evaporates from the surface of the cotton fabric, it absorbs latent heat of vaporization from our body, keeping us cool and comfortable.</li>\r\n    <li><strong>Reflection of Heat:</strong> Light-coloured (white) clothes reflect solar thermal radiation rather than absorbing it, minimizing heat gain.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Recommending cotton and light-coloured clothes</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cotton absorbs sweat facilitating evaporative cooling</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Light colour reflects heat radiation</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q1_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">Convert the following temperatures to the Celsius scale:<br>(a) 293 K<br>(b) 470 K</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong> <span class=\"math\">°C = K - 273</span><br>\r\n  (a) <span class=\"math\">293 K = 293 - 273 = 20°C</span><br>\r\n  (b) <span class=\"math\">470 K = 470 - 273 = 197°C</span>\r\n</div>\r\n<p><strong>Final Answer:</strong> (a) <strong>20°C</strong>, (b) <strong>197°C</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) 20°C</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) 197°C</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">Convert the following temperatures to the Kelvin scale:<br>(a) 25°C<br>(b) 373°C</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong> <span class=\"math\">K = °C + 273</span><br>\r\n  (a) <span class=\"math\">25°C = 25 + 273 = 298 K</span><br>\r\n  (b) <span class=\"math\">373°C = 373 + 273 = 646 K</span>\r\n</div>\r\n<p><strong>Final Answer:</strong> (a) <strong>298 K</strong>, (b) <strong>646 K</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) 298 K</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) 646 K</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">Give reason for the following observations:<br>(a) Naphthalene balls disappear with time without leaving any solid.<br>(b) We can get the smell of perfume sitting several metres away.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) Sublimation of Naphthalene:</strong><br>\r\n  Naphthalene undergoes <strong>sublimation</strong> — the direct phase change from solid to gas without passing through the intermediate liquid state.<br>\r\n  At ambient room temperature, the intermolecular cohesive forces between naphthalene molecules are weak. They slowly and steadily vaporize into gaseous naphthalene molecules that disperse into the air, leaving behind zero solid residue.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Diffusion of Perfume Vapours:</strong><br>\r\n  Perfumes contain highly volatile aromatic liquids. When sprayed, these volatile particles immediately vaporize into gas. Due to their high kinetic energy and large inter-particle spaces in air, the perfume molecules rapidly diffuse across the room through continuous random collisions with air molecules, reaching our nostrils several metres away.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Definition of sublimation with weak intermolecular bonds</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Volatile nature and rapid diffusion of gases</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">Arrange the following substances in increasing order of forces of attraction between the particles — water, sugar, oxygen.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Concept:</strong> Intermolecular force of attraction is strongest in solids, intermediate in liquids, and weakest in gases.<br>\r\n  • <strong>Oxygen</strong> is a gas (negligible attraction between O₂ molecules).<br>\r\n  • <strong>Water</strong> is a liquid (moderate hydrogen bonding).<br>\r\n  • <strong>Sugar</strong> is a crystalline solid (strong intermolecular bonds).\r\n</div>\r\n<p><strong>Order of Increasing Forces of Attraction:</strong><br>\r\n<span class=\"math\">Oxygen &lt; Water &lt; Sugar</span></p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying state of matter of each substance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct increasing sequence: Oxygen < Water < Sugar</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">What is the physical state of water at:<br>(a) 25°C<br>(b) 0°C<br>(c) 100°C?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) At 25°C:</strong><br>\r\n  25°C is standard room temperature, between the melting point (0°C) and boiling point (100°C). Water exists as a <strong>liquid</strong>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) At 0°C:</strong><br>\r\n  0°C is the freezing/melting point of water. Both solid ice and liquid water coexist in equilibrium as latent heat of fusion is absorbed or released. Water exists as <strong>both solid and liquid</strong>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(c) At 100°C:</strong><br>\r\n  100°C is the boiling point of water. Water exists as <strong>both liquid and gas (vapour / steam)</strong> in equilibrium as latent heat of vaporization is absorbed.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Liquid at 25°C</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Solid and liquid coexistence at 0°C</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c) Liquid and gas/steam coexistence at 100°C</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">Give two reasons to justify:<br>(a) water at room temperature is a liquid.<br>(b) an iron almirah is a solid at room temperature.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) Water is a liquid at room temperature because:</strong>\r\n  <ol>\r\n    <li>Water has a fixed definite volume but no fixed shape; it takes the shape of the container in which it is placed.</li>\r\n    <li>Water can flow readily (fluidity) and possesses negligible compressibility with moderate intermolecular forces of attraction.</li>\r\n  </ol>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) An iron almirah is a solid at room temperature because:</strong>\r\n  <ol>\r\n    <li>It possesses a fixed definite shape and fixed volume with rigid, distinct boundaries that do not deform under normal forces.</li>\r\n    <li>It is extremely rigid and practically incompressible due to strong metallic bonds and negligible inter-particle spaces.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Two distinct liquid characteristics justified</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Two distinct solid characteristics justified</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">Why is ice at 273 K more effective in cooling than water at the same temperature?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Role of Latent Heat of Fusion:</strong><br>\r\n  1. Both ice and water at 273 K (0°C) are at the exact same temperature.<br>\r\n  2. However, water at 273 K possesses an additional <span class=\"math\">3.34 × 10⁵ J/kg</span> of heat energy in the form of <strong>latent heat of fusion</strong> compared to ice.<br>\r\n  3. When ice at 273 K is placed in contact with a warm substance, it first absorbs this extra latent heat of fusion (<span class=\"math\">3.34 × 10⁵ J/kg</span>) from the substance just to melt into water at 0°C, and then absorbs further heat as its temperature rises.<br>\r\n  4. Since ice extracts substantially more heat energy per unit mass from the surrounding medium, it is significantly more effective at cooling than water at the same temperature.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that water has latent heat of fusion while ice does not</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Ice absorbs extra 3.34 × 10⁵ J/kg to melt, cooling much more effectively</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">What produces more severe burns, boiling water or steam?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Reason:</strong><br>\r\n  <strong>Steam produces much more severe burns than boiling water</strong>, even though both are at the same temperature of 100°C (373 K).<br><br>\r\n  <strong>Explanation:</strong><br>\r\n  1. Steam at 100°C possesses extra latent heat energy called the <strong>Latent Heat of Vaporization</strong> (<span class=\"math\">22.6 × 10⁵ J/kg</span>).<br>\r\n  2. When steam comes into contact with skin, it first condenses into boiling water at 100°C, releasing this massive amount of latent heat (<span class=\"math\">2260 kJ/kg</span>) directly onto the skin tissue.<br>\r\n  3. It then cools down further as liquid water, releasing additional sensible heat.<br>\r\n  4. Boiling water only transfers sensible heat as it cools. Therefore, steam transfers far more energy per gram to the skin, causing deeper and more severe tissue damage.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying steam produces more severe burns</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Latent heat of vaporization of steam (22.6 × 10⁵ J/kg)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Heat released during condensation onto skin</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q1_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">Name A, B, C, D, E and F in the following diagram showing change in its state:<br>Solid ⇄ Liquid ⇄ Gas; Solid ⇄ Gas</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Processes of Phase Transition:</strong>\r\n  <ul>\r\n    <li><strong>A (Solid ⟶ Liquid):</strong> <strong>Melting / Fusion</strong> (Liquefaction upon heating).</li>\r\n    <li><strong>B (Liquid ⟶ Gas):</strong> <strong>Vaporization / Boiling</strong> (Evaporation).</li>\r\n    <li><strong>C (Gas ⟶ Liquid):</strong> <strong>Condensation</strong> (Liquefaction upon cooling).</li>\r\n    <li><strong>D (Liquid ⟶ Solid):</strong> <strong>Solidification / Freezing</strong>.</li>\r\n    <li><strong>E (Solid ⟶ Gas directly):</strong> <strong>Sublimation</strong> (without passing through liquid state).</li>\r\n    <li><strong>F (Gas ⟶ Solid directly):</strong> <strong>Deposition</strong> (Reverse sublimation).</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">A: Fusion, B: Vaporization</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">C: Condensation, D: Solidification</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">E: Sublimation, F: Deposition</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 1</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Industrial Gas Storage (LPG & CNG):</strong> Natural gas is compressed at high pressure into cylinders as CNG, and petroleum gas is liquefied under pressure as LPG.<br>(a) Which property of gases enables large volumes to be stored in small cylinders?<br>(b) Why does an LPG cylinder feel cold when gas escapes rapidly from it?<br>(c) Which odorant is mixed with LPG to detect leaks?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> High <strong>compressibility</strong> of gases due to large intermolecular spaces.<br><strong>(b)</strong> As pressurized liquefied gas expands rapidly through the nozzle, it vaporizes, absorbing latent heat of vaporization from the cylinder body, cooling it down.<br><strong>(c)</strong> <strong>Ethyl mercaptan (ethanethiol, C₂H₅SH)</strong>, which has a strong, distinctive foul smell.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why does a wooden table feel hard and cold initially during winter, while a woollen blanket at the same temperature feels warm?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">Both are at the same ambient temperature. However, wood has higher density and thermal conductivity than a woollen blanket, which traps air (a poor conductor of heat) in its porous fibers. When touched, wood conducts heat away from our hand faster, creating a sensation of cold. The blanket prevents conductive heat loss from our skin, reflecting body heat back and feeling warm.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" disabled style=\"opacity:.35;\">← Previous</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\">Chapter 2 →</button>\r\n  </div>\r\n</section>","2":"<section class=\"chapter-section\" id=\"ch2\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">2</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 2: Is Matter Around Us Pure?</h2>\r\n      <p>Pure Substances, Mixtures, Solutions, Colloids, Suspensions & Physical/Chemical Changes — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 15)</div>\r\n\r\n  <div class=\"q-card\" id=\"q2_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_in_1')\">\r\n      <div class=\"q-num\">Page 15 — Q1</div>\r\n      <div class=\"q-text\">What is meant by a substance?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Definition:</strong><br>\r\n  A <strong>substance</strong> (or pure substance) is a distinct form of matter that has:\r\n  <ol>\r\n    <li>A uniform, definite, and constant chemical composition throughout.</li>\r\n    <li>A specific and fixed set of characteristic physical and chemical properties (such as exact melting point, boiling point, and density).</li>\r\n    <li>Cannot be separated into other kinds of matter by any physical processes (e.g. pure gold, pure water H₂O, sodium chloride NaCl).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: Single type of particles with constant chemical composition</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cannot be separated by physical methods; fixed physical/chemical properties</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_in_2')\">\r\n      <div class=\"q-num\">Page 15 — Q2</div>\r\n      <div class=\"q-text\">List the points of differences between homogeneous and heterogeneous mixtures.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison Table:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Homogeneous Mixture</th><th>Heterogeneous Mixture</th></tr>\r\n    <tr><td><strong>Composition</strong></td><td>Uniform composition throughout the bulk.</td><td>Non-uniform composition throughout.</td></tr>\r\n    <tr><td><strong>Phases & Boundaries</strong></td><td>Single phase; no visible boundaries of separation between constituents.</td><td>Two or more phases; distinct visible boundaries of separation exist.</td></tr>\r\n    <tr><td><strong>Particle Distribution</strong></td><td>Constituent particles are completely mixed at molecular level.</td><td>Constituent particles are physically distinct and unevenly distributed.</td></tr>\r\n    <tr><td><strong>Examples</strong></td><td>Salt in water, sugar in water, clean air, brass (alloys).</td><td>Sand in water, oil and water, iron filings and sulphur powder, chalk powder in water.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Uniform vs non-uniform composition</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Single phase vs distinct phase boundaries</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate representative examples of each</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 18)</div>\r\n\r\n  <div class=\"q-card\" id=\"q2_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_in_3')\">\r\n      <div class=\"q-num\">Page 18 — Q1</div>\r\n      <div class=\"q-text\">Differentiate between homogeneous and heterogeneous mixtures with examples.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Key Differences:</strong><br>\r\n  • <strong>Homogeneous Mixtures:</strong> Mixtures in which the components are uniformly distributed and cannot be distinguished even under an optical microscope. They consist of a single uniform phase.<br>\r\n  <em>Examples:</em> Sodium chloride dissolved in water, ethanol in water, bronze (alloy).<br><br>\r\n  • <strong>Heterogeneous Mixtures:</strong> Mixtures that do not possess uniform composition; individual components remain physically separate and form distinct visible phases.<br>\r\n  <em>Examples:</em> Muddy water, kerosene oil in water, gunpowder (mixture of sulfur, charcoal, and potassium nitrate).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of homogeneous with example</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of heterogeneous with example</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_in_4')\">\r\n      <div class=\"q-num\">Page 18 — Q2</div>\r\n      <div class=\"q-text\">How are sol, solution and suspension different from each other?</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparative Analysis: Solution vs Sol (Colloid) vs Suspension:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Property</th><th>True Solution</th><th>Sol (Colloidal Solution)</th><th>Suspension</th></tr>\r\n    <tr><td><strong>Nature</strong></td><td>Homogeneous mixture</td><td>Heterogeneous (appears homogeneous)</td><td>Heterogeneous mixture</td></tr>\r\n    <tr><td><strong>Particle Size</strong></td><td>&lt; 1 nm (&lt; 10⁻⁹ m)</td><td>Between 1 nm and 1000 nm (10⁻⁹ to 10⁻⁶ m)</td><td>&gt; 1000 nm (&gt; 10⁻⁶ m)</td></tr>\r\n    <tr><td><strong>Filterability</strong></td><td>Passes through ordinary filter paper & animal membrane</td><td>Passes through ordinary filter paper, not ultrafilter</td><td>Retained on ordinary filter paper</td></tr>\r\n    <tr><td><strong>Stability</strong></td><td>Completely stable (particles never settle)</td><td>Stable (particles do not settle under gravity)</td><td>Unstable (particles settle on standing)</td></tr>\r\n    <tr><td><strong>Tyndall Effect</strong></td><td>Does not scatter light (No Tyndall effect)</td><td>Scatters light beam clearly (Shows Tyndall effect)</td><td>May scatter light when particles are suspended</td></tr>\r\n    <tr><td><strong>Visibility</strong></td><td>Particles invisible under high microscope</td><td>Visible only under ultramicroscope</td><td>Visible to naked eye or simple microscope</td></tr>\r\n    <tr><td><strong>Examples</strong></td><td>Copper sulphate in water, salt water</td><td>Milk, starch sol, ink, blood, fog</td><td>Chalk in water, muddy water, sand in water</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Particle size comparison for all three</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stability and settling behavior comparison</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Tyndall effect (scattering of light)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Filterability comparison</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate examples of all three systems</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_in_5')\">\r\n      <div class=\"q-num\">Page 18 — Q3</div>\r\n      <div class=\"q-text\">To make a saturated solution, 36 g of sodium chloride is dissolved in 100 g of water at 293 K. Find its concentration at this temperature.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given Data:</strong><br>\r\n  • Mass of solute (Sodium chloride, NaCl) = <span class=\"math\">36 g</span><br>\r\n  • Mass of solvent (Water, H₂O) = <span class=\"math\">100 g</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Total Mass of Solution:</strong><br>\r\n  <span class=\"math\">Mass of solution = Mass of solute + Mass of solvent</span><br>\r\n  <span class=\"math\">Mass of solution = 36 g + 100 g = 136 g</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Concentration Formula (Mass by Mass Percentage):</strong><br>\r\n  <span class=\"math\">Concentration (mass %) = (Mass of Solute / Mass of Solution) × 100</span><br>\r\n  <span class=\"math\">Concentration = (36 / 136) × 100 = (9 / 34) × 100 = 900 / 34 ≈ 26.47% (w/w)</span>\r\n</div>\r\n<p><strong>Final Answer:</strong> The concentration of the sodium chloride solution at 293 K is <strong>26.47% (by mass)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying mass of solute and solvent</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating total mass of solution = 36 + 100 = 136 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying formula (Mass of Solute / Mass of Solution) × 100</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct final calculated value = 26.47%</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 24)</div>\r\n\r\n  <div class=\"q-card\" id=\"q2_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_in_6')\">\r\n      <div class=\"q-num\">Page 24 — Q1</div>\r\n      <div class=\"q-text\">Classify each of the following as a chemical or physical change:<br>• Cutting of trees<br>• Melting of butter in a pan<br>• Rusting of almirah<br>• Boiling of water to form steam<br>• Passing of electric current through water and the water breaking down into hydrogen and oxygen gases<br>• Dissolving common salt in water<br>• Making a fruit salad with raw fruits<br>• Burning of paper and wood</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Concept:</strong><br>\r\n  • <strong>Physical Change:</strong> No new chemical substance is formed; chemical identity remains intact; generally reversible.<br>\r\n  • <strong>Chemical Change:</strong> One or more new chemical substances with distinct properties are formed; irreversible by simple physical methods.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Classification & Justifications:</strong>\r\n  <ul>\r\n    <li><strong>Cutting of trees:</strong> <em>Physical Change</em> (alters shape and size; chemical structure of wood remains cellulose/lignin).</li>\r\n    <li><strong>Melting of butter in a pan:</strong> <em>Physical Change</em> (phase change from solid to liquid lipid; no new substance formed).</li>\r\n    <li><strong>Rusting of almirah:</strong> <em>Chemical Change</em> (iron oxidizes to hydrated iron(III) oxide: 4Fe + 3O₂ + 2xH₂O → 2Fe₂O₃·xH₂O).</li>\r\n    <li><strong>Boiling of water to form steam:</strong> <em>Physical Change</em> (phase transition H₂O(l) → H₂O(g); molecular composition unchanged).</li>\r\n    <li><strong>Electrolysis of water into H₂ and O₂:</strong> <em>Chemical Change</em> (chemical decomposition 2H₂O(l) → 2H₂(g) + O₂(g); new substances formed).</li>\r\n    <li><strong>Dissolving common salt in water:</strong> <em>Physical Change</em> (hydration of Na⁺ and Cl⁻ ions; salt can be recovered completely by evaporation).</li>\r\n    <li><strong>Making a fruit salad with raw fruits:</strong> <em>Physical Change</em> (mechanical cutting and mixing; no chemical reaction occurs).</li>\r\n    <li><strong>Burning of paper and wood:</strong> <em>Chemical Change</em> (combustion reaction producing CO₂, H₂O vapour, ash, and heat/light; irreversible).</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct identification of all 4 physical changes with reason</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct identification of all 4 chemical changes with chemical reason</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_in_7')\">\r\n      <div class=\"q-num\">Page 24 — Q2</div>\r\n      <div class=\"q-text\">Try segregating the things around you as pure substances or mixtures.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Classification of Everyday Materials:</strong>\r\n  <ul>\r\n    <li><strong>Pure Substances:</strong>\r\n      <ul>\r\n        <li><em>Elements:</em> Copper wire, aluminium foil, iron nails, gold ring (24 karat), diamond (carbon).</li>\r\n        <li><em>Compounds:</em> Distilled water (H₂O), table sugar (sucrose C₁₂H₂₂O₁₁), baking soda (NaHCO₃), common salt (NaCl).</li>\r\n      </ul>\r\n    </li>\r\n    <li><strong>Mixtures:</strong>\r\n      <ul>\r\n        <li><em>Homogeneous Mixtures:</em> Tap water, air, vinegar, brass door handles, stainless steel utensils.</li>\r\n        <li><em>Heterogeneous Mixtures:</em> Milk, soil, concrete, muddy water, aerated soft drinks, vegetable soup, paint.</li>\r\n      </ul>\r\n    </li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing at least 4 valid pure substances (elements and compounds)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing at least 4 valid mixtures (homogeneous and heterogeneous)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q2_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">Which separation techniques will you apply for the separation of the following?<br>(a) Sodium chloride from its solution in water.<br>(b) Ammonium chloride from a mixture containing sodium chloride and ammonium chloride.<br>(c) Small pieces of metal in the engine oil of a car.<br>(d) Different pigments from an extract of flower petals.<br>(e) Butter from curd.<br>(f) Oil from water.<br>(g) Tea leaves from tea.<br>(h) Iron pins from sand.<br>(i) Wheat grains from husk.<br>(j) Fine mud particles suspended in water.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Techniques & Principles:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Mixture</th><th>Appropriate Separation Technique</th><th>Scientific Principle</th></tr>\r\n    <tr><td><strong>(a) Sodium chloride from aqueous solution</strong></td><td><strong>Evaporation / Distillation</strong></td><td>Water (solvent) evaporates at 100°C leaving non-volatile solid NaCl residue.</td></tr>\r\n    <tr><td><strong>(b) NH₄Cl from NaCl + NH₄Cl</strong></td><td><strong>Sublimation</strong></td><td>NH₄Cl sublimes directly from solid to gas upon heating, leaving non-sublimable NaCl behind.</td></tr>\r\n    <tr><td><strong>(c) Small metal pieces in car engine oil</strong></td><td><strong>Filtration / Magnetic separation</strong></td><td>Solid insoluble metal particles are retained on filter or attracted by magnet.</td></tr>\r\n    <tr><td><strong>(d) Flower petal pigments</strong></td><td><strong>Chromatography (Paper chromatography)</strong></td><td>Different pigments travel at different rates based on differential solubility and adsorption.</td></tr>\r\n    <tr><td><strong>(e) Butter from curd</strong></td><td><strong>Centrifugation (churning)</strong></td><td>Denser liquid phase is forced outward/downward while lighter fat (butter) collects at top.</td></tr>\r\n    <tr><td><strong>(f) Oil from water</strong></td><td><strong>Separating Funnel</strong></td><td>Immiscible liquids separate into two distinct layers based on density differences.</td></tr>\r\n    <tr><td><strong>(g) Tea leaves from tea</strong></td><td><strong>Filtration (using a tea strainer)</strong></td><td>Insoluble large tea leaves are retained by the mesh.</td></tr>\r\n    <tr><td><strong>(h) Iron pins from sand</strong></td><td><strong>Magnetic Separation</strong></td><td>Iron pins are ferromagnetic and strongly attracted by a magnet.</td></tr>\r\n    <tr><td><strong>(i) Wheat grains from husk</strong></td><td><strong>Winnowing</strong></td><td>Lighter husk particles are blown away by wind while heavier wheat grains fall vertically.</td></tr>\r\n    <tr><td><strong>(j) Fine mud suspended in water</strong></td><td><strong>Sedimentation, Decantation & Filtration (or Alum loading)</strong></td><td>Mud particles aggregate, settle down under gravity, and supernatant liquid is filtered.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Techniques (a) to (e) identified with principles</span><span class=\"marking-marks\">2½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Techniques (f) to (j) identified with principles</span><span class=\"marking-marks\">2½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">Write the steps you would use for making tea. Use the words solution, solvent, solute, dissolve, soluble, insoluble, filtrate and residue.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Recipe for Making Tea using Chemical Terminology:</strong>\r\n  <ol>\r\n    <li>Take a required volume of water in a saucepan. Water acts as the universal <strong>solvent</strong>. Heat it over a stove.</li>\r\n    <li>Add sugar to the hot solvent. Sugar acts as a <strong>solute</strong> which is highly <strong>soluble</strong> in water. Stir the liquid so that the sugar crystals <strong>dissolve</strong> completely to form a homogeneous <strong>solution</strong>.</li>\r\n    <li>Add tea leaves to the boiling solution. The water-soluble aromatic compounds and pigments dissolve into the liquid, while the solid fibrous part of the tea leaves remains completely <strong>insoluble</strong>.</li>\r\n    <li>Add milk (which is an emulsion) to this mixture and allow the concoction to boil.</li>\r\n    <li>Pour the boiling mixture through a fine mesh strainer into a cup.</li>\r\n    <li>The prepared tea that passes through the strainer into the cup is the <strong>filtrate</strong>.</li>\r\n    <li>The insoluble spent tea leaves left behind on the strainer mesh constitute the <strong>residue</strong>.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct contextual usage of solvent, solute, soluble, dissolve</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct contextual usage of solution, insoluble, filtrate, and residue</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">Pragya tested the solubility of three different substances at different temperatures and collected the following data (results are given in the following table, as grams of substance dissolved in 100 grams of water to form a saturated solution).<br>\r\n<table class=\"data-table\">\r\n<tr><th>Substance Dissolved</th><th>283 K</th><th>293 K</th><th>313 K</th><th>333 K</th><th>353 K</th></tr>\r\n<tr><td>Potassium nitrate</td><td>21</td><td>32</td><td>62</td><td>106</td><td>167</td></tr>\r\n<tr><td>Sodium chloride</td><td>36</td><td>36</td><td>36</td><td>37</td><td>37</td></tr>\r\n<tr><td>Potassium chloride</td><td>35</td><td>35</td><td>40</td><td>46</td><td>54</td></tr>\r\n<tr><td>Ammonium chloride</td><td>24</td><td>37</td><td>41</td><td>55</td><td>66</td></tr>\r\n</table><br>\r\n(a) What mass of potassium nitrate would be needed to produce a saturated solution of potassium nitrate in 50 grams of water at 313 K?<br>\r\n(b) Pragya makes a saturated solution of potassium chloride in water at 353 K and leaves the solution to cool at room temperature. What would she observe as the solution cools? Explain.<br>\r\n(c) Find the solubility of each salt at 293 K. Which salt has the highest solubility at this temperature?<br>\r\n(d) What is the effect of change of temperature on the solubility of a salt?</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) Potassium nitrate needed in 50 g water at 313 K:</strong><br>\r\n  From the table, solubility of potassium nitrate at 313 K = <span class=\"math\">62 g</span> per 100 g of water.<br>\r\n  Therefore, mass needed in 50 g of water = <span class=\"math\">(62 / 100) × 50 = 31 g</span>.<br>\r\n  <strong>Answer:</strong> <strong>31 grams</strong> of KNO₃ is needed.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Observation on cooling KCl solution from 353 K to room temperature (approx 293 K):</strong><br>\r\n  • At 353 K, 54 g of KCl dissolves in 100 g water.<br>\r\n  • At room temperature (293 K), only 35 g of KCl can remain dissolved in 100 g water.<br>\r\n  • As the saturated solution cools, the excess solute (<span class=\"math\">54 g - 35 g = 19 g</span> of KCl) can no longer remain in solution.<br>\r\n  <strong>Observation:</strong> Fine solid crystals of potassium chloride (KCl) will precipitate and separate out at the bottom of the beaker (crystallization).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(c) Solubility at 293 K:</strong><br>\r\n  • Potassium nitrate = <span class=\"math\">32 g / 100 g water</span><br>\r\n  • Sodium chloride = <span class=\"math\">36 g / 100 g water</span><br>\r\n  • Potassium chloride = <span class=\"math\">35 g / 100 g water</span><br>\r\n  • Ammonium chloride = <span class=\"math\">37 g / 100 g water</span><br>\r\n  <strong>Answer:</strong> <strong>Ammonium chloride</strong> has the highest solubility (37 g) at 293 K.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(d) Effect of temperature on solubility:</strong><br>\r\n  The solubility of most solid salts in water <strong>increases with an increase in temperature</strong> (evident from KNO₃, KCl, and NH₄Cl). For some salts like NaCl, the solubility remains practically constant with temperature increase.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Calculation (62/100)*50 = 31 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Precipitation of solid crystals due to decrease in solubility</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c) Comparison showing Ammonium chloride has highest solubility (37 g)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (d) Stating solubility of solid salts generally increases with temperature</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">Explain the following giving examples:<br>(a) Saturated solution<br>(b) Pure substance<br>(c) Colloid<br>(d) Suspension</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) Saturated Solution:</strong><br>\r\n  A solution in which no more quantity of solute can be dissolved at a given specified temperature is called a <em>saturated solution</em>. Any extra solute added remains undissolved at the bottom.<br>\r\n  <em>Example:</em> Dissolving table salt in water until excess salt crystals settle at the bottom and cannot dissolve further at 25°C.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Pure Substance:</strong><br>\r\n  A material composed of only one single type of atom or molecule with fixed, invariable chemical composition and definite physical constants (such as sharp melting and boiling points). It cannot be broken down into simpler constituents by any physical means.<br>\r\n  <em>Example:</em> Pure distilled water (H₂O), pure copper metal (Cu), sucrose (C₁₂H₂₂O₁₁).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(c) Colloid (Colloidal Solution):</strong><br>\r\n  A heterogeneous mixture in which solute particle sizes range between 1 nm and 1000 nm (intermediate between true solution and suspension). The particles are small enough not to settle under gravity, pass through filter paper, and scatter a beam of visible light showing the <strong>Tyndall effect</strong>.<br>\r\n  <em>Example:</em> Milk, gelatin, blood, ink, fog.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(d) Suspension:</strong><br>\r\n  A heterogeneous mixture containing large insoluble solid solute particles (&gt; 1000 nm) dispersed throughout the bulk of a liquid medium without dissolving. The particles are visible to the naked eye and settle down under gravity upon standing.<br>\r\n  <em>Example:</em> Chalk powder in water, muddy pond water, sand stirred in water.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and example of saturated solution</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and example of pure substance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition, Tyndall effect, and example of colloid</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition, particle size, and example of suspension</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">Classify each of the following as a homogeneous or heterogeneous mixture:<br>Soda water, wood, air, soil, vinegar, filtered tea.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Classification:</strong>\r\n  <ul>\r\n    <li><strong>Homogeneous Mixtures:</strong>\r\n      <ul>\r\n        <li><strong>Soda water:</strong> Clear solution of CO₂ gas uniformly dissolved in water under pressure.</li>\r\n        <li><strong>Air:</strong> Clean, dust-free air is a uniform gaseous solution of N₂, O₂, Ar, CO₂, etc.</li>\r\n        <li><strong>Vinegar:</strong> Homogeneous 5–8% aqueous solution of acetic acid in water.</li>\r\n        <li><strong>Filtered tea:</strong> Uniform clear liquid solution of soluble tea extracts, sugar, and water with no suspended particles.</li>\r\n      </ul>\r\n    </li>\r\n    <li><strong>Heterogeneous Mixtures:</strong>\r\n      <ul>\r\n        <li><strong>Wood:</strong> Natural composite material with visible grains, varying lignin, cellulose fibers, and sap channels.</li>\r\n        <li><strong>Soil:</strong> Complex non-uniform mixture containing sand, clay, humus, organic decay, and mineral fragments.</li>\r\n      </ul>\r\n    </li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Classifying soda water, air, vinegar, filtered tea as homogeneous</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Classifying wood and soil as heterogeneous</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">How would you confirm that a colourless liquid given to you is pure water?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Experimental Confirmation through Physical Constants:</strong><br>\r\n  Every pure chemical substance has fixed, sharp, and invariable physical boiling and freezing points at 1 atmosphere pressure.<br>\r\n  1. <strong>Boiling Point Determination:</strong> Heat a sample of the colourless liquid in a distillation apparatus with a sensitive thermometer placed in the vapour phase.<br>\r\n     • If the liquid boils sharply at <strong>exactly 100°C (373 K)</strong> at 1 atm without any temperature variation during phase transition, it confirms the liquid is pure water.<br>\r\n     • (If dissolved impurities like salts are present, the boiling point will elevate above 100°C).<br>\r\n  2. <strong>Freezing Point Determination:</strong> Cool the liquid. If it freezes sharply at <strong>exactly 0°C (273 K)</strong>, it proves purity.<br>\r\n  3. <strong>Evaporation Test:</strong> Evaporate a drop on a clean watch glass; pure water leaves absolutely <strong>zero solid residue</strong> behind.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Testing sharp boiling point at 100°C (373 K) at 1 atm</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Testing sharp freezing point at 0°C or zero residue on evaporation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">Which of the following materials fall in the category of a 'pure substance'?<br>(a) Ice, (b) Milk, (c) Iron, (d) Hydrochloric acid, (e) Calcium oxide, (f) Mercury, (g) Brick, (h) Wood, (i) Air.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Evaluation of Materials:</strong><br>\r\n  A pure substance is made of only one type of constituent particles (either an element or a chemical compound) with fixed chemical composition.<br>\r\n  • <strong>Pure Substances:</strong>\r\n    <ol>\r\n      <li><strong>Ice:</strong> Solid H₂O (chemical compound).</li>\r\n      <li><strong>Iron:</strong> Metallic Fe (chemical element).</li>\r\n      <li><strong>Hydrochloric acid (pure gas/compound HCl):</strong> Compound of hydrogen and chlorine (Note: Aqueous HCl solution is a mixture, but chemically pure HCl is a compound).</li>\r\n      <li><strong>Calcium oxide:</strong> Quicklime, CaO (chemical compound).</li>\r\n      <li><strong>Mercury:</strong> Liquid metallic element Hg (chemical element).</li>\r\n    </ol>\r\n  • <strong>Mixtures (Not pure substances):</strong>\r\n    <ul>\r\n      <li><strong>Milk:</strong> Emulsion mixture of water, fats, proteins, and lactose.</li>\r\n      <li><strong>Brick:</strong> Heterogeneous mixture of clay, sand, iron oxides, and minerals.</li>\r\n      <li><strong>Wood:</strong> Heterogeneous mixture of cellulose, lignin, resins, and moisture.</li>\r\n      <li><strong>Air:</strong> Gaseous mixture of nitrogen, oxygen, argon, carbon dioxide, etc.</li>\r\n    </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying Ice, Iron, Calcium oxide, Mercury as pure substances</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying Milk, Brick, Wood, Air as mixtures</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">Identify the solutions among the following mixtures:<br>(a) Soil<br>(b) Sea water<br>(c) Air<br>(d) Coal<br>(e) Soda water</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis:</strong><br>\r\n  A <strong>solution</strong> is strictly defined as a <em>homogeneous mixture</em> of two or more substances.<br>\r\n  • <strong>Solutions:</strong>\r\n    <ol>\r\n      <li><strong>Sea water:</strong> Homogeneous liquid solution of multiple soluble mineral salts (NaCl, MgCl₂, etc.) dissolved in water.</li>\r\n      <li><strong>Air:</strong> Homogeneous gaseous solution consisting mainly of nitrogen (solvent) and oxygen, argon, carbon dioxide (solutes).</li>\r\n      <li><strong>Soda water:</strong> Homogeneous liquid solution of carbon dioxide gas dissolved in water.</li>\r\n    </ol>\r\n  • <strong>Not Solutions:</strong>\r\n    <ul>\r\n      <li><strong>Soil:</strong> Heterogeneous solid mixture.</li>\r\n      <li><strong>Coal:</strong> Heterogeneous carbonaceous mineral rock/mixture.</li>\r\n    </ul>\r\n</div>\r\n<p><strong>Final Answer:</strong> <strong>(b) Sea water, (c) Air, and (e) Soda water</strong> are true solutions.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying Sea water, Air, and Soda water as solutions</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining why Soil and Coal are not solutions</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">Which of the following will show 'Tyndall effect'?<br>(a) Salt solution<br>(b) Milk<br>(c) Copper sulphate solution<br>(d) Starch solution</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Principle:</strong><br>\r\n  The <strong>Tyndall effect</strong> is the scattering of a visible light beam by colloidal particles whose diameter is comparable to the wavelength of light (1 nm to 1000 nm). True solutions have particles smaller than 1 nm and cannot scatter light.<br><br>\r\n  • <strong>(b) Milk:</strong> A colloid (emulsion of liquid butterfat globules in water). <strong>Shows Tyndall effect.</strong><br>\r\n  • <strong>(d) Starch solution:</strong> A colloidal sol of starch macromolecules dispersed in water. <strong>Shows Tyndall effect.</strong><br>\r\n  • <strong>(a) Salt solution</strong> and <strong>(c) Copper sulphate solution:</strong> These are true homogeneous solutions (< 1 nm particles); light passes straight through without scattering.\r\n</div>\r\n<p><strong>Final Answer:</strong> <strong>(b) Milk</strong> and <strong>(d) Starch solution</strong> will show the Tyndall effect.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying (b) Milk and (d) Starch solution correctly</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining colloidal particle size scattering light vs true solutions</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">Classify the following into elements, compounds and mixtures:<br>(a) Sodium, (b) Soil, (c) Sugar solution, (d) Silver, (e) Calcium carbonate, (f) Tin, (g) Silicon, (h) Coal, (i) Air, (j) Soap, (k) Methane, (l) Carbon dioxide, (m) Blood.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Complete Classification:</strong>\r\n  <ul>\r\n    <li><strong>Elements (Fundamental substances of one type of atom):</strong><br>\r\n      • <strong>Sodium (Na)</strong><br>\r\n      • <strong>Silver (Ag)</strong><br>\r\n      • <strong>Tin (Sn)</strong><br>\r\n      • <strong>Silicon (Si)</strong>\r\n    </li>\r\n    <li><strong>Compounds (Chemically combined in fixed proportions):</strong><br>\r\n      • <strong>Calcium carbonate (CaCO₃)</strong><br>\r\n      • <strong>Soap (Sodium stearate C₁₇H₃₅COONa)</strong><br>\r\n      • <strong>Methane (CH₄)</strong><br>\r\n      • <strong>Carbon dioxide (CO₂)</strong>\r\n    </li>\r\n    <li><strong>Mixtures (Physically combined in variable proportions):</strong><br>\r\n      • <strong>Soil</strong> (heterogeneous mixture)<br>\r\n      • <strong>Sugar solution</strong> (homogeneous mixture)<br>\r\n      • <strong>Coal</strong> (complex carbon mixture)<br>\r\n      • <strong>Air</strong> (homogeneous gas mixture)<br>\r\n      • <strong>Blood</strong> (colloidal heterogeneous mixture)\r\n    </li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correctly listing all 4 elements</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correctly listing all 4 compounds</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correctly listing all 5 mixtures</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q2_ex_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_ex_11')\">\r\n      <div class=\"q-num\">Exercise — Q11</div>\r\n      <div class=\"q-text\">Which of the following are chemical changes?<br>(a) Growth of a plant<br>(b) Rusting of iron<br>(c) Mixing of iron filings and sand<br>(d) Cooking of food<br>(e) Digestion of food<br>(f) Freezing of water<br>(g) Burning of a candle</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis of Changes:</strong>\r\n  <ul>\r\n    <li><strong>(a) Growth of a plant:</strong> <em>Chemical Change</em> (Photosynthesis, cellular respiration, irreversible synthesis of organic matter).</li>\r\n    <li><strong>(b) Rusting of iron:</strong> <em>Chemical Change</em> (Oxidation of iron to hydrated ferric oxide Fe₂O₃·xH₂O).</li>\r\n    <li><strong>(c) Mixing of iron filings and sand:</strong> <em>Physical Change</em> (No reaction; iron can be separated with a magnet).</li>\r\n    <li><strong>(d) Cooking of food:</strong> <em>Chemical Change</em> (Denaturation of proteins, breakdown of starch; new flavours/compounds formed, irreversible).</li>\r\n    <li><strong>(e) Digestion of food:</strong> <em>Chemical Change</em> (Enzymatic hydrolysis of complex polymers into simple monomers).</li>\r\n    <li><strong>(f) Freezing of water:</strong> <em>Physical Change</em> (Phase transition liquid → solid ice; molecular formula H₂O is unchanged).</li>\r\n    <li><strong>(g) Burning of a candle:</strong> <em>Both Chemical and Physical Change</em> (Combustion of molten wax into CO₂ and H₂O is a chemical change, while melting of solid wax is a physical change. As burning is involved, it is classified as a <strong>chemical change</strong>).</li>\r\n  </ul>\r\n</div>\r\n<p><strong>Final Answer:</strong> The chemical changes are: <strong>(a) Growth of a plant, (b) Rusting of iron, (d) Cooking of food, (e) Digestion of food, and (g) Burning of a candle.</strong></p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correctly identifying (a), (b), (d), (e), (g) as chemical changes</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Scientific justifications for digestion/combustion/rusting</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 2</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Colloidal Applications in Daily Life:</strong> A teacher shines a laser pointer through three beakers: Beaker A contains aqueous NaCl solution, Beaker B contains milk diluted with water, and Beaker C contains ferric hydroxide sol.<br>(a) In which beaker(s) will the path of the light beam become illuminated? Name this optical phenomenon.<br>(b) Why do the colloidal particles not settle down under gravity like a suspension?<br>(c) What happens if an electrolyte (like concentrated NaCl) is added to Beaker C?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> The path will become illuminated in <strong>Beakers B and C</strong>. This phenomenon is called the <strong>Tyndall Effect</strong>.<br><strong>(b)</strong> Colloidal particles are held in continuous random zigzag motion (<strong>Brownian motion</strong>) caused by unbalanced bombardment of dispersion medium molecules, which opposes gravity and prevents settling. They also carry like electrical charges that cause mutual repulsion.<br><strong>(c)</strong> Addition of an electrolyte neutralizes the surface charge on the colloidal particles, causing them to aggregate and precipitate out — a process called <strong>coagulation (flocculation)</strong>.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why is an alloy considered a mixture even though its constituent metals are completely fused and cannot be separated by physical filtration?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">An alloy (such as brass = 70% Cu + 30% Zn) is classified as a mixture because: (1) It retains and displays the individual properties of its constituent metals (e.g., electrical conductivity and chemical reactivity of Cu and Zn), (2) Its composition can vary within a range (e.g., bronze can have varying Sn percentages), and (3) It does not have a single chemical formula representing fixed stoichiometric chemical bonding.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(1)\">← Chapter 1</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\">Chapter 3 →</button>\r\n  </div>\r\n</section>","3":"<section class=\"chapter-section\" id=\"ch3\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">3</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 3: Atoms and Molecules</h2>\r\n      <p>Laws of Chemical Combination, Chemical Formulae, Molecular Mass & Mole Concept — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 32)</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_1')\">\r\n      <div class=\"q-num\">Page 32 — Q1</div>\r\n      <div class=\"q-text\">In a reaction, 5.3 g of sodium carbonate reacted with 6 g of ethanoic acid. The products were 2.2 g of carbon dioxide, 0.9 g water and 8.2 g of sodium ethanoate. Show that these observations are in agreement with the law of conservation of mass.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Chemical Reaction:</strong><br>\r\n  <span class=\"math\">Sodium carbonate + Ethanoic acid ⟶ Sodium ethanoate + Carbon dioxide + Water</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Total Mass of Reactants:</strong><br>\r\n  • Mass of sodium carbonate = <span class=\"math\">5.3 g</span><br>\r\n  • Mass of ethanoic acid = <span class=\"math\">6.0 g</span><br>\r\n  <span class=\"math\">Total mass of reactants = 5.3 g + 6.0 g = 11.3 g</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Total Mass of Products:</strong><br>\r\n  • Mass of sodium ethanoate = <span class=\"math\">8.2 g</span><br>\r\n  • Mass of carbon dioxide = <span class=\"math\">2.2 g</span><br>\r\n  • Mass of water = <span class=\"math\">0.9 g</span><br>\r\n  <span class=\"math\">Total mass of products = 8.2 g + 2.2 g + 0.9 g = 11.3 g</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Conclusion:</strong><br>\r\n  Since <span class=\"math\">Total mass of reactants (11.3 g) = Total mass of products (11.3 g)</span>, mass is neither created nor destroyed during the chemical change. Hence, these experimental observations completely agree with the <strong>Law of Conservation of Mass</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Summing mass of reactants = 5.3 + 6.0 = 11.3 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Summing mass of products = 8.2 + 2.2 + 0.9 = 11.3 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Equating reactant mass to product mass and stating Law of Conservation of Mass</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_2')\">\r\n      <div class=\"q-num\">Page 32 — Q2</div>\r\n      <div class=\"q-text\">Hydrogen and oxygen combine in the ratio of 1:8 by mass to form water. What mass of oxygen gas would be required to react completely with 3 g of hydrogen gas?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  Mass ratio of Hydrogen to Oxygen in water (<span class=\"math\">H₂O</span>) = <span class=\"math\">1 : 8</span>.<br>\r\n  This means <span class=\"math\">1 g</span> of hydrogen reacts completely with <span class=\"math\">8 g</span> of oxygen.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  Mass of oxygen required for <span class=\"math\">3 g</span> of hydrogen:<br>\r\n  <span class=\"math\">Mass of Oxygen = 3 × 8 = 24 g</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Exactly <strong>24 grams</strong> of oxygen gas is required to react completely with 3 g of hydrogen gas, in accordance with the <strong>Law of Definite Proportions</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating ratio by mass 1:8 according to Law of Definite Proportions</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation: 3 × 8 = 24 g with final answer</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_3')\">\r\n      <div class=\"q-num\">Page 32 — Q3</div>\r\n      <div class=\"q-text\">Which postulate of Dalton's atomic theory is the result of the law of conservation of mass?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Postulate:</strong><br>\r\n  <em>\"Atoms are indivisible particles, which cannot be created or destroyed in a chemical reaction.\"</em><br>\r\n  This postulate directly accounts for and proves the <strong>Law of Conservation of Mass</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Exact quotation/statement of Dalton's indivisibility and indestructible atom postulate</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_4')\">\r\n      <div class=\"q-num\">Page 32 — Q4</div>\r\n      <div class=\"q-text\">Which postulate of Dalton's atomic theory can explain the law of definite proportions?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Postulate:</strong><br>\r\n  <em>\"The relative number and kinds of atoms are constant in a given compound.\"</em><br>\r\n  (Also stated as: <em>Atoms combine in the ratio of small whole numbers to form compounds</em>).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Statement of constant relative number and kinds of atoms in a compound</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 35)</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_5')\">\r\n      <div class=\"q-num\">Page 35 — Q1</div>\r\n      <div class=\"q-text\">Define the atomic mass unit.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition of Unified Atomic Mass Unit (u):</strong><br>\r\n  One atomic mass unit is defined as a mass exactly equal to <strong>one-twelfth (1/12th) of the mass of one atom of carbon-12 (<span class=\"math\">¹²C</span>)</strong> isotope at rest.<br>\r\n  <span class=\"math\">1 u = (1/12) × Mass of one ¹²C atom ≈ 1.6605 × 10⁻²⁴ g = 1.6605 × 10⁻²⁷ kg</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition referencing 1/12th the mass of one carbon-12 atom</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Symbol 'u' and numerical equivalent value</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_6')\">\r\n      <div class=\"q-num\">Page 35 — Q2</div>\r\n      <div class=\"q-text\">Why is it not possible to see an atom with naked eyes?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Reasons:</strong><br>\r\n  1. <strong>Extremely Submicroscopic Dimensions:</strong> Atoms are unimaginably tiny. The atomic radius of a typical atom (like hydrogen) is about <span class=\"math\">10⁻¹⁰ m</span> (0.1 nanometre).<br>\r\n  2. <strong>Limit of Resolution of Human Eye:</strong> The human eye cannot resolve any object smaller than approximately <span class=\"math\">0.1 mm</span> (<span class=\"math\">10⁻⁴ m</span>).<br>\r\n  3. Since the size of an atom is about a million times smaller than the resolving limit of the human retina, an individual atom cannot reflect visible light to be seen with naked eyes.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Atomic size scale (~10⁻¹⁰ m / 0.1 nm)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Limit of human eye resolution (~10⁻⁴ m / 0.1 mm)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 39)</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_7')\">\r\n      <div class=\"q-num\">Page 39 — Q1</div>\r\n      <div class=\"q-text\">Write down the formulae of:<br>(i) Sodium oxide<br>(ii) Aluminium chloride<br>(iii) Sodium sulphide<br>(iv) Magnesium hydroxide</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Derivation by Criss-Cross Valency Method:</strong>\r\n  <ul>\r\n    <li><strong>(i) Sodium oxide:</strong><br>\r\n      Symbols: <span class=\"math\">Na</span> and <span class=\"math\">O</span>; Valencies: <span class=\"math\">Na = +1, O = -2</span>.<br>\r\n      Criss-cross: <span class=\"math\">Na₂O₁</span> ⟹ <strong>Na₂O</strong>.\r\n    </li>\r\n    <li><strong>(ii) Aluminium chloride:</strong><br>\r\n      Symbols: <span class=\"math\">Al</span> and <span class=\"math\">Cl</span>; Valencies: <span class=\"math\">Al = +3, Cl = -1</span>.<br>\r\n      Criss-cross: <span class=\"math\">Al₁Cl₃</span> ⟹ <strong>AlCl₃</strong>.\r\n    </li>\r\n    <li><strong>(iii) Sodium sulphide:</strong><br>\r\n      Symbols: <span class=\"math\">Na</span> and <span class=\"math\">S</span>; Valencies: <span class=\"math\">Na = +1, S = -2</span>.<br>\r\n      Criss-cross: <span class=\"math\">Na₂S₁</span> ⟹ <strong>Na₂S</strong>.\r\n    </li>\r\n    <li><strong>(iv) Magnesium hydroxide:</strong><br>\r\n      Symbols: <span class=\"math\">Mg</span> and <span class=\"math\">OH</span>; Valencies: <span class=\"math\">Mg = +2, OH = -1</span>.<br>\r\n      Criss-cross: <span class=\"math\">Mg₁(OH)₂</span> ⟹ <strong>Mg(OH)₂</strong>.\r\n    </li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Na₂O</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) AlCl₃</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Na₂S</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(iv) Mg(OH)₂ with brackets around polyatomic ion</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_8')\">\r\n      <div class=\"q-num\">Page 39 — Q2</div>\r\n      <div class=\"q-text\">Write down the names of compounds represented by the following formulae:<br>(i) Al₂(SO₄)₃<br>(ii) CaCl₂<br>(iii) K₂SO₄<br>(iv) KNO₃<br>(v) CaCO₃</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Chemical Nomenclature:</strong>\r\n  <ul>\r\n    <li><strong>(i) Al₂(SO₄)₃:</strong> <strong>Aluminium sulphate</strong> (Cation: Al³⁺, Anion: SO₄²⁻)</li>\r\n    <li><strong>(ii) CaCl₂:</strong> <strong>Calcium chloride</strong> (Cation: Ca²⁺, Anion: Cl⁻)</li>\r\n    <li><strong>(iii) K₂SO₄:</strong> <strong>Potassium sulphate</strong> (Cation: K⁺, Anion: SO₄²⁻)</li>\r\n    <li><strong>(iv) KNO₃:</strong> <strong>Potassium nitrate</strong> (Cation: K⁺, Anion: NO₃⁻)</li>\r\n    <li><strong>(v) CaCO₃:</strong> <strong>Calcium carbonate</strong> (Cation: Ca²⁺, Anion: CO₃²⁻)</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct names for (i) Aluminium sulphate and (ii) Calcium chloride</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct names for (iii) Potassium sulphate and (iv) Potassium nitrate</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct name for (v) Calcium carbonate</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_9')\">\r\n      <div class=\"q-num\">Page 39 — Q3</div>\r\n      <div class=\"q-text\">What is meant by the term chemical formula?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  A <strong>chemical formula</strong> is a symbolic representation of the composition of a compound.<br>\r\n  It indicates:\r\n  <ol>\r\n    <li>The types of elements present in the compound (represented by chemical symbols).</li>\r\n    <li>The exact number of atoms of each element present in one molecule or formula unit of that compound (represented by numerical subscripts).</li>\r\n  </ol>\r\n  <em>Example:</em> <span class=\"math\">H₂SO₄</span> represents one molecule of sulphuric acid consisting of 2 atoms of Hydrogen, 1 atom of Sulphur, and 4 atoms of Oxygen.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition as symbolic representation of composition of a compound</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Significance (types of elements and definite atom proportions) with example</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_10')\">\r\n      <div class=\"q-num\">Page 39 — Q4</div>\r\n      <div class=\"q-text\">How many atoms are present in a:<br>(i) H₂S molecule and<br>(ii) PO₄³⁻ ion?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(i) In one H₂S molecule:</strong><br>\r\n  • Hydrogen atoms = 2<br>\r\n  • Sulphur atoms = 1<br>\r\n  <span class=\"math\">Total number of atoms = 2 + 1 = 3 atoms</span> (Triatomic molecule).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(ii) In one PO₄³⁻ (phosphate) ion:</strong><br>\r\n  • Phosphorus atoms = 1<br>\r\n  • Oxygen atoms = 4<br>\r\n  <span class=\"math\">Total number of atoms = 1 + 4 = 5 atoms</span> (Polyatomic pentatomic ion).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">H₂S: 2 + 1 = 3 atoms</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">PO₄³⁻: 1 + 4 = 5 atoms</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 40)</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_in_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_11')\">\r\n      <div class=\"q-num\">Page 40 — Q1</div>\r\n      <div class=\"q-text\">Calculate the molecular masses of H₂, O₂, Cl₂, CO₂, CH₄, C₂H₆, C₂H₄, NH₃, CH₃OH.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Atomic Masses:</strong> H = 1 u, C = 12 u, N = 14 u, O = 16 u, Cl = 35.5 u.<br><br>\r\n  <strong>Calculations:</strong>\r\n  <ul>\r\n    <li><strong>H₂:</strong> <span class=\"math\">2 × 1 = 2 u</span></li>\r\n    <li><strong>O₂:</strong> <span class=\"math\">2 × 16 = 32 u</span></li>\r\n    <li><strong>Cl₂:</strong> <span class=\"math\">2 × 35.5 = 71 u</span></li>\r\n    <li><strong>CO₂:</strong> <span class=\"math\">12 + 2 × 16 = 12 + 32 = 44 u</span></li>\r\n    <li><strong>CH₄:</strong> <span class=\"math\">12 + 4 × 1 = 16 u</span></li>\r\n    <li><strong>C₂H₆:</strong> <span class=\"math\">2 × 12 + 6 × 1 = 24 + 6 = 30 u</span></li>\r\n    <li><strong>C₂H₄:</strong> <span class=\"math\">2 × 12 + 4 × 1 = 24 + 4 = 28 u</span></li>\r\n    <li><strong>NH₃:</strong> <span class=\"math\">14 + 3 × 1 = 17 u</span></li>\r\n    <li><strong>CH₃OH:</strong> <span class=\"math\">12 + 3 × 1 + 16 + 1 = 32 u</span></li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculations for H₂, O₂, Cl₂, CO₂</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculations for CH₄, C₂H₆, C₂H₄</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculations for NH₃ and CH₃OH</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_12')\">\r\n      <div class=\"q-num\">Page 40 — Q2</div>\r\n      <div class=\"q-text\">Calculate the formula unit masses of ZnO, Na₂O, K₂CO₃, given atomic masses of Zn = 65 u, Na = 23 u, K = 39 u, C = 12 u, and O = 16 u.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>1. ZnO (Zinc oxide):</strong><br>\r\n  <span class=\"math\">Formula unit mass = Mass of Zn + Mass of O = 65 + 16 = 81 u</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>2. Na₂O (Sodium oxide):</strong><br>\r\n  <span class=\"math\">Formula unit mass = 2 × (Mass of Na) + Mass of O = 2 × 23 + 16 = 46 + 16 = 62 u</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>3. K₂CO₃ (Potassium carbonate):</strong><br>\r\n  <span class=\"math\">Formula unit mass = 2 × (Mass of K) + Mass of C + 3 × (Mass of O)</span><br>\r\n  <span class=\"math\">= 2 × 39 + 12 + 3 × 16 = 78 + 12 + 48 = 138 u</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">ZnO = 81 u</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Na₂O = 62 u</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">K₂CO₃ = 138 u</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 42)</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_in_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_13')\">\r\n      <div class=\"q-num\">Page 42 — Q1</div>\r\n      <div class=\"q-text\">If one mole of carbon atoms weighs 12 grams, what is the mass (in grams) of 1 atom of carbon?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Mass of 1 mole of carbon atoms = <span class=\"math\">12 g</span><br>\r\n  • 1 mole contains Avogadro's number (<span class=\"math\">N_A</span>) of atoms = <span class=\"math\">6.022 × 10²³ atoms</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">Mass of 1 atom = (Mass of 1 mole) / N_A</span><br>\r\n  <span class=\"math\">Mass of 1 atom = 12 / (6.022 × 10²³) ≈ 1.993 × 10⁻²³ g</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The mass of one atom of carbon is <strong>1.993 × 10⁻²³ g</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula: Mass of 1 atom = Molar mass / N_A</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution and calculation: 1.993 × 10⁻²³ g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_in_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_in_14')\">\r\n      <div class=\"q-num\">Page 42 — Q2</div>\r\n      <div class=\"q-text\">Which has more number of atoms, 100 grams of sodium or 100 grams of iron? (given, atomic mass of Na = 23 u, Fe = 56 u)</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong> <span class=\"math\">Number of atoms = (Given Mass / Molar Mass) × N_A</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>1. For 100 g Sodium (Na):</strong><br>\r\n  <span class=\"math\">Moles of Na = 100 / 23 ≈ 4.348 moles</span><br>\r\n  <span class=\"math\">Atoms of Na = 4.348 × N_A = 4.348 × 6.022 × 10²³ ≈ 2.618 × 10²⁴ atoms</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>2. For 100 g Iron (Fe):</strong><br>\r\n  <span class=\"math\">Moles of Fe = 100 / 56 ≈ 1.786 moles</span><br>\r\n  <span class=\"math\">Atoms of Fe = 1.786 × N_A = 1.786 × 6.022 × 10²³ ≈ 1.075 × 10²⁴ atoms</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Conclusion:</strong><br>\r\n  Since 4.348 moles &gt; 1.786 moles, <strong>100 grams of sodium has significantly more atoms</strong> than 100 grams of iron (approximately 2.44 times more).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of moles/atoms of Na = 4.348 N_A ≈ 2.618 × 10²⁴</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of moles/atoms of Fe = 1.786 N_A ≈ 1.075 × 10²⁴</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison and concluding Sodium has more atoms</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">A 0.24 g sample of compound of oxygen and boron was found by analysis to contain 0.096 g of boron and 0.144 g of oxygen. Calculate the percentage composition of the compound by weight.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Mass of compound = <span class=\"math\">0.24 g</span><br>\r\n  • Mass of boron = <span class=\"math\">0.096 g</span><br>\r\n  • Mass of oxygen = <span class=\"math\">0.144 g</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Percentage of Boron:</strong><br>\r\n  <span class=\"math\">% Boron = (Mass of Boron / Mass of Compound) × 100</span><br>\r\n  <span class=\"math\">% Boron = (0.096 / 0.24) × 100 = 40%</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Percentage of Oxygen:</strong><br>\r\n  <span class=\"math\">% Oxygen = (Mass of Oxygen / Mass of Compound) × 100</span><br>\r\n  <span class=\"math\">% Oxygen = (0.144 / 0.24) × 100 = 60%</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Boron = <strong>40%</strong>, Oxygen = <strong>60%</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">% Boron = (0.096 / 0.24) × 100 = 40%</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">% Oxygen = (0.144 / 0.24) × 100 = 60%</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">When 3.0 g of carbon is burnt in 8.00 g oxygen, 11.00 g of carbon dioxide is produced. What mass of carbon dioxide will be formed when 3.00 g of carbon is burnt in 50.00 g of oxygen? Which law of chemical combination will govern your answer?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Step 1: Determine Combining Ratio:</strong><br>\r\n  <span class=\"math\">C + O₂ ⟶ CO₂</span><br>\r\n  <span class=\"math\">3 g C + 8 g O₂ ⟶ 11 g CO₂</span><br>\r\n  The mass ratio of Carbon to Oxygen in CO₂ is strictly <span class=\"math\">3 : 8</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Burning 3.00 g Carbon in 50.00 g Oxygen:</strong><br>\r\n  • 3.00 g of carbon can react with only <strong>8.00 g</strong> of oxygen.<br>\r\n  • Carbon is the <strong>limiting reactant</strong>.<br>\r\n  • The remaining oxygen (<span class=\"math\">50.00 g - 8.00 g = 42.00 g</span>) will remain unreacted as excess.<br>\r\n  • Therefore, the mass of carbon dioxide produced will still be: <span class=\"math\">3.00 g + 8.00 g = 11.00 g</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Governing Law:</strong><br>\r\n  This is governed by the <strong>Law of Definite Proportions (or Law of Constant Composition)</strong>, which states that in a chemical substance, the elements are always present in definite proportions by mass.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying mass of CO₂ formed = 11.00 g with 42 g excess O₂</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating Law of Definite Proportions and its definition</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">What are polyatomic ions? Give examples.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  A <strong>polyatomic ion</strong> is a charged group of covalently bonded atoms that behaves as a single unit with a net positive or negative electrical charge.<br><br>\r\n  <strong>Examples:</strong>\r\n  <ul>\r\n    <li>Ammonium ion: <span class=\"math\">NH₄⁺</span> (Valency = +1)</li>\r\n    <li>Hydroxide ion: <span class=\"math\">OH⁻</span> (Valency = -1)</li>\r\n    <li>Nitrate ion: <span class=\"math\">NO₃⁻</span> (Valency = -1)</li>\r\n    <li>Sulphate ion: <span class=\"math\">SO₄²⁻</span> (Valency = -2)</li>\r\n    <li>Carbonate ion: <span class=\"math\">CO₃²⁻</span> (Valency = -2)</li>\r\n    <li>Phosphate ion: <span class=\"math\">PO₄³⁻</span> (Valency = -3)</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of polyatomic ion with net charge</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">At least two valid examples with formula and charge</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">Write the chemical formulae of the following:<br>(a) Magnesium chloride<br>(b) Calcium oxide<br>(c) Copper nitrate<br>(d) Aluminium chloride<br>(e) Calcium carbonate</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula Derivation:</strong>\r\n  <ul>\r\n    <li><strong>(a) Magnesium chloride:</strong> Mg²⁺ and Cl⁻ ⟹ <strong>MgCl₂</strong></li>\r\n    <li><strong>(b) Calcium oxide:</strong> Ca²⁺ and O²⁻ ⟹ Ca₂O₂ ⟹ <strong>CaO</strong></li>\r\n    <li><strong>(c) Copper(II) nitrate:</strong> Cu²⁺ and NO₃⁻ ⟹ <strong>Cu(NO₃)₂</strong></li>\r\n    <li><strong>(d) Aluminium chloride:</strong> Al³⁺ and Cl⁻ ⟹ <strong>AlCl₃</strong></li>\r\n    <li><strong>(e) Calcium carbonate:</strong> Ca²⁺ and CO₃²⁻ ⟹ Ca₂(CO₃)₂ ⟹ <strong>CaCO₃</strong></li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">MgCl₂</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">CaO</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cu(NO₃)₂</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">AlCl₃</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">CaCO₃</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">Give the names of the elements present in the following compounds:<br>(a) Quick lime<br>(b) Hydrogen bromide<br>(c) Baking powder<br>(d) Potassium sulphate</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis of Elements:</strong>\r\n  <ul>\r\n    <li><strong>(a) Quick lime (Calcium oxide, CaO):</strong> <strong>Calcium (Ca)</strong> and <strong>Oxygen (O)</strong>.</li>\r\n    <li><strong>(b) Hydrogen bromide (HBr):</strong> <strong>Hydrogen (H)</strong> and <strong>Bromine (Br)</strong>.</li>\r\n    <li><strong>(c) Baking powder (Sodium hydrogen carbonate, NaHCO₃ + tartaric acid):</strong> Main active compound NaHCO₃ contains <strong>Sodium (Na), Hydrogen (H), Carbon (C), and Oxygen (O)</strong>.</li>\r\n    <li><strong>(d) Potassium sulphate (K₂SO₄):</strong> <strong>Potassium (K), Sulphur (S), and Oxygen (O)</strong>.</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Quick lime: Calcium, Oxygen</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Hydrogen bromide: Hydrogen, Bromine</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Baking powder: Sodium, Hydrogen, Carbon, Oxygen</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Potassium sulphate: Potassium, Sulphur, Oxygen</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">Calculate the molar mass of the following substances:<br>(a) Ethyne, C₂H₂<br>(b) Sulphur molecule, S₈<br>(c) Phosphorus molecule, P₄ (Atomic mass of phosphorus = 31)<br>(d) Hydrochloric acid, HCl<br>(e) Nitric acid, HNO₃</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Calculations (Molar Mass in g/mol):</strong>\r\n  <ul>\r\n    <li><strong>(a) Ethyne (C₂H₂):</strong> <span class=\"math\">2 × 12 + 2 × 1 = 24 + 2 = 26 g/mol</span></li>\r\n    <li><strong>(b) Sulphur molecule (S₈):</strong> <span class=\"math\">8 × 32 = 256 g/mol</span></li>\r\n    <li><strong>(c) Phosphorus molecule (P₄):</strong> <span class=\"math\">4 × 31 = 124 g/mol</span></li>\r\n    <li><strong>(d) Hydrochloric acid (HCl):</strong> <span class=\"math\">1 + 35.5 = 36.5 g/mol</span></li>\r\n    <li><strong>(e) Nitric acid (HNO₃):</strong> <span class=\"math\">1 + 14 + 3 × 16 = 1 + 14 + 48 = 63 g/mol</span></li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) C₂H₂ = 26 g/mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) S₈ = 256 g/mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) P₄ = 124 g/mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) HCl = 36.5 g/mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) HNO₃ = 63 g/mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">What is the mass of:<br>(a) 1 mole of nitrogen atoms?<br>(b) 4 moles of aluminium atoms (Atomic mass of aluminium = 27)?<br>(c) 10 moles of sodium sulphite (Na₂SO₃)?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong> <span class=\"math\">Mass = Number of moles × Molar mass</span><br><br>\r\n  • <strong>(a) 1 mole of Nitrogen atoms (N):</strong><br>\r\n    <span class=\"math\">Mass = 1 × 14 = 14 g</span>.<br><br>\r\n  • <strong>(b) 4 moles of Aluminium atoms (Al):</strong><br>\r\n    <span class=\"math\">Mass = 4 × 27 = 108 g</span>.<br><br>\r\n  • <strong>(c) 10 moles of Sodium sulphite (Na₂SO₃):</strong><br>\r\n    Molar mass of Na₂SO₃ = <span class=\"math\">2 × 23 + 32 + 3 × 16 = 46 + 32 + 48 = 126 g/mol</span>.<br>\r\n    <span class=\"math\">Mass = 10 × 126 = 1260 g</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) 14 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) 108 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Molar mass 126 g/mol ⟹ 1260 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">Convert into mole:<br>(a) 12 g of oxygen gas<br>(b) 20 g of water<br>(c) 22 g of carbon dioxide</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong> <span class=\"math\">Number of moles (n) = Given mass (m) / Molar mass (M)</span><br><br>\r\n  • <strong>(a) 12 g of Oxygen gas (O₂):</strong><br>\r\n    Molar mass of O₂ = <span class=\"math\">32 g/mol</span>.<br>\r\n    <span class=\"math\">n = 12 / 32 = 3 / 8 = 0.375 mole</span>.<br><br>\r\n  • <strong>(b) 20 g of Water (H₂O):</strong><br>\r\n    Molar mass of H₂O = <span class=\"math\">18 g/mol</span>.<br>\r\n    <span class=\"math\">n = 20 / 18 = 10 / 9 ≈ 1.11 moles</span>.<br><br>\r\n  • <strong>(c) 22 g of Carbon dioxide (CO₂):</strong><br>\r\n    Molar mass of CO₂ = <span class=\"math\">44 g/mol</span>.<br>\r\n    <span class=\"math\">n = 22 / 44 = 0.5 mole</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) 12/32 = 0.375 mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) 20/18 = 1.11 mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) 22/44 = 0.5 mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">What is the mass of:<br>(a) 0.2 mole of oxygen atoms?<br>(b) 0.5 mole of water molecules?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) 0.2 mole of Oxygen atoms (O):</strong><br>\r\n  Atomic mass of O = 16 u ⟹ Molar mass = 16 g/mol.<br>\r\n  <span class=\"math\">Mass = 0.2 × 16 = 3.2 g</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) 0.5 mole of Water molecules (H₂O):</strong><br>\r\n  Molar mass of H₂O = 18 g/mol.<br>\r\n  <span class=\"math\">Mass = 0.5 × 18 = 9.0 g</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) 0.2 × 16 = 3.2 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) 0.5 × 18 = 9.0 g</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">Calculate the number of molecules of sulphur (S₈) present in 16 g of solid sulphur.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Molar Mass of S₈:</strong><br>\r\n  <span class=\"math\">Molar mass of S₈ = 8 × 32 = 256 g/mol</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Number of Moles in 16 g:</strong><br>\r\n  <span class=\"math\">Moles (n) = 16 / 256 = 1 / 16 = 0.0625 mole</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 3: Number of S₈ Molecules:</strong><br>\r\n  <span class=\"math\">Number of molecules = n × N_A = (1 / 16) × 6.022 × 10²³</span><br>\r\n  <span class=\"math\">Number of molecules = 0.3764 × 10²³ = 3.764 × 10²² molecules</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Exactly <strong>3.76 × 10²² molecules</strong> of S₈.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Molar mass of S₈ = 256 g/mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Moles = 16 / 256 = 0.0625</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Molecules = 3.764 × 10²² molecules</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q3_ex_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_ex_11')\">\r\n      <div class=\"q-num\">Exercise — Q11</div>\r\n      <div class=\"q-text\">Calculate the number of aluminium ions present in 0.051 g of aluminium oxide. (Hint: The mass of an ion is the same as that of an atom of the same element. Atomic mass of Al = 27 u).</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Step 1: Molar Mass of Aluminium Oxide (Al₂O₃):</strong><br>\r\n  <span class=\"math\">M = 2 × 27 + 3 × 16 = 54 + 48 = 102 g/mol</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Number of Moles and Formula Units of Al₂O₃:</strong><br>\r\n  <span class=\"math\">Moles = 0.051 / 102 = 0.0005 mole = 5 × 10⁻⁴ mole</span>.<br>\r\n  <span class=\"math\">Number of Al₂O₃ formula units = 5 × 10⁻⁴ × 6.022 × 10²³ = 3.011 × 10²⁰ units</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 3: Number of Aluminium Ions (Al³⁺):</strong><br>\r\n  Each formula unit of Al₂O₃ contains <strong>2 aluminium ions</strong> (<span class=\"math\">2 Al³⁺</span>).<br>\r\n  <span class=\"math\">Number of Al³⁺ ions = 2 × (3.011 × 10²⁰) = 6.022 × 10²⁰ ions</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> There are <strong>6.022 × 10²⁰ aluminium ions</strong> in 0.051 g of aluminium oxide.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Molar mass of Al₂O₃ = 102 g/mol</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Number of Al₂O₃ formula units = 3.011 × 10²⁰</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplying by 2 to get 6.022 × 10²⁰ Al³⁺ ions</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 3</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Avogadro's Hypothesis and Stoichiometry:</strong> A sealed container holds 44 g of CO₂ gas, while another identical container holds 32 g of O₂ gas at identical temperature and pressure.<br>(a) Calculate the number of moles in each container.<br>(b) Compare the number of molecules present in both containers.<br>(c) Compare the total number of atoms in both containers.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> Moles of CO₂ = 44/44 = 1.0 mole; Moles of O₂ = 32/32 = 1.0 mole.<br><strong>(b)</strong> Since both contain 1.0 mole, both containers have an <strong>identical number of molecules</strong> (<span class='math'>6.022 × 10²³ molecules</span>).<br><strong>(c)</strong> Each CO₂ molecule has 3 atoms (1C + 2O), so total atoms in CO₂ = <span class='math'>3 × N_A = 1.8066 × 10²⁴</span>. Each O₂ molecule has 2 atoms, so total atoms in O₂ = <span class='math'>2 × N_A = 1.2044 × 10²⁴</span>. Therefore, the CO₂ container has 1.5 times more atoms.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why is carbon-12 chosen as the international standard reference for atomic mass rather than hydrogen-1 or oxygen-16?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">Carbon-12 was chosen by IUPAC in 1961 because: (1) It is a stable, non-radioactive solid at room temperature and very abundant, (2) It yields near whole-number atomic masses for almost all other chemical elements, and (3) Oxygen-16 was rejected because natural oxygen contains multiple isotopes (¹⁶O, ¹⁷O, ¹⁸O) leading to discrepancies between physical and chemical mass scales.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(2)\">← Chapter 2</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\">Chapter 4 →</button>\r\n  </div>\r\n</section>","4":"<section class=\"chapter-section\" id=\"ch4\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">4</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 4: Structure of the Atom</h2>\r\n      <p>Subatomic Particles, Atomic Models (Thomson, Rutherford, Bohr), Electronic Configuration, Valency, Isotopes & Isobars — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 47)</div>\r\n\r\n  <div class=\"q-card\" id=\"q4_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_1')\">\r\n      <div class=\"q-num\">Page 47 — Q1</div>\r\n      <div class=\"q-text\">What are canal rays?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Definition & Discovery:</strong><br>\r\n  • <strong>Canal rays</strong> (also known as anode rays) are streams of positively charged subatomic radiations discovered by German physicist <strong>E. Goldstein in 1886</strong> in a modified gas discharge tube using a perforated cathode.<br>\r\n  • These rays travel in a direction opposite to cathode rays (from anode toward the cathode) and pass through the perforations (canals) of the cathode.<br>\r\n  • The investigation of canal rays led to the discovery of another subatomic particle carrying a positive charge equal in magnitude to the electron, which was later named the <strong>proton</strong> by Ernest Rutherford.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: Streams of positively charged particles discovered by Goldstein (1886)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Pass through perforated cathode; led to discovery of protons</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_2')\">\r\n      <div class=\"q-num\">Page 47 — Q2</div>\r\n      <div class=\"q-text\">If an atom contains one electron and one proton, will it carry any charge or not?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis:</strong><br>\r\n  • An electron carries a unit negative electrical charge (<span class=\"math\">-1.602 × 10⁻¹⁹ C</span> or <span class=\"math\">-1</span>).<br>\r\n  • A proton carries an exactly equal magnitude of positive electrical charge (<span class=\"math\">+1.602 × 10⁻¹⁹ C</span> or <span class=\"math\">+1</span>).<br>\r\n  • When an atom contains 1 proton and 1 electron, the total net charge is:<br>\r\n  <span class=\"math\">Net Charge = (+1) + (-1) = 0</span>.\r\n</div>\r\n<p><strong>Conclusion:</strong> The atom will be <strong>electrically neutral</strong> and carry <strong>no net charge</strong> (this represents a normal protium hydrogen atom, <span class=\"math\">¹₁H</span>).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">State that charges are equal in magnitude and opposite in sign (+1 and -1)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Conclude net charge is zero / electrically neutral</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 49)</div>\r\n\r\n  <div class=\"q-card\" id=\"q4_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_3')\">\r\n      <div class=\"q-num\">Page 49 — Q1</div>\r\n      <div class=\"q-text\">On the basis of Thomson's model of an atom, explain how the atom is neutral as a whole.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Thomson's Plum Pudding / Watermelon Model:</strong><br>\r\n  1. J.J. Thomson proposed that an atom consists of a uniform sphere of positive charge in which negatively charged electrons are embedded like seeds in a watermelon or raisins in a pudding.<br>\r\n  2. The negative and positive charges are <strong>equal in magnitude</strong>.<br>\r\n  3. Because the total positive charge of the sphere exactly equals the sum of the negative charges of all embedded electrons, they cancel each other out completely, making the atom <strong>electrically neutral as a whole</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Description of positive sphere with embedded negative electrons</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Equal magnitude of positive and negative charges cancelling out</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_4')\">\r\n      <div class=\"q-num\">Page 49 — Q2</div>\r\n      <div class=\"q-text\">On the basis of Rutherford's model of an atom, which subatomic particle is present in the nucleus of an atom?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  According to Rutherford's nuclear model, the positively charged <strong>proton</strong> is present inside the extremely dense and tiny central core called the <strong>nucleus</strong>. (Later, James Chadwick discovered that neutral <em>neutrons</em> also reside in the nucleus alongside protons).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Proton (and mention of nucleons)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_5')\">\r\n      <div class=\"q-num\">Page 49 — Q3</div>\r\n      <div class=\"q-text\">Draw a sketch of Bohr's model of an atom with three shells.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Bohr's Atomic Shell Structure:</strong><br>\r\n  Neils Bohr proposed that electrons revolve around the central positive nucleus only in discrete orbits called <em>energy levels</em> or <em>electron shells</em>, designated as:\r\n  <ul>\r\n    <li>Innermost shell: <span class=\"math\">n = 1</span> (<strong>K shell</strong>)</li>\r\n    <li>Second shell: <span class=\"math\">n = 2</span> (<strong>L shell</strong>)</li>\r\n    <li>Third shell: <span class=\"math\">n = 3</span> (<strong>M shell</strong>)</li>\r\n  </ul>\r\n  <div style=\"text-align:center; padding:15px; background:rgba(0,0,0,0.2); border-radius:8px; margin:10px 0; font-family:monospace;\">\r\n    ( M Shell: n = 3 )<br>\r\n    &nbsp;&nbsp;[ L Shell: n = 2 ]<br>\r\n    &nbsp;&nbsp;&nbsp;&nbsp;{ K Shell: n = 1 }<br>\r\n    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;⭐ [ Nucleus: +ve ]\r\n  </div>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate representation of central positive nucleus</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Three concentric discrete energy shells labeled K (n=1), L (n=2), M (n=3)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_6')\">\r\n      <div class=\"q-num\">Page 49 — Q4</div>\r\n      <div class=\"q-text\">What do you think would be the observation if the α-particle scattering experiment is carried out using a foil of a metal other than gold?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Analysis:</strong><br>\r\n  1. <strong>If another heavy metal foil (like Platinum) is used:</strong> Observations would remain essentially identical, because platinum atoms also have a massive, highly positively charged nucleus that can deflect heavy α-particles (<span class=\"math\">⁴₂He²⁺</span>).<br>\r\n  2. <strong>If a very light metal foil (like Aluminium or Lithium) is used:</strong><br>\r\n     • The nucleus of a light atom is much less massive and carries a much smaller positive nuclear charge.<br>\r\n     • The electrostatic repulsion would be too weak to cause large-angle deflections or rebound fast-moving α-particles.<br>\r\n     • Most α-particles would pass straight through with virtually no large deflections or back-scattering. Gold was uniquely chosen because it is the most malleable metal, capable of being hammered into an extremely thin sheet just ~1000 atoms thick.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Heavy metal foil yields similar scattering patterns</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Light metal foil causes negligible large deflections due to lower nuclear charge/mass</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 52)</div>\r\n\r\n  <div class=\"q-card\" id=\"q4_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_7')\">\r\n      <div class=\"q-num\">Page 52 — Q1</div>\r\n      <div class=\"q-text\">Name the three sub-atomic particles of an atom.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>The three fundamental sub-atomic particles are:</strong>\r\n  <ol>\r\n    <li><strong>Electron (<span class=\"math\">e⁻</span>):</strong> Negatively charged particle discovered by J.J. Thomson.</li>\r\n    <li><strong>Proton (<span class=\"math\">p⁺</span>):</strong> Positively charged particle discovered by E. Goldstein / Rutherford.</li>\r\n    <li><strong>Neutron (<span class=\"math\">n⁰</span>):</strong> Electrically neutral particle discovered by James Chadwick.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Electron, Proton, Neutron correctly identified with symbols/charges</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_8')\">\r\n      <div class=\"q-num\">Page 52 — Q2</div>\r\n      <div class=\"q-text\">Helium atom has an atomic mass of 4 u and two protons in its nucleus. How many neutrons does it have?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Atomic mass (<span class=\"math\">A</span>) = <span class=\"math\">4 u</span><br>\r\n  • Number of protons (<span class=\"math\">Z</span>) = <span class=\"math\">2</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Formula:</strong><br>\r\n  <span class=\"math\">Mass number (A) = Number of protons (Z) + Number of neutrons (n)</span><br>\r\n  <span class=\"math\">n = A - Z</span><br>\r\n  <span class=\"math\">n = 4 - 2 = 2</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The helium atom has <strong>2 neutrons</strong> in its nucleus.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula: Number of neutrons = Mass number - Atomic number</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation 4 - 2 = 2 neutrons</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 53)</div>\r\n\r\n  <div class=\"q-card\" id=\"q4_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_9')\">\r\n      <div class=\"q-num\">Page 53 — Q1</div>\r\n      <div class=\"q-text\">Write the distribution of electrons in carbon and sodium atoms.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Bohr-Bury Scheme (<span class=\"math\">2n²</span> rule):</strong><br>\r\n  • <strong>Carbon (C, Atomic Number Z = 6):</strong><br>\r\n    Total electrons = 6.<br>\r\n    Electronic configuration = <strong>K = 2, L = 4</strong> (or simply <strong>2, 4</strong>).<br><br>\r\n  • <strong>Sodium (Na, Atomic Number Z = 11):</strong><br>\r\n    Total electrons = 11.<br>\r\n    Electronic configuration = <strong>K = 2, L = 8, M = 1</strong> (or simply <strong>2, 8, 1</strong>).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Carbon distribution: K=2, L=4</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Sodium distribution: K=2, L=8, M=1</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_10')\">\r\n      <div class=\"q-num\">Page 53 — Q2</div>\r\n      <div class=\"q-text\">If K and L shells of an atom are full, then what would be the total number of electrons in the atom?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Maximum Electron Capacity per Shell (<span class=\"math\">2n²</span>):</strong><br>\r\n  • For K shell (<span class=\"math\">n = 1</span>): <span class=\"math\">Maximum electrons = 2(1)² = 2</span>.<br>\r\n  • For L shell (<span class=\"math\">n = 2</span>): <span class=\"math\">Maximum electrons = 2(2)² = 8</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">Total number of electrons = Electrons in K shell + Electrons in L shell</span><br>\r\n  <span class=\"math\">Total electrons = 2 + 8 = 10 electrons</span>.\r\n</div>\r\n<p><strong>Note:</strong> An atom with 10 electrons is the noble gas <strong>Neon (Ne)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating maximum capacity: K=2 and L=8</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Summing 2 + 8 = 10 electrons (Neon)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_11')\">\r\n      <div class=\"q-num\">Page 53 — Q3</div>\r\n      <div class=\"q-text\">How will you find the valency of chlorine, sulphur and magnesium?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition of Valency:</strong> Valency is the combining capacity of an atom to achieve a stable octet (8 valence electrons).<br>\r\n  If valence electrons (<span class=\"math\">v</span>) ≤ 4, <span class=\"math\">Valency = v</span>.<br>\r\n  If valence electrons (<span class=\"math\">v</span>) &gt; 4, <span class=\"math\">Valency = 8 - v</span>.<br><br>\r\n  • <strong>Chlorine (Cl, Z = 17):</strong><br>\r\n    Configuration = 2, 8, 7. Valence electrons = 7.<br>\r\n    <span class=\"math\">Valency = 8 - 7 = 1</span> (Gains 1 electron to complete octet).<br><br>\r\n  • <strong>Sulphur (S, Z = 16):</strong><br>\r\n    Configuration = 2, 8, 6. Valence electrons = 6.<br>\r\n    <span class=\"math\">Valency = 8 - 6 = 2</span> (Gains 2 electrons to complete octet).<br><br>\r\n  • <strong>Magnesium (Mg, Z = 12):</strong><br>\r\n    Configuration = 2, 8, 2. Valence electrons = 2.<br>\r\n    <span class=\"math\">Valency = 2</span> (Loses 2 valence electrons to achieve stable octet).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Chlorine valency = 8 - 7 = 1</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Sulphur valency = 8 - 6 = 2</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Magnesium valency = 2</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_12')\">\r\n      <div class=\"q-num\">Page 53 — Q4</div>\r\n      <div class=\"q-text\">If number of electrons in an atom is 8 and number of protons is also 8, then (i) what is the atomic number of the atom? and (ii) what is the charge on the atom?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(i) Atomic Number (Z):</strong><br>\r\n  By definition, <span class=\"math\">Atomic number (Z) = Number of protons in the nucleus = 8</span>.<br>\r\n  (Element is Oxygen).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(ii) Net Charge on the atom:</strong><br>\r\n  <span class=\"math\">Total positive charge = +8</span> (from 8 protons)<br>\r\n  <span class=\"math\">Total negative charge = -8</span> (from 8 electrons)<br>\r\n  <span class=\"math\">Net charge = (+8) + (-8) = 0</span>.<br>\r\n  The atom carries <strong>zero net charge (neutral)</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Atomic number = 8</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Net charge = 0 (neutral)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_in_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_in_13')\">\r\n      <div class=\"q-num\">Page 53 — Q5</div>\r\n      <div class=\"q-text\">With the help of Table 4.1, find out the mass number of oxygen and sulphur atom.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong> <span class=\"math\">Mass number (A) = Protons + Neutrons</span><br><br>\r\n  • <strong>For Oxygen atom:</strong><br>\r\n    Number of protons = 8, Number of neutrons = 8.<br>\r\n    <span class=\"math\">Mass number (A) = 8 + 8 = 16 u</span>.<br><br>\r\n  • <strong>For Sulphur atom:</strong><br>\r\n    Number of protons = 16, Number of neutrons = 16.<br>\r\n    <span class=\"math\">Mass number (A) = 16 + 16 = 32 u</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Oxygen: Protons=8, Neutrons=8 ⟹ Mass number = 16</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Sulphur: Protons=16, Neutrons=16 ⟹ Mass number = 32</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q4_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">Compare the properties of electrons, protons and neutrons.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparative Table of Fundamental Subatomic Particles:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Property</th><th>Electron (<span class=\"math\">e⁻</span>)</th><th>Proton (<span class=\"math\">p⁺</span>)</th><th>Neutron (<span class=\"math\">n⁰</span>)</th></tr>\r\n    <tr><td><strong>Discovery</strong></td><td>J.J. Thomson (1897)</td><td>E. Goldstein (1886) / Rutherford</td><td>James Chadwick (1932)</td></tr>\r\n    <tr><td><strong>Nature of Charge</strong></td><td>Negative (<span class=\"math\">-1</span>)</td><td>Positive (<span class=\"math\">+1</span>)</td><td>Neutral (<span class=\"math\">0</span>)</td></tr>\r\n    <tr><td><strong>Absolute Charge</strong></td><td><span class=\"math\">-1.602 × 10⁻¹⁹ C</span></td><td><span class=\"math\">+1.602 × 10⁻¹⁹ C</span></td><td>0 C</td></tr>\r\n    <tr><td><strong>Relative Mass</strong></td><td><span class=\"math\">1/1840 u</span> (negligible)</td><td><span class=\"math\">1 u</span></td><td><span class=\"math\">1 u</span></td></tr>\r\n    <tr><td><strong>Absolute Mass</strong></td><td><span class=\"math\">9.109 × 10⁻³¹ kg</span></td><td><span class=\"math\">1.673 × 10⁻²⁷ kg</span></td><td><span class=\"math\">1.675 × 10⁻²⁷ kg</span></td></tr>\r\n    <tr><td><strong>Location in Atom</strong></td><td>Extranuclear space (in shells/orbits)</td><td>Inside the nucleus</td><td>Inside the nucleus</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Relative and absolute charges compared</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Relative and absolute masses compared</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Location and discoverers compared</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">What are the limitations of J.J. Thomson’s model of the atom?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Limitations of Thomson's Model:</strong>\r\n  <ol>\r\n    <li>It failed to explain the results of Rutherford's alpha-particle scattering experiment, specifically why a small fraction of fast-moving α-particles were deflected through large angles and some rebounded backwards at 180°.</li>\r\n    <li>It lacked experimental evidence and failed to explain the stability of an atom or the presence of a localized, dense positive nucleus.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Failure to explain Rutherford's alpha scattering results</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Lack of experimental verification of positive charge distribution</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">What are the limitations of Rutherford’s model of the atom?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Major Limitation — Instability of the Atom:</strong><br>\r\n  1. According to classical electromagnetic theory (Maxwell's electrodynamics), any charged particle revolving in a circular orbit undergoes continuous centripetal acceleration.<br>\r\n  2. An accelerating charged particle must continuously radiate energy in the form of electromagnetic waves.<br>\r\n  3. Consequently, the revolving electron should continuously lose kinetic energy, its orbital radius would steadily shrink, and it should spiral inward into the nucleus in less than <span class=\"math\">10⁻⁸ seconds</span>.<br>\r\n  4. If this were true, all atoms would collapse, and matter would not exist in a stable form. But atoms are known to be completely stable. Rutherford's model could not explain this stability.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Maxwell's electromagnetic theory: accelerated charges radiate energy</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Electron spiraling into nucleus causing collapse vs observed atomic stability</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">Describe Bohr’s model of the atom.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Postulates of Neils Bohr's Atomic Model (1913):</strong>\r\n  <ol>\r\n    <li><strong>Discrete Orbits:</strong> Electrons revolve around the nucleus only in certain specific, non-radiating circular orbits known as <em>discrete orbits</em> or stationary energy states.</li>\r\n    <li><strong>Non-radiating Energy:</strong> While revolving in these discrete orbits, electrons do not radiate energy.</li>\r\n    <li><strong>Energy Shells:</strong> These orbits or shells are represented by letters <strong>K, L, M, N...</strong> or principal quantum numbers <span class=\"math\">n = 1, 2, 3, 4...</span></li>\r\n    <li><strong>Energy Transitions:</strong> An electron absorbs energy when it jumps from a lower orbit to a higher orbit, and radiates energy when it drops from a higher orbit to a lower orbit (<span class=\"math\">ΔE = E₂ - E₁ = hν</span>).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Concept of discrete non-radiating orbits (stationary states)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Designation of energy shells (K, L, M, N... / n=1, 2, 3, 4)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of energy emission/absorption during shell transitions</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">Compare all the proposed models of an atom given in this chapter.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comprehensive Comparison of Atomic Models:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Thomson's Model (1898)</th><th>Rutherford's Model (1911)</th><th>Bohr's Model (1913)</th></tr>\r\n    <tr><td><strong>Structure</strong></td><td>Uniform positive sphere with electrons embedded like watermelon seeds.</td><td>Tiny dense positive nucleus at center; electrons orbiting in wide open space.</td><td>Central positive nucleus surrounded by quantized, discrete circular orbits.</td></tr>\r\n    <tr><td><strong>Nucleus</strong></td><td>No nucleus conceived.</td><td>Discovered tiny, dense positively charged nucleus containing all mass.</td><td>Nucleus at center with fixed positive charge.</td></tr>\r\n    <tr><td><strong>Electron Movement</strong></td><td>Stationary embedded within positive sphere.</td><td>Revolve in circular orbits (like planets around Sun).</td><td>Revolve in stationary, discrete non-radiating energy shells (K, L, M...).</td></tr>\r\n    <tr><td><strong>Stability</strong></td><td>Assumed electrostatic balance.</td><td>Failed to explain stability against electromagnetic radiation collapse.</td><td>Successfully explained stability: orbits are non-radiating energy levels.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Thomson's model comparison</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Rutherford's model comparison</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Bohr's model comparison</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">Summarize the rules for writing of distribution of electrons in various shells for the first eighteen elements.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Bohr-Bury Scheme Rules:</strong>\r\n  <ol>\r\n    <li><strong>Maximum Capacity Formula (<span class=\"math\">2n²</span>):</strong> The maximum number of electrons that can be accommodated in any shell is given by <span class=\"math\">2n²</span> (where <span class=\"math\">n</span> is the shell number):\r\n      <ul>\r\n        <li>K-shell (<span class=\"math\">n = 1</span>): <span class=\"math\">2(1)² = 2 electrons</span></li>\r\n        <li>L-shell (<span class=\"math\">n = 2</span>): <span class=\"math\">2(2)² = 8 electrons</span></li>\r\n        <li>M-shell (<span class=\"math\">n = 3</span>): <span class=\"math\">2(3)² = 18 electrons</span></li>\r\n      </ul>\r\n    </li>\r\n    <li><strong>Octet Rule for Outermost Shell:</strong> The maximum number of electrons that can be accommodated in the outermost shell is strictly <strong>8</strong>, even if the shell has capacity for more.</li>\r\n    <li><strong>Stepwise Shell Filling:</strong> Electrons are not accommodated in a given shell unless the inner shells are completely filled (shells are filled in a step-wise, progressive manner).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Rule 1: 2n² formula with values for K, L, M</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Rule 2: Outermost shell maximum capacity = 8 electrons</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Rule 3: Step-wise filling of inner shells first</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">Define valency by taking examples of silicon and oxygen.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition of Valency:</strong><br>\r\n  Valency is the combining capacity of an atom of an element to achieve a completely filled, stable outermost octet (or duplet) electron shell.<br><br>\r\n  • <strong>Example 1: Silicon (Si, Z = 14):</strong><br>\r\n    Electronic configuration = 2, 8, 4. It has 4 valence electrons in its outermost M-shell.<br>\r\n    To attain a stable octet, it shares 4 electrons with other atoms.<br>\r\n    Therefore, the <strong>valency of silicon is 4</strong>.<br><br>\r\n  • <strong>Example 2: Oxygen (O, Z = 8):</strong><br>\r\n    Electronic configuration = 2, 6. It has 6 valence electrons in its outermost L-shell.<br>\r\n    Instead of losing 6 electrons, it easily gains or shares 2 electrons to complete its octet (<span class=\"math\">8 - 6 = 2</span>).<br>\r\n    Therefore, the <strong>valency of oxygen is 2</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Standard definition of valency</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Derivation of Silicon valency = 4</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Derivation of Oxygen valency = 8 - 6 = 2</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">Explain with examples (i) Atomic number, (ii) Mass number, (iii) Isotopes and (iv) Isobars. Give any two uses of isotopes.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(i) Atomic Number (Z):</strong> The total number of protons present in the nucleus of an atom. Example: Carbon has 6 protons, so <span class=\"math\">Z = 6</span>.<br><br>\r\n  <strong>(ii) Mass Number (A):</strong> The total sum of protons and neutrons (nucleons) present in the nucleus of an atom (<span class=\"math\">A = p + n</span>). Example: Aluminium has 13 protons and 14 neutrons, so <span class=\"math\">A = 13 + 14 = 27</span>.<br><br>\r\n  <strong>(iii) Isotopes:</strong> Atoms of the same element having the same atomic number (<span class=\"math\">Z</span>) but different mass numbers (<span class=\"math\">A</span>) due to differing numbers of neutrons. Example: Hydrogen isotopes: Protium (<span class=\"math\">¹₁H</span>), Deuterium (<span class=\"math\">²₁H</span>), and Tritium (<span class=\"math\">³₁H</span>); Carbon isotopes: <span class=\"math\">¹²₆C</span> and <span class=\"math\">¹⁴₆C</span>.<br><br>\r\n  <strong>(iv) Isobars:</strong> Atoms of different chemical elements having different atomic numbers (<span class=\"math\">Z</span>) but the same mass number (<span class=\"math\">A</span>). Example: Argon (<span class=\"math\">⁴⁰₁₈Ar</span>) and Calcium (<span class=\"math\">⁴⁰₂₀Ca</span>).<br><br>\r\n  <strong>Two Important Uses of Isotopes:</strong>\r\n  <ol>\r\n    <li>An isotope of <strong>Uranium (U-235)</strong> is used as fuel in nuclear reactors to generate electricity.</li>\r\n    <li>An isotope of <strong>Cobalt (Co-60)</strong> is used in radiation therapy for the treatment of cancer. (Also, Iodine-131 is used in treating goitre).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Atomic number and Mass number definitions + examples</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Isotopes and Isobars definitions + examples</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Two commercial/medical uses of isotopes (U-235, Co-60)</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">Na⁺ has completely filled K and L shells. Explain.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Step-by-Step Electronic Analysis:</strong><br>\r\n  1. A neutral Sodium atom (<span class=\"math\">Na</span>) has atomic number <span class=\"math\">Z = 11</span>, meaning it possesses 11 protons and 11 electrons.<br>\r\n  2. Its electronic configuration is: <span class=\"math\">K = 2, L = 8, M = 1</span>.<br>\r\n  3. When sodium forms a cation (<span class=\"math\">Na⁺</span>), it loses its single outermost valence electron from the M shell:<br>\r\n  <span class=\"math\">Na (2, 8, 1) ⟶ Na⁺ (2, 8) + e⁻</span>.<br>\r\n  4. Now, the <span class=\"math\">Na⁺</span> ion possesses 10 electrons:\r\n     • K shell has 2 electrons (maximum capacity = 2).<br>\r\n     • L shell has 8 electrons (maximum capacity = 8).<br>\r\n  Both K and L shells are completely filled to their maximum capacities, giving <span class=\"math\">Na⁺</span> a highly stable noble gas configuration (isoelectronic with Neon).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Electronic configuration of Na atom (2, 8, 1)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Loss of 1 valence electron to form Na⁺ (2, 8)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Concluding K (2) and L (8) are filled to maximum capacity</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">If bromine atom is available in the form of, say, two isotopes ⁷⁹Br (49.7%) and ⁸¹Br (50.3%), calculate the average atomic mass of bromine atom.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Isotope 1: Mass = <span class=\"math\">79 u</span>, Abundance = <span class=\"math\">49.7%</span><br>\r\n  • Isotope 2: Mass = <span class=\"math\">81 u</span>, Abundance = <span class=\"math\">50.3%</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Formula:</strong><br>\r\n  <span class=\"math\">Average Atomic Mass = (Mass₁ × %₁) / 100 + (Mass₂ × %₂) / 100</span><br>\r\n  <span class=\"math\">Average Atomic Mass = (79 × 49.7 + 81 × 50.3) / 100</span><br>\r\n  <span class=\"math\">= (3926.3 + 4074.3) / 100</span><br>\r\n  <span class=\"math\">= 8000.6 / 100 = 80.006 u ≈ 80 u</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The average atomic mass of bromine is <strong>80.006 u (or 80 u)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Weighted average formula stated</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct calculation (3926.3 + 4074.3)/100</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer = 80.006 u</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_11')\">\r\n      <div class=\"q-num\">Exercise — Q11</div>\r\n      <div class=\"q-text\">The average atomic mass of a sample of an element X is 16.2 u. What are the percentages of isotopes ¹⁶X and ¹⁸X in the sample?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Let:</strong><br>\r\n  • Percentage of isotope <span class=\"math\">¹⁶X = y %</span><br>\r\n  • Percentage of isotope <span class=\"math\">¹⁸X = (100 - y) %</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Setting up Equation:</strong><br>\r\n  <span class=\"math\">Average Atomic Mass = [16 × y + 18 × (100 - y)] / 100 = 16.2</span><br>\r\n  <span class=\"math\">16y + 1800 - 18y = 16.2 × 100 = 1620</span><br>\r\n  <span class=\"math\">1800 - 2y = 1620</span><br>\r\n  <span class=\"math\">2y = 1800 - 1620 = 180</span><br>\r\n  <span class=\"math\">y = 90%</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Conclusion:</strong><br>\r\n  • Percentage of <span class=\"math\">¹⁶X = 90%</span><br>\r\n  • Percentage of <span class=\"math\">¹⁸X = 100 - 90 = 10%</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> <strong>¹⁶X = 90%</strong> and <strong>¹⁸X = 10%</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Setting up expression with variables y and (100 - y)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving algebraic equation 2y = 180</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final values: ¹⁶X = 90% and ¹⁸X = 10%</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_12')\">\r\n      <div class=\"q-num\">Exercise — Q12</div>\r\n      <div class=\"q-text\">If Z = 3, what would be the valency of the element? Also, name the element.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis:</strong><br>\r\n  • Atomic number <span class=\"math\">Z = 3</span> corresponds to the element <strong>Lithium (Li)</strong>.<br>\r\n  • Electronic distribution = <span class=\"math\">K = 2, L = 1</span>.<br>\r\n  • Since it has 1 valence electron in its outermost L-shell, it readily loses this 1 electron to achieve a stable duplet configuration.<br>\r\n  • Therefore, its <strong>valency is 1</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Valency = 1</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Name of element = Lithium</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_13')\">\r\n      <div class=\"q-num\">Exercise — Q13</div>\r\n      <div class=\"q-text\">Composition of the nuclei of two atomic species X and Y are given as: X (Protons = 6, Neutrons = 6), Y (Protons = 6, Neutrons = 8). Give the mass numbers of X and Y. What is the relation between the two species?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Mass Numbers (<span class=\"math\">A = p + n</span>):</strong><br>\r\n  • Mass number of X = <span class=\"math\">6 + 6 = 12</span>.<br>\r\n  • Mass number of Y = <span class=\"math\">6 + 8 = 14</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Relationship Between Species:</strong><br>\r\n  Both species X and Y have the <strong>same atomic number (Z = 6 protons)</strong> but <strong>different mass numbers (A = 12 and 14)</strong>.<br>\r\n  Therefore, species X and Y are <strong>Isotopes</strong> of the same element (Carbon: <span class=\"math\">¹²₆C</span> and <span class=\"math\">¹⁴₆C</span>).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mass number of X = 12</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mass number of Y = 14</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification as Isotopes of carbon</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_14')\">\r\n      <div class=\"q-num\">Exercise — Q14</div>\r\n      <div class=\"q-text\">Rutherford’s alpha-particle scattering experiment was responsible for the discovery of:<br>(a) Atomic Nucleus<br>(b) Electron<br>(c) Proton<br>(d) Neutron</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<p><strong>Correct Option:</strong> <strong>(a) Atomic Nucleus</strong></p>\r\n<div class=\"step\">\r\n  <em>Explanation:</em> The rebound of 1 in 20,000 α-particles showed that all positive charge and nearly all mass of an atom is concentrated in a tiny central region called the nucleus.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (a) Atomic Nucleus with scientific explanation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_15')\">\r\n      <div class=\"q-num\">Exercise — Q15</div>\r\n      <div class=\"q-text\">Isotopes of an element have:<br>(a) the same physical properties<br>(b) different chemical properties<br>(c) different number of neutrons<br>(d) different atomic numbers</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<p><strong>Correct Option:</strong> <strong>(c) different number of neutrons</strong></p>\r\n<div class=\"step\">\r\n  <em>Explanation:</em> Isotopes have identical atomic numbers (same protons/electrons, hence identical chemical properties) but different mass numbers due to differing neutron counts.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (c) different number of neutrons</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_16')\">\r\n      <div class=\"q-num\">Exercise — Q16</div>\r\n      <div class=\"q-text\">Number of valence electrons in Cl⁻ ion are:<br>(a) 16<br>(b) 8<br>(c) 17<br>(d) 18</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<p><strong>Correct Option:</strong> <strong>(b) 8</strong></p>\r\n<div class=\"step\">\r\n  <em>Explanation:</em> A neutral Cl atom has electronic configuration 2, 8, 7. When it gains 1 electron to form the chloride ion (Cl⁻), its configuration becomes 2, 8, 8. The outermost (valence) shell contains exactly <strong>8 electrons</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (b) 8 with electron configuration explanation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_17\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_17')\">\r\n      <div class=\"q-num\">Exercise — Q17</div>\r\n      <div class=\"q-text\">Which one of the following is a correct electronic configuration of sodium?<br>(a) 2,8<br>(b) 8,2,1<br>(c) 2,1,8<br>(d) 2,8,1</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<p><strong>Correct Option:</strong> <strong>(d) 2,8,1</strong></p>\r\n<div class=\"step\">\r\n  <em>Explanation:</em> Sodium has atomic number Z = 11. Following the Bohr-Bury rule, K shell accommodates 2, L shell accommodates 8, and the remaining 1 goes to M shell: (2, 8, 1).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (d) 2,8,1</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_18\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_18')\">\r\n      <div class=\"q-num\">Exercise — Q18</div>\r\n      <div class=\"q-text\">Complete the following table:<br>\r\n<table class=\"data-table\">\r\n<tr><th>Atomic Number</th><th>Mass Number</th><th>Number of Neutrons</th><th>Number of Protons</th><th>Number of Electrons</th><th>Name of the Atomic Species</th></tr>\r\n<tr><td>9</td><td>-</td><td>10</td><td>-</td><td>-</td><td>-</td></tr>\r\n<tr><td>16</td><td>32</td><td>-</td><td>-</td><td>-</td><td>Sulphur</td></tr>\r\n<tr><td>-</td><td>24</td><td>-</td><td>12</td><td>-</td><td>-</td></tr>\r\n<tr><td>-</td><td>2</td><td>-</td><td>1</td><td>-</td><td>-</td></tr>\r\n<tr><td>-</td><td>1</td><td>0</td><td>1</td><td>-</td><td>-</td></tr>\r\n</table></div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Completed Table:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Atomic Number</th><th>Mass Number</th><th>Number of Neutrons</th><th>Number of Protons</th><th>Number of Electrons</th><th>Name of the Atomic Species</th></tr>\r\n    <tr><td><strong>9</strong></td><td><strong>19</strong></td><td>10</td><td><strong>9</strong></td><td><strong>9</strong></td><td><strong>Fluorine</strong></td></tr>\r\n    <tr><td>16</td><td>32</td><td><strong>16</strong></td><td><strong>16</strong></td><td><strong>16</strong></td><td>Sulphur</td></tr>\r\n    <tr><td><strong>12</strong></td><td>24</td><td><strong>12</strong></td><td>12</td><td><strong>12</strong></td><td><strong>Magnesium</strong></td></tr>\r\n    <tr><td><strong>1</strong></td><td>2</td><td><strong>1</strong></td><td>1</td><td><strong>1</strong></td><td><strong>Deuterium (Hydrogen-2)</strong></td></tr>\r\n    <tr><td><strong>1</strong></td><td>1</td><td>0</td><td>1</td><td><strong>1</strong></td><td><strong>Protium (Hydrogen-1)</strong></td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Row 1 (Fluorine, Mass 19)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Row 2 (Sulphur, Neutrons 16, Protons 16, Electrons 16)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Row 3 (Magnesium, Z=12)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Row 4 (Deuterium, Z=1, Neutrons=1)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Row 5 (Protium, Z=1, Electrons=1)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q4_ex_19\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_ex_19')\">\r\n      <div class=\"q-num\">Exercise — Q19</div>\r\n      <div class=\"q-text\">True or False:<br>(a) J.J. Thomson proposed that the nucleus of an atom contains only nucleons.<br>(b) A neutron is formed by an electron and a proton combining together. Therefore, it is neutral.<br>(c) The mass of an electron is about 1/2000 times that of proton.<br>(d) An isotope of iodine is used for making tincture iodine, which is used as a medicine.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Evaluation of Statements:</strong>\r\n  <ul>\r\n    <li><strong>(a) False:</strong> J.J. Thomson did not propose any nucleus. The nucleus was discovered by Ernest Rutherford.</li>\r\n    <li><strong>(b) False:</strong> A neutron is an independent fundamental subatomic particle, not a physical composite of an electron and a proton.</li>\r\n    <li><strong>(c) True:</strong> The mass of an electron is approximately <span class=\"math\">1/1840 ≈ 1/2000</span> of the mass of a proton.</li>\r\n    <li><strong>(d) False:</strong> Tincture of iodine is a physical solution of ordinary elemental iodine in alcohol-water; the radioactive isotope Iodine-131 is used specifically in the treatment of goitre/thyroid disorders, not as tincture of iodine.</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) False and (b) False with explanations</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) True and (d) False with explanations</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 4</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Rutherford's Gold Foil Experiment:</strong> Rutherford bombarded a 100 nm thin gold sheet with fast-moving alpha particles (<span class='math'>⁴₂He²⁺</span>).<br>(a) What unexpected result led to the rejection of Thomson's plum pudding model?<br>(b) What conclusion was drawn from the observation that 1 in 20,000 particles rebounded backwards?<br>(c) Why did Rutherford select gold specifically?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> Thomson's model predicted slight deflections across the uniform sphere; however, 1 in 20,000 α-particles were deflected by more than 90° or rebounded back at 180°, which was impossible in a diffuse positive cloud.<br><strong>(b)</strong> The entire positive charge and almost all the mass of the atom is concentrated in an unimaginably tiny, dense central volume called the nucleus.<br><strong>(c)</strong> Gold is the most malleable metal known, allowing a sheet just ~1000 atoms thick to be produced.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why do isotopes of an element show identical chemical properties but different physical properties?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">Chemical properties are governed solely by the electronic configuration (specifically the number of valence electrons), which is identical in all isotopes of an element since their atomic number (Z) is the same. Physical properties (such as density, boiling point, and diffusion rate) depend directly on atomic mass, which differs among isotopes due to different numbers of neutrons.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(3)\">← Chapter 3</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\">Chapter 5 →</button>\r\n  </div>\r\n</section>","5":"<section class=\"chapter-section\" id=\"ch5\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">5</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 5: The Fundamental Unit of Life</h2>\r\n      <p>Cell Discovery, Plasma Membrane, Diffusion, Osmosis, Organelles & Cell Division — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 59)</div>\r\n\r\n  <div class=\"q-card\" id=\"q5_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_in_1')\">\r\n      <div class=\"q-num\">Page 59 — Q1</div>\r\n      <div class=\"q-text\">Who discovered cells, and how?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Discovery of Cells:</strong><br>\r\n  • <strong>Scientist:</strong> Cells were first discovered by the English scientist <strong>Robert Hooke in 1665</strong>.<br>\r\n  • <strong>How:</strong> Hooke examined a very thin slice of bottle cork (a substance that comes from the bark of a tree) under a self-designed primitive compound microscope.<br>\r\n  • <strong>Observation:</strong> He observed that the cork slice resembled the structure of a honeycomb consisting of numerous tiny compartments or walled boxes.<br>\r\n  • Hooke coined the term <strong>'cell'</strong> (derived from the Latin word <em>cellula</em> meaning 'a little room') to describe these individual box-like compartments. (Note: These were dead cell walls of plant tissue; Antonie van Leeuwenhoek in 1674 first observed free living cells).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Scientist: Robert Hooke (1665)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Observation of honeycomb-like compartments in thin cork slice under microscope</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_in_2')\">\r\n      <div class=\"q-num\">Page 59 — Q2</div>\r\n      <div class=\"q-text\">Why is the cell called the structural and functional unit of life?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>1. Structural Unit:</strong><br>\r\n  • All living organisms (from microscopic bacteria to gigantic blue whales and redwood trees) are composed of one or more cells.<br>\r\n  • Cells assemble together to form tissues, tissues form organs, organs form organ systems, which ultimately build the entire physical anatomical architecture of an organism. Without cells, biological structure cannot exist.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>2. Functional Unit:</strong><br>\r\n  • A single independent cell possesses all biochemical machinery to carry out all vital metabolic life processes independently (e.g. cellular respiration, nutrient intake, protein synthesis, excretion of waste, and reproduction).<br>\r\n  • All functions of an organ or organism are the cumulative aggregate of the functions performed by its individual constituent cells.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of cell as Structural Unit (building blocks forming tissues/organs)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of cell as Functional Unit (executing all metabolic life activities)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 61)</div>\r\n\r\n  <div class=\"q-card\" id=\"q5_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_in_3')\">\r\n      <div class=\"q-num\">Page 61 — Q1</div>\r\n      <div class=\"q-text\">How do substances like CO₂ and water move in and out of the cell? Discuss.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>1. Movement of Carbon Dioxide (CO₂) by Diffusion:</strong><br>\r\n  • As cellular respiration occurs inside the cell, CO₂ (a metabolic waste product) accumulates, creating a <strong>high concentration</strong> of CO₂ inside the cytoplasm.<br>\r\n  • In the external environment, the concentration of CO₂ is comparatively low.<br>\r\n  • Due to this concentration difference, CO₂ moves spontaneously across the cell membrane from an area of high concentration to an area of low concentration by <strong>simple diffusion</strong>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>2. Movement of Water (H₂O) by Osmosis:</strong><br>\r\n  • Water moves across the selectively permeable plasma membrane following the law of diffusion, specifically termed <strong>osmosis</strong>.<br>\r\n  • The net direction and rate of water movement depend on the water potential (solute concentration) difference between the inside and outside of the cell:<br>\r\n    - In a <em>hypotonic solution</em>, water enters the cell (endosmosis), causing it to swell.<br>\r\n    - In a <em>hypertonic solution</em>, water leaves the cell (exosmosis), causing it to shrink.<br>\r\n    - In an <em>isotonic solution</em>, there is no net movement of water.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism of CO₂ transport via simple diffusion down concentration gradient</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism of H₂O transport via osmosis across selectively permeable membrane</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_in_4')\">\r\n      <div class=\"q-num\">Page 61 — Q2</div>\r\n      <div class=\"q-text\">Why is the plasma membrane called a selectively permeable membrane?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Explanation:</strong><br>\r\n  The plasma membrane is termed <strong>selectively permeable</strong> because:\r\n  <ol>\r\n    <li>It permits the selective passage and entry/exit of only specific substances (such as respiratory gases O₂ and CO₂, water, glucose, and essential ions) into and out of the cell.</li>\r\n    <li>It simultaneously acts as an impenetrable barrier that prevents the movement of harmful foreign substances, large unwanted macromolecules, or the leakage of vital cellular cytoplasmic components out of the cell.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Allows entry and exit of only selected substances based on size/charge</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Blocks passage of other materials, maintaining internal cellular integrity</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 65)</div>\r\n\r\n  <div class=\"q-card\" id=\"q5_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_in_5')\">\r\n      <div class=\"q-num\">Page 65 — Q1</div>\r\n      <div class=\"q-text\">Can you name the two organelles we have studied that contain their own genetic material?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Semi-Autonomous Organelles:</strong><br>\r\n  The two cytoplasmic organelles that possess their own genetic material are:\r\n  <ol>\r\n    <li><strong>Mitochondria:</strong> Contain their own circular double-stranded DNA molecules and 70S ribosomes, allowing them to synthesize some of their own proteins and enzymes.</li>\r\n    <li><strong>Plastids (e.g. Chloroplasts in plant cells):</strong> Possess their own circular DNA and 70S ribosomes, enabling them to replicate semi-autonomously.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mitochondria (with mention of circular DNA and ribosomes)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Plastids / Chloroplasts (with mention of DNA and ribosomes)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_in_6')\">\r\n      <div class=\"q-num\">Page 65 — Q2</div>\r\n      <div class=\"q-text\">If the organisation of a cell is destroyed due to some physical or chemical influence, what will happen?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Consequences of Structural Destruction:</strong><br>\r\n  1. The cell's compartmentalization, selective membrane permeability, and organelle coordination will break down completely.<br>\r\n  2. The cell will be unable to carry out basic life-sustaining metabolic functions such as respiration, protein synthesis, active transport, and waste clearance.<br>\r\n  3. The damaged membrane will cause lysosomes to rupture, releasing powerful hydrolytic digestive enzymes that will digest and self-destruct the dead cell components.<br>\r\n  4. Ultimately, <strong>the cell will cease to live and die</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Loss of metabolic functions (respiration, protein synthesis)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Lysis of cell contents by lysosomal enzymes leading to cell death</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_in_7')\">\r\n      <div class=\"q-num\">Page 65 — Q3</div>\r\n      <div class=\"q-text\">Why are lysosomes known as suicide bags?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Hydrolytic Action of Lysosomes:</strong><br>\r\n  1. Lysosomes are membrane-bound vesicular organelles containing powerful <strong>hydrolytic digestive enzymes</strong> (synthesized by the Rough Endoplasmic Reticulum) capable of breaking down all organic polymers.<br>\r\n  2. When a cell gets infected, damaged, aged, or when its cellular metabolism is irreversibly disturbed, the lysosomal membrane ruptures.<br>\r\n  3. The released active digestive enzymes pour into the cytoplasm and digest their own cell from within (autolysis).<br>\r\n  4. Hence, lysosomes are famously termed the <strong>'suicide bags'</strong> of a cell.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Contain powerful hydrolytic/digestive enzymes synthesized by RER</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Rupture during cell damage/aging, digesting their own cellular contents (autolysis)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_in_8')\">\r\n      <div class=\"q-num\">Page 65 — Q4</div>\r\n      <div class=\"q-text\">Where are proteins synthesised inside the cell?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Site of Protein Synthesis:</strong><br>\r\n  • Proteins are synthesized on sub-microscopic non-membrane-bound granular organelles called <strong>Ribosomes</strong>.<br>\r\n  • Ribosomes are found either attached to the outer surface of the <strong>Rough Endoplasmic Reticulum (RER)</strong> (which gives it a rough, studded appearance under an electron microscope) or floating freely within the <strong>cytosol</strong>.<br>\r\n  • The synthesized proteins are then transported by the ER to the Golgi apparatus for modification, packaging, and dispatch.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Ribosomes as protein factories</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Attached to Rough Endoplasmic Reticulum (RER) and free in cytoplasm</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q5_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">Make a comparison and write down ways in which plant cells are different from animal cells.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comprehensive Comparison: Plant Cell vs Animal Cell:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Plant Cell</th><th>Animal Cell</th></tr>\r\n    <tr><td><strong>Cell Wall</strong></td><td>Present (rigid outer layer made of cellulose).</td><td>Completely absent (enclosed only by plasma membrane).</td></tr>\r\n    <tr><td><strong>Plastids</strong></td><td>Present (chloroplasts, chromoplasts, leucoplasts).</td><td>Absent (cannot perform photosynthesis).</td></tr>\r\n    <tr><td><strong>Vacuoles</strong></td><td>A single, very large central permanent vacuole (occupies 50–90% cell volume).</td><td>Small, temporary, and multiple vacuoles (if present).</td></tr>\r\n    <tr><td><strong>Centrosome / Centrioles</strong></td><td>Absent in higher plants (mitotic spindle forms without centrioles).</td><td>Present (centrosome with paired centrioles organizes spindle).</td></tr>\r\n    <tr><td><strong>Nucleus Position</strong></td><td>Pushed to the periphery due to the large central vacuole.</td><td>Typically located centrally in the cytoplasm.</td></tr>\r\n    <tr><td><strong>Stored Food</strong></td><td>Stored primarily as starch grains.</td><td>Stored primarily as glycogen granules and fats.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cell wall and plastids comparison</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Vacuole size and centrosome comparison</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Nucleus position and storage food comparison</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">How is a prokaryotic cell different from a eukaryotic cell?</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison: Prokaryotic Cell vs Eukaryotic Cell:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Prokaryotic Cell (e.g. Bacteria)</th><th>Eukaryotic Cell (e.g. Plant, Animal, Fungi)</th></tr>\r\n    <tr><td><strong>Size</strong></td><td>Generally small (1–10 µm)</td><td>Generally large (5–100 µm)</td></tr>\r\n    <tr><td><strong>Nuclear Region</strong></td><td>Poorly defined; lacks nuclear membrane. Known as <strong>nucleoid</strong>.</td><td>Well defined; surrounded by a double-layered nuclear membrane.</td></tr>\r\n    <tr><td><strong>Chromosome</strong></td><td>Single circular chromosome (naked DNA without histones).</td><td>More than one linear chromosome (DNA complexed with histones).</td></tr>\r\n    <tr><td><strong>Membrane-bound Organelles</strong></td><td>Completely absent (no mitochondria, plastids, ER, Golgi, lysosomes).</td><td>Present (mitochondria, chloroplasts, Golgi apparatus, ER, lysosomes).</td></tr>\r\n    <tr><td><strong>Ribosomes</strong></td><td>Smaller 70S type ribosomes</td><td>Larger 80S type ribosomes (70S in mitochondria/plastids)</td></tr>\r\n    <tr><td><strong>Cell Division</strong></td><td>Divides by fission or budding (no mitosis/meiosis).</td><td>Divides by organized mitosis or meiosis.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Nuclear region (nucleoid vs true nucleus with nuclear envelope)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Membrane-bound organelles comparison</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Chromosomes, ribosomes, and cell division comparison</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">What would happen if the plasma membrane ruptures or breaks down?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Consequences of Plasma Membrane Rupture:</strong><br>\r\n  1. The plasma membrane provides structural containment and maintains the homeostatic balance of the internal cytoplasmic environment.<br>\r\n  2. If it ruptures or breaks down, the selective permeability barrier is permanently destroyed.<br>\r\n  3. Cytoplasmic contents, organelles, and enzymes will spill out into the extracellular environment, while uncontrolled substances and water rush in.<br>\r\n  4. Cellular metabolism immediately collapses, and the <strong>cell dies</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Destruction of selective permeability and spillage of cellular contents</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Inability to maintain homeostatic metabolism leading to cell death</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">What would happen to the life of a cell if there was no Golgi apparatus?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Crucial Roles of Golgi Apparatus:</strong><br>\r\n  The Golgi apparatus (discovered by Camillo Golgi) acts as the central shipping, packaging, and dispatch department of the cell. If it were absent:\r\n  <ol>\r\n    <li><strong>Packaging & Modification Failure:</strong> Proteins and lipids synthesized by the endoplasmic reticulum could not be modified (e.g. glycosylation into glycoproteins/glycolipids), concentrated, or packaged into secretory vesicles.</li>\r\n    <li><strong>Intracellular Transport Breakdown:</strong> Materials could not be dispatched to intracellular targets or secreted outside the cell membrane.</li>\r\n    <li><strong>No Lysosome Formation:</strong> Lysosomes are formed through the budding of Golgi cisternae. In its absence, no lysosomes would be produced, preventing cellular waste digestion and autophagy, poisoning the cell with accumulated debris.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Inability to modify, package, and dispatch proteins/lipids from ER</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Disruption of secretor transport to plasma membrane</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Failure to produce lysosomes leading to cell degeneration</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">Which organelle is known as the powerhouse of the cell? Why?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>The Powerhouse of the Cell: Mitochondria.</strong><br><br>\r\n  <strong>Reasons:</strong>\r\n  <ol>\r\n    <li>Mitochondria are the primary sites of cellular aerobic respiration. They oxidize carbohydrate and lipid metabolic products (pyruvate, fatty acids) in the presence of oxygen.</li>\r\n    <li>During this oxidation, energy is released and captured in the high-energy phosphoanhydride bonds of <strong>Adenosine Triphosphate (ATP)</strong> molecules.</li>\r\n    <li>ATP is universally recognized as the <strong>energy currency of the cell</strong>. The cell utilizes the energy stored in ATP to perform mechanical work (muscle contraction, locomotion) and synthesize chemical compounds (proteins, nucleic acids).</li>\r\n    <li>Mitochondria feature a deeply folded inner membrane (forming <em>cristae</em>) that provides a massive surface area for ATP-generating electron transport enzyme complexes.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Mitochondria as powerhouse of the cell</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Generation of energy in the form of ATP through cellular respiration</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of ATP as energy currency and role of cristae surface area</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">Where do the lipids and proteins constituting the cell membrane get synthesised?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Biosynthesis of Membrane Components (Membrane Biogenesis):</strong><br>\r\n  • <strong>Proteins:</strong> Synthesized by <strong>Ribosomes</strong> bound to the <strong>Rough Endoplasmic Reticulum (RER)</strong>.<br>\r\n  • <strong>Lipids (Phospholipids and Sterols):</strong> Synthesized by the <strong>Smooth Endoplasmic Reticulum (SER)</strong>.<br><br>\r\n  These newly formed lipids and proteins are transported via vesicles to the Golgi complex and then incorporated into the plasma membrane during the process known as <strong>membrane biogenesis</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Proteins synthesized by ribosomes on Rough Endoplasmic Reticulum (RER)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Lipids synthesized by Smooth Endoplasmic Reticulum (SER)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">How does an Amoeba obtain its food?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Endocytosis / Phagocytosis in Amoeba:</strong><br>\r\n  1. Amoeba is a unicellular, eukaryotic freshwater protozoan with a flexible, fluid plasma membrane.<br>\r\n  2. When an Amoeba senses a microscopic food particle nearby, it extends finger-like temporary projections of its cytoplasm called <strong>pseudopodia</strong> (false feet) around the food particle.<br>\r\n  3. The pseudopodia engulf and fuse around the food particle, forming a membrane-bound vesicle called a <strong>food vacuole</strong>. This process of engulfing extracellular food via membrane flexibility is called <strong>endocytosis (or phagocytosis)</strong>.<br>\r\n  4. Lysosomal digestive enzymes enter the food vacuole to hydrolyze complex nutrients into soluble forms, which diffuse into the cytoplasm.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Extension of pseudopodia engulfing food into food vacuole</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of endocytosis / phagocytosis due to membrane flexibility</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">What is osmosis?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Definition:</strong><br>\r\n  <strong>Osmosis</strong> is the spontaneous net movement of solvent (water) molecules from a region of higher water concentration (dilute solution with lower solute concentration) to a region of lower water concentration (concentrated solution with higher solute concentration) across a <strong>selectively permeable membrane</strong> until dynamic equilibrium is established.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Net passage of water from higher water concentration to lower water concentration</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Movement across a selectively permeable membrane</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">Carry out the following potato osmoscope experiment:<br>\r\nTake four peeled potato halves and scoos each one out to make potato cups. One of these potato cups should be made from a boiled potato. Put each potato cup in a trough containing water. Now:<br>\r\n(a) Keep cup A empty<br>\r\n(b) Put one teaspoon sugar in cup B<br>\r\n(c) Put one teaspoon salt in cup C<br>\r\n(d) Put one teaspoon sugar in the boiled potato cup D.<br>\r\nKeep these for two hours. Then observe the four potato cups and answer the following:<br>\r\n(i) Explain why water gathers in the hollowed portion of B and C.<br>\r\n(ii) Why is potato A necessary for this experiment?<br>\r\n(iii) Explain why water does not gather in the hollowed out portions of A and D.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(i) Why water gathers in cups B and C:</strong><br>\r\n  In cups B (sugar) and C (salt), the high concentration of solute inside the cavity creates a <strong>hypertonic environment</strong> (low water concentration). The water in the trough represents a pure hypotonic medium (high water concentration). Water moves across the living, selectively permeable membranes of the potato tuber cells into the cavity by <strong>endosmosis</strong>, accumulating liquid inside.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(ii) Role of Potato A:</strong><br>\r\n  Potato cup A is empty; it acts as a <strong>control experiment</strong>. It proves that the accumulation of water in cups B and C is solely due to the presence of solute creating an osmotic gradient, and not simply due to physical suction or natural seeping through potato tissue.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(iii) Why water does not gather in A and D:</strong><br>\r\n  • <strong>In Cup A:</strong> There is no solute inside the cavity, so there is no concentration gradient or osmotic difference to drive water movement.<br>\r\n  • <strong>In Cup D (Boiled Potato):</strong> Boiling denatures cellular proteins and permanently kills the potato cells. Dead cell membranes lose their semi-permeable / selectively permeable properties and become freely permeable. Without intact semi-permeable membranes, osmosis cannot take place.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Endosmosis in B and C due to hypertonic solute cavity</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Cup A acts as control experiment</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Lack of gradient in A; boiling destroys cell membrane selectively in D</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q5_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">Which type of cell division is required for growth and repair of body and which type is involved in formation of gametes?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Types of Cell Division:</strong><br>\r\n  1. <strong>For Growth and Tissue Repair:</strong> <strong>Mitosis (Equational division)</strong>.<br>\r\n     • A parent diploid cell divides into two genetically identical daughter cells, maintaining the exact chromosome number (<span class=\"math\">2n ⟶ 2n</span>), essential for somatic body growth, development, and tissue healing.<br><br>\r\n  2. <strong>For Formation of Gametes:</strong> <strong>Meiosis (Reductional division)</strong>.<br>\r\n     • Specific diploid reproductive germ cells divide twice to produce four haploid gametes (sperm and ova), halving the chromosome number (<span class=\"math\">2n ⟶ n</span>). This ensures that upon fertilization, the original diploid chromosome number of the species is conserved.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mitosis for body growth and repair (maintains chromosome number)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Meiosis for gamete formation (halves chromosome number)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 5</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Osmotic Responses in Blood and Plant Cells:</strong> Fresh RBCs and plant epidermal peel cells are placed in three beakers containing: (A) Pure distilled water, (B) 0.9% NaCl solution, and (C) Concentrated 10% NaCl solution.<br>(a) What will happen to RBCs in beaker A? How will plant cells behave differently?<br>(b) What term describes the state of plant cells in beaker C?<br>(c) Which structure provides mechanical strength to plant cells against bursting?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> In beaker A (hypotonic), RBCs will swell and burst (hemolysis) because animal cells lack a cell wall. Plant cells will swell and become <em>turgid</em>, but will not burst.<br><strong>(b)</strong> The plant cells will undergo <strong>plasmolysis</strong> (shrinkage of protoplast away from the rigid cell wall due to exosmosis).<br><strong>(c)</strong> The rigid, cellulose <strong>cell wall</strong> exerts turgor counter-pressure that prevents osmotic rupture.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why are mitochondria and plastids called semi-autonomous organelles?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">They are termed semi-autonomous because: (1) They contain their own extranuclear circular DNA, (2) They possess their own 70S ribosomes and RNA, enabling them to synthesize some of their own structural proteins and enzymes, and (3) They can self-replicate by binary fission independently within the host eukaryotic cell.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(4)\">← Chapter 4</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\">Chapter 6 →</button>\r\n  </div>\r\n</section>","6":"<section class=\"chapter-section\" id=\"ch6\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">6</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 6: Tissues</h2>\r\n      <p>Plant Tissues (Meristematic & Permanent), Animal Tissues (Epithelial, Connective, Muscular & Nervous) — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 69)</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_1')\">\r\n      <div class=\"q-num\">Page 69 — Q1</div>\r\n      <div class=\"q-text\">What is a tissue?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Definition:</strong><br>\r\n  A <strong>tissue</strong> is defined as a cluster or group of structurally similar (or coordinated) cells that have a common embryonic origin and work together synergistically to perform a specific, specialized physiological function within a multicellular organism.<br>\r\n  <em>Examples:</em> Phloem tissue in vascular plants (specialized for translocation of organic nutrients), Nervous tissue in animals (specialized for conduction of electrical impulses).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: Group of similar cells with common origin working together for specific function</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Valid plant or animal example given</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_2')\">\r\n      <div class=\"q-num\">Page 69 — Q2</div>\r\n      <div class=\"q-text\">What is the utility of tissues in multi-cellular organisms?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Utility & Advantages of Tissues:</strong>\r\n  <ol>\r\n    <li><strong>Division of Labour:</strong> In multicellular organisms, different groups of specialized cells (tissues) take charge of distinct physiological tasks. For example, muscle tissues contract to produce movement, nerve cells transmit impulses, and xylem transports water.</li>\r\n    <li><strong>Higher Functional Efficiency:</strong> Cells specialized for one particular task carry out that function with maximum efficiency and precision compared to a solitary cell trying to perform all tasks.</li>\r\n    <li><strong>Structural Organization & Complexity:</strong> Tissues assemble into organs and organ systems, conferring higher morphological complexity, physical strength, and endurance.</li>\r\n    <li><strong>Enhanced Survival Rate:</strong> Multicellular organization ensures that damage to a single cell or group of cells does not immediately kill the entire organism.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Division of labour among specialized cell groups</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Higher functional efficiency and precision</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Organ formation and enhanced survival capability</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 74)</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_3')\">\r\n      <div class=\"q-num\">Page 74 — Q1</div>\r\n      <div class=\"q-text\">Name types of simple tissues.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Simple Permanent Tissues in Plants:</strong><br>\r\n  Simple tissues are composed of only one single type of structurally identical cells. The three main types are:\r\n  <ol>\r\n    <li><strong>Parenchyma:</strong> Living, unspecialized cells with thin cellulose walls; primary site for food storage, photosynthesis (chlorenchyma), and buoyancy (aerenchyma).</li>\r\n    <li><strong>Collenchyma:</strong> Living cells with localized pectin and cellulose thickenings at the corners; provides flexibility and mechanical support without breaking.</li>\r\n    <li><strong>Sclerenchyma:</strong> Dead cells with heavily lignified, thick secondary walls and narrow lumens; provides immense rigidity, hardness, and mechanical strength.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing Parenchyma, Collenchyma, and Sclerenchyma</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Brief structural/functional identification of each</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_4')\">\r\n      <div class=\"q-num\">Page 74 — Q2</div>\r\n      <div class=\"q-text\">Where is apical meristem found?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Location and Role of Apical Meristem:</strong><br>\r\n  • <strong>Location:</strong> Apical meristematic tissue is located at the <strong>growing tips of stems (shoot apices)</strong> and <strong>growing tips of roots (root apices)</strong> in plants.<br>\r\n  • <strong>Function:</strong> It consists of continuously actively dividing cells responsible for primary growth, leading to an increase in the linear length (elongation) of stems and roots.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating location at the growing tips of stems and roots</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning primary growth / elongation function</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_5')\">\r\n      <div class=\"q-num\">Page 74 — Q3</div>\r\n      <div class=\"q-text\">Which tissue makes up the husk of coconut?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Tissue Identity & Characteristics:</strong><br>\r\n  • The fibrous husk of a coconut (coir) is made up of <strong>Sclerenchyma tissue</strong> (specifically <em>sclerenchymatous fibres</em>).<br>\r\n  • <strong>Characteristics:</strong><br>\r\n    - The cells of this tissue are dead at maturity.<br>\r\n    - They have extremely thick secondary cell walls heavily deposited with <strong>lignin</strong> (a natural chemical cement that hardens walls).<br>\r\n    - They lack intracellular protoplasm and have narrow lumens, conferring extreme tensile strength, stiffness, and durability to protect the coconut seed.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification: Sclerenchymatous tissue / fibres</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of dead cells with heavily lignified thick walls</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_6')\">\r\n      <div class=\"q-num\">Page 74 — Q4</div>\r\n      <div class=\"q-text\">What are the constituents of phloem?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Four Major Constituents of Phloem Tissue:</strong>\r\n  <ol>\r\n    <li><strong>Sieve Tubes (and Sieve Cells):</strong> Tubular cells with perforated end-walls (sieve plates) through which photosynthesized sugars flow.</li>\r\n    <li><strong>Companion Cells:</strong> Specialized parenchymatous living cells closely associated with sieve tube elements, possessing active nuclei that regulate sieve tube transport.</li>\r\n    <li><strong>Phloem Parenchyma:</strong> Living elongated cells that store food (starch, resins, latex) and assist in lateral conduction.</li>\r\n    <li><strong>Phloem Fibres (Bast Fibres):</strong> Dead, highly lignified sclerenchymatous cells that provide mechanical tensile support. (Note: Phloem fibres are the only dead elements of phloem; the other three are living).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing all four components: Sieve tubes, Companion cells, Phloem parenchyma, Phloem fibres</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Distinguishing living components from dead phloem fibres</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 78)</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_7')\">\r\n      <div class=\"q-num\">Page 78 — Q1</div>\r\n      <div class=\"q-text\">Name the tissue responsible for movement in our body.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  <strong>Muscular tissue</strong> (composed of elongated muscle fibres containing specialized contractile proteins like actin and myosin, which contract and relax to generate force and body movement).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Muscular tissue (with mention of contractile proteins)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_8')\">\r\n      <div class=\"q-num\">Page 78 — Q2</div>\r\n      <div class=\"q-text\">What does a neuron look like?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Morphology of a Neuron (Nerve Cell):</strong><br>\r\n  A neuron resembles a tiny branched tree. It consists of three distinct anatomical regions:\r\n  <ol>\r\n    <li><strong>Cyton (Cell Body / Soma):</strong> Contains a prominent spherical nucleus, neuroplasm, and Nissl's granules.</li>\r\n    <li><strong>Dendrites:</strong> Short, highly branched, tapering cytoplasmic extensions emerging from the cyton that receive incoming nerve impulses from receptors or other neurons.</li>\r\n    <li><strong>Axon:</strong> A single, long, cylindrical cytoplasmic nerve fibre extending away from the cell body (often insulated by a myelin sheath) that transmits electrical action potentials away to terminal arborizations and synaptic knobs. Neurons can be up to a metre long in humans.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Description of cyton/cell body with nucleus and cytoplasm</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Description of branched dendrites receiving signals</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Description of long single axon conducting impulses away</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_9')\">\r\n      <div class=\"q-num\">Page 78 — Q3</div>\r\n      <div class=\"q-text\">Give three features of cardiac muscles.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Characteristic Features of Cardiac Muscle Tissue:</strong>\r\n  <ol>\r\n    <li><strong>Involuntary and Rhythmic:</strong> They work automatically and unconsciously under autonomic control; they contract and relax rhythmically throughout life without showing physical fatigue.</li>\r\n    <li><strong>Cylindrical and Branched:</strong> Cardiac muscle cells are cylindrical fibres interconnected by specialized lateral oblique bridges, forming a 3D syncytial network.</li>\r\n    <li><strong>Uninucleate with Intercalated Discs:</strong> Each muscle cell typically contains a single centrally located nucleus and features dark transverse junctions called <strong>intercalated discs</strong> that allow rapid electrical coupling between adjacent cells. They also exhibit faint transverse striations.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Involuntary rhythmic contraction without fatigue</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cylindrical, branched structural network</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Uninucleate with intercalated discs and faint striations</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_in_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_in_10')\">\r\n      <div class=\"q-num\">Page 78 — Q4</div>\r\n      <div class=\"q-text\">What are the functions of areolar tissue?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Functions of Areolar Connective Tissue:</strong><br>\r\n  Areolar tissue is a loose connective tissue found between skin and muscles, around blood vessels and nerves, and in the bone marrow. Its key functions are:\r\n  <ol>\r\n    <li><strong>Packing and Structural Cushioning:</strong> It acts as a supportive packing tissue filling empty spaces inside organs and binding neighboring anatomical structures together.</li>\r\n    <li><strong>Support to Internal Organs:</strong> It anchors blood vessels and nerve bundles in place within organ parenchyma.</li>\r\n    <li><strong>Tissue Repair:</strong> Its fibroblast and macrophage cells play an active role in wound healing, collagen deposition, and defense against localized pathogens.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Acts as packing tissue filling spaces and connecting skin to muscle</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Supports internal organs and aids in rapid tissue repair</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">Define the term 'tissue'.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  A <strong>tissue</strong> is a group or collection of structurally similar cells having a common embryonic origin that work together in a coordinated manner to perform a specific physiological function.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate standard biological definition of tissue</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">How many types of elements together make up the xylem tissue? Name them.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Four Types of Elements Make Up Xylem Tissue:</strong>\r\n  <ol>\r\n    <li><strong>Tracheids:</strong> Elongated, dead cells with tapering ends, lignified walls, and pits for water conduction.</li>\r\n    <li><strong>Vessels:</strong> Long, continuous tubular pipes formed by end-to-end fusion of dead cylindrical cells with dissolved end walls.</li>\r\n    <li><strong>Xylem Parenchyma:</strong> The <em>only living element</em> of xylem; stores starch and fats and assists in lateral sideways conduction of water.</li>\r\n    <li><strong>Xylem Sclerenchyma (Xylem Fibres):</strong> Highly lignified dead fibres providing tensile mechanical strength to plant axes.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating four elements: Tracheids, Vessels, Xylem parenchyma, Xylem fibres</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Highlighting that Xylem parenchyma is the only living component</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">How are simple tissues different from complex tissues in plants?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison: Simple Plant Tissues vs Complex Plant Tissues:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Simple Permanent Tissue</th><th>Complex Permanent Tissue</th></tr>\r\n    <tr><td><strong>Cellular Composition</strong></td><td>Composed of only <strong>one single type</strong> of structurally and functionally identical cells.</td><td>Composed of <strong>more than one type</strong> of distinct cells working coordinately as a unit.</td></tr>\r\n    <tr><td><strong>Location</strong></td><td>Distributed throughout ground tissue (cortex, pith, epidermis).</td><td>Restricted to vascular bundles (conducting channels).</td></tr>\r\n    <tr><td><strong>Primary Function</strong></td><td>Packaging, photosynthesis, food storage, and primary mechanical support.</td><td>Long-distance conducting/translocation of water, minerals, and organic food.</td></tr>\r\n    <tr><td><strong>Examples</strong></td><td>Parenchyma, Collenchyma, Sclerenchyma.</td><td>Xylem and Phloem.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">One type of cell vs multiple cell types working as a unit</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Functions and distribution compared</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate examples of each category</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">Differentiate between parenchyma, collenchyma and sclerenchyma on the basis of their cell wall.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Cell Wall Differentiation:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Parenchyma</th><th>Collenchyma</th><th>Sclerenchyma</th></tr>\r\n    <tr><td><strong>Wall Thickness</strong></td><td>Evenly thin primary cell walls.</td><td>Unevenly thickened cell walls.</td><td>Extremely thick, rigid secondary cell walls.</td></tr>\r\n    <tr><td><strong>Chemical Composition</strong></td><td>Composed purely of <strong>cellulose and hemicellulose</strong>.</td><td>Heavy deposition of <strong>pectin and cellulose</strong> localized specifically at the corners of cells.</td><td>Thick, uniform deposition of <strong>lignin</strong> (a waterproof chemical cement).</td></tr>\r\n    <tr><td><strong>Cell Lumen & State</strong></td><td>Wide central lumen; cells are <strong>living</strong> with active protoplasm.</td><td>Moderate lumen; cells are <strong>living</strong> with active protoplasm.</td><td>Lumen is almost entirely obliterated (very narrow); cells are <strong>dead</strong>.</td></tr>\r\n    <tr><td><strong>Pits</strong></td><td>Normal simple plasmodesmata.</td><td>Simple pits may be present.</td><td>Numerous deep pits connect neighboring thick-walled cells.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Parenchyma: thin cellulose walls</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Collenchyma: walls thickened with pectin at corners</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Sclerenchyma: heavily lignified, dead, thick secondary walls</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">What are the functions of the stomata?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Functions of Stomata:</strong><br>\r\n  Stomata are microscopic pores located in the leaf epidermis, bounded by a pair of specialized kidney-shaped (or dumb-bell-shaped in grasses) <strong>guard cells</strong>.<br>\r\n  <ol>\r\n    <li><strong>Gaseous Exchange:</strong> They facilitate the bidirectional diffusion of respiratory gases (<span class=\"math\">O₂</span> intake and <span class=\"math\">CO₂</span> release during respiration; <span class=\"math\">CO₂</span> intake and <span class=\"math\">O₂</span> release during photosynthesis) between internal mesophyll tissue and atmosphere.</li>\r\n    <li><strong>Transpiration:</strong> They regulate the loss of excess water in the form of water vapour from the aerial surfaces of leaves. Transpiration creates the <em>transpiration pull</em> essential for water and mineral ascent in tall trees and provides evaporative cooling to prevent heat injury.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Exchange of respiratory and photosynthetic gases (CO₂ and O₂)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Transpiration (cooling and driving transpirational suction pull)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">Diagrammatically show the difference between the three types of muscle fibres.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Structural Features of Muscle Fibres:</strong><br>\r\n  • <strong>1. Striated (Skeletal) Muscle:</strong> Long, unbranched, cylindrical fibres; multinucleate (peripheral nuclei); distinct alternate dark (A) and light (I) cross-striations.<br>\r\n  • <strong>2. Smooth (Unstriated) Muscle:</strong> Spindle-shaped (fusiform) fibres with pointed ends; uninucleate (single central oval nucleus); no striations.<br>\r\n  • <strong>3. Cardiac Muscle:</strong> Short, cylindrical, branched fibres forming an anastomosing network; uninucleate; faint striations with prominent transverse <strong>intercalated discs</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Striated: Cylindrical, unbranched, multinucleate, alternate bands</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Smooth: Spindle-shaped, unstriated, uninucleate</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cardiac: Cylindrical, branched, uninucleate, intercalated discs</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">What is the specific function of the cardiac muscle?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Specific Function:</strong><br>\r\n  1. Cardiac muscle forms the muscular wall (myocardium) of the heart.<br>\r\n  2. Its unique and vital physiological function is to produce <strong>continuous, rhythmic, tireless, and involuntary contractions and relaxations</strong> throughout the entire lifetime of an individual.<br>\r\n  3. By pumping rhythmically without a single moment of fatigue, it continuously propels deoxygenated blood to the lungs and oxygenated blood to all systemic organs, sustaining cellular life.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Continuous involuntary, rhythmic contraction and relaxation without fatigue</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Pumping and circulation of blood throughout the vascular system of the body</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">Differentiate between striated, unstriated and cardiac muscles on the basis of their structure and site/location in the body.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comprehensive Comparison of Muscle Types:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Striated (Skeletal) Muscle</th><th>Smooth (Unstriated) Muscle</th><th>Cardiac Muscle</th></tr>\r\n    <tr><td><strong>Shape</strong></td><td>Long, cylindrical, unbranched</td><td>Spindle-shaped (tapering ends)</td><td>Cylindrical, branched network</td></tr>\r\n    <tr><td><strong>Striations (Bands)</strong></td><td>Prominent alternate dark & light bands</td><td>Completely absent (smooth)</td><td>Faint cross-striations present</td></tr>\r\n    <tr><td><strong>Nucleus</strong></td><td>Multinucleate (nuclei at periphery)</td><td>Uninucleate (single central nucleus)</td><td>Uninucleate (centrally located)</td></tr>\r\n    <tr><td><strong>Intercalated Discs</strong></td><td>Absent</td><td>Absent</td><td>Present (specialized cell junctions)</td></tr>\r\n    <tr><td><strong>Nature of Action</strong></td><td>Voluntary (under conscious will)</td><td>Involuntary (autonomic control)</td><td>Involuntary (rhythmic myogenic)</td></tr>\r\n    <tr><td><strong>Fatigue Rate</strong></td><td>Fatigues quickly upon prolonged work</td><td>Slow to fatigue; sustained contraction</td><td>Never fatigues; contracts for life</td></tr>\r\n    <tr><td><strong>Site / Location</strong></td><td>Attached to skeletal bones (limbs, tongue, neck, diaphragm)</td><td>Walls of visceral organs: stomach, intestine, blood vessels, iris, uterus</td><td>Found strictly and exclusively in the muscular heart wall (myocardium)</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Structural comparison (shape, nuclei, striations, intercalated discs)</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Action and fatigue characteristics compared</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Precise anatomical locations for all three types</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">Draw a labelled diagram of a neuron.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Key Components of a Standard Motor Neuron:</strong>\r\n  <ul>\r\n    <li><strong>Dendrites:</strong> Multiple fine branched terminal cytoplasmic projections receiving inputs.</li>\r\n    <li><strong>Cyton (Soma):</strong> Central broad cell body containing neuroplasm and a distinct nucleus.</li>\r\n    <li><strong>Nucleus:</strong> Large central spherical genetic control center.</li>\r\n    <li><strong>Axon:</strong> Long, slender uniform nerve fibre conducting action potentials away.</li>\r\n    <li><strong>Myelin Sheath:</strong> Insulating lipid layer punctuated at gaps called <em>Nodes of Ranvier</em>.</li>\r\n    <li><strong>Axon Terminal / Synaptic Knobs:</strong> Bulbous ends that release neurotransmitters across the synapse to the next neuron or muscle effector.</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Dendrites, Cyton, and Nucleus correctly identified</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Axon, Myelin sheath, and Nerve endings correctly identified</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">Name the following:<br>\r\n(a) Tissue that forms the inner lining of our mouth.<br>\r\n(b) Tissue that connects muscle to bone in humans.<br>\r\n(c) Tissue that transports food in plants.<br>\r\n(d) Tissue that stores fat in our body.<br>\r\n(e) Connective tissue with a fluid matrix.<br>\r\n(f) Tissue present in the brain.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Identifications:</strong>\r\n  <ul>\r\n    <li><strong>(a) Inner lining of our mouth:</strong> <strong>Squamous epithelium</strong> (specifically non-keratinized stratified squamous epithelium).</li>\r\n    <li><strong>(b) Muscle to bone connector:</strong> <strong>Tendon</strong> (dense regular fibrous connective tissue).</li>\r\n    <li><strong>(c) Transports food in plants:</strong> <strong>Phloem</strong> (complex permanent vascular tissue).</li>\r\n    <li><strong>(d) Stores fat in our body:</strong> <strong>Adipose tissue</strong> (contains specialized adipocyte cells filled with lipid droplets).</li>\r\n    <li><strong>(e) Connective tissue with fluid matrix:</strong> <strong>Blood</strong> (matrix is liquid plasma; Lymph is also valid).</li>\r\n    <li><strong>(f) Tissue present in the brain:</strong> <strong>Nervous tissue</strong> (composed of neurons and neuroglial support cells).</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Squamous epithelium, (b) Tendon</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Phloem, (d) Adipose tissue</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Blood / Lymph, (f) Nervous tissue</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_11')\">\r\n      <div class=\"q-num\">Exercise — Q11</div>\r\n      <div class=\"q-text\">Identify the type of tissue in the following: skin, bark of tree, bone, lining of kidney tubule, vascular bundle.</div>\r\n      <div class=\"q-marks\">2½ Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Tissue Classification:</strong>\r\n  <ol>\r\n    <li><strong>Skin:</strong> <strong>Stratified squamous epithelium</strong> (multi-layered epithelial tissue protecting against mechanical wear).</li>\r\n    <li><strong>Bark of tree:</strong> <strong>Cork / Phellem (Protective secondary tissue)</strong> with suberin deposits.</li>\r\n    <li><strong>Bone:</strong> <strong>Hard / Specialized skeletal connective tissue</strong> (with mineralized calcium-phosphate osteocyte matrix).</li>\r\n    <li><strong>Lining of kidney tubule:</strong> <strong>Cuboidal epithelium</strong> (specialized for absorption and secretion).</li>\r\n    <li><strong>Vascular bundle:</strong> <strong>Complex permanent conducting tissue (Xylem and Phloem)</strong>.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Skin: Stratified squamous epithelium</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Bark: Cork / protective tissue</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Bone: Skeletal connective tissue</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Lining of kidney tubule: Cuboidal epithelium</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Vascular bundle: Xylem and Phloem</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_12')\">\r\n      <div class=\"q-num\">Exercise — Q12</div>\r\n      <div class=\"q-text\">Name the regions in which parenchyma tissue is present.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Occurrence and Distribution of Parenchyma:</strong><br>\r\n  Parenchyma forms the major bulk of the plant body (ground tissue) and is found in:\r\n  <ol>\r\n    <li><strong>Cortex, Pith, and Medullary Rays</strong> of roots and dicot/monocot stems.</li>\r\n    <li><strong>Mesophyll of Leaves:</strong> Present as specialized photosynthetic <em>chlorenchyma</em> (palisade and spongy parenchyma) containing chloroplasts.</li>\r\n    <li><strong>Petioles, Flowers, and Fruits:</strong> Forms the fleshy pulp of edible fruits (e.g. apples, tomatoes) and endosperm of seeds storing starch and nutrients.</li>\r\n    <li><strong>Aquatic Plants:</strong> Forms <em>aerenchyma</em> with large air cavities in petiole and leaves of hydrophytes (e.g. lotus, hydrilla) to provide buoyancy.</li>\r\n    <li><strong>Vascular Bundles:</strong> Present as xylem parenchyma and phloem parenchyma.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning cortex, pith, and medullary rays of stems/roots</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning leaf mesophyll (chlorenchyma), aquatic aerenchyma, and fruit flesh</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_13')\">\r\n      <div class=\"q-num\">Exercise — Q13</div>\r\n      <div class=\"q-text\">What is the role of epidermis in plants?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Protective Functions of Plant Epidermis:</strong>\r\n  <ol>\r\n    <li><strong>Barrier & Protection:</strong> Forms a continuous single outermost protective sheet covering the entire plant body, shielding internal tissues against mechanical injury, desiccation, and parasite invasion.</li>\r\n    <li><strong>Prevention of Water Loss (Cuticle):</strong> Epidermal cells of aerial parts secrete a waxy, water-resistant lipid coating called <strong>cutin</strong> on their outer walls, preventing excessive evaporative water loss.</li>\r\n    <li><strong>Gas Exchange & Transpiration:</strong> Epidermis houses <strong>stomata</strong> with guard cells, which regulate the intake of CO₂ for photosynthesis and release water vapour via transpiration.</li>\r\n    <li><strong>Water and Mineral Absorption (Root Hairs):</strong> Root epidermal cells have unicellular extensions called <strong>root hairs</strong> that increase surface area for efficient absorption of soil moisture.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Protection against mechanical injury and pathogen invasion</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cuticle secretion preventing water loss</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of stomata in gas exchange and root hairs in water absorption</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_14')\">\r\n      <div class=\"q-num\">Exercise — Q14</div>\r\n      <div class=\"q-text\">How does the cork act as a protective tissue?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Protective Mechanisms of Cork (Phellem):</strong><br>\r\n  As a woody tree grows older, a secondary lateral meristem (cork cambium or phellogen) develops in the outer cortex, forming multiple compact layers of dead cork cells.<br>\r\n  <ol>\r\n    <li><strong>Suberin Deposition:</strong> The walls of cork cells are heavily deposited with an organic waxy substance called <strong>suberin</strong>, which makes them completely <strong>impermeable to water and gases</strong>.</li>\r\n    <li><strong>Mechanical Protection:</strong> Cork cells are dead, tightly packed without intercellular spaces, acting as an insulating shock-absorbent shield protecting inner vascular bundles against mechanical blows, fire, and extreme temperature fluctuations.</li>\r\n    <li><strong>Defense Against Pathogens:</strong> Due to lack of living protoplasm and suberized impermeable walls, bacteria, fungi, and insect pests cannot penetrate into the plant body.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Suberin deposition making cells impermeable to water and gases</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Dead, compact cells acting as thermal and mechanical shock shield</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Barrier preventing entry of parasitic microbes and fungi</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q6_ex_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_ex_15')\">\r\n      <div class=\"q-num\">Exercise — Q15</div>\r\n      <div class=\"q-text\">Complete the following chart:<br>Permanent Tissues ⟶ Simple and Complex;<br>Simple ⟶ Parenchyma, Collenchyma, Sclerenchyma;<br>Complex ⟶ Xylem and Phloem.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Completed Hierarchy Chart of Plant Permanent Tissues:</strong><br>\r\n  <pre style=\"background:rgba(0,0,0,0.2); padding:12px; border-radius:6px; font-family:monospace; font-size:13px; line-height:1.6;\">\r\n                          PERMANENT TISSUES\r\n                                  │\r\n          ┌───────────────────────┴───────────────────────┐\r\n          ▼                                               ▼\r\n   SIMPLE TISSUES                                 COMPLEX TISSUES\r\n          │                                               │\r\n   ┌──────┼──────────────┐                         ┌──────┴──────┐\r\n   ▼      ▼              ▼                         ▼             ▼\r\nParenchyma Collenchyma Sclerenchyma             Xylem         Phloem\r\n  </pre>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate division into Simple and Complex tissues</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate subdivision into Parenchyma, Collenchyma, Sclerenchyma and Xylem, Phloem</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 6</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Girdling Experiment and Vascular Transport:</strong> A biologist removes a complete ring of bark (including phloem tissue) from the trunk of a woody tree while keeping the central xylem cylinder intact.<br>(a) What will happen to the leaves and roots initially?<br>(b) Which organ will starve and die first: roots or leaves? Explain why.<br>(c) What does this experiment prove regarding the specific functions of xylem and phloem?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> Initially, the leaves will remain green and healthy because the intact xylem continues to supply water and minerals upward from the roots. However, roots cannot receive organic food synthesised by leaves.<br><strong>(b)</strong> The <strong>roots will die first</strong> because translocation of sucrose through downward phloem is blocked at the girdle; once root food reserves are exhausted, roots starve, stop active water uptake, and the whole tree wilts and dies.<br><strong>(c)</strong> This proves that <strong>phloem is responsible for bidirectional translocation of organic food</strong>, while <strong>xylem conducts water and mineral sap unidirectionally upward</strong>.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why do desert plants (xerophytes) have an extremely thick waxy cuticle, sunken stomata, and multiple epidermal layers?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">Desert plants face extreme water scarcity and high ambient temperatures. A thick waxy cuticle (cutin), multiple epidermal layers, and stomata sunken deep in epidermal crypts (often surrounded by epidermal hairs) minimize the water vapour pressure gradient and reduce transpirational water loss to near zero, preventing dehydration and thermal death.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(5)\">← Chapter 5</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\">Chapter 7 →</button>\r\n  </div>\r\n</section>","7":"<section class=\"chapter-section\" id=\"ch7\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">7</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 7: Motion</h2>\r\n      <p>Distance, Displacement, Speed, Velocity, Acceleration, Equations of Motion & Uniform Circular Motion — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 100)</div>\r\n\r\n  <div class=\"q-card\" id=\"q7_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_1')\">\r\n      <div class=\"q-num\">Page 100 — Q1</div>\r\n      <div class=\"q-text\">An object has moved through a distance. Can it have zero displacement? If yes, support your answer with an example.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: Yes, an object that has moved through a finite distance can have zero net displacement.</strong><br><br>\r\n  <strong>Explanation:</strong><br>\r\n  • <em>Distance</em> is the total actual path length traversed by an object, which is a scalar quantity and always positive for any moving body.<br>\r\n  • <em>Displacement</em> is the shortest straight-line vector distance between the initial position and final position of the object.<br>\r\n  • If a moving object returns to its starting point, its initial position and final position coincide. Hence, its net displacement is zero.<br><br>\r\n  <strong>Example:</strong> An athlete runs around a circular athletic track of radius <span class=\"math\">r</span> and completes one full round. The distance covered is <span class=\"math\">2πr</span>, but the displacement is <strong>0</strong> because the runner finishes exactly where they started.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative answer (Yes) with definition of displacement</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Valid practical example (e.g., circular track or round trip)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_2')\">\r\n      <div class=\"q-num\">Page 100 — Q2</div>\r\n      <div class=\"q-text\">A farmer moves along the boundary of a square field of side 10 m in 40 s. What will be the magnitude of displacement of the farmer at the end of 2 minutes 20 seconds from his initial position?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given Data:</strong><br>\r\n  • Side of square field (<span class=\"math\">s</span>) = <span class=\"math\">10 m</span><br>\r\n  • Perimeter of field = <span class=\"math\">4 × 10 = 40 m</span><br>\r\n  • Time to complete 1 round = <span class=\"math\">40 s</span><br>\r\n  • Total time of motion = <span class=\"math\">2 min 20 s = 2 × 60 + 20 = 140 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Number of Rounds Completed:</strong><br>\r\n  <span class=\"math\">Number of rounds = Total time / Time for 1 round = 140 / 40 = 3.5 rounds</span>.<br>\r\n  After 3 complete rounds, the farmer is back at the initial corner (say point A).<br>\r\n  In the remaining 0.5 round (half round = 20 s), the farmer covers two sides (from A to B to C) and ends up at the diagonally opposite corner C.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Magnitude of Displacement:</strong><br>\r\n  The displacement is the straight line diagonal AC of the square ABCD:<br>\r\n  By Pythagoras Theorem in right triangle ABC:<br>\r\n  <span class=\"math\">AC = √(AB² + BC²) = √(10² + 10²) = √(100 + 100) = √200 = 10√2 m</span>.<br>\r\n  Taking <span class=\"math\">√2 ≈ 1.414</span>:<br>\r\n  <span class=\"math\">Displacement = 10 × 1.414 = 14.14 m</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The magnitude of displacement of the farmer is <strong>10√2 m (or 14.14 m)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting time to 140 s and finding 3.5 rounds</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying final position at diagonally opposite corner</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Using Pythagoras theorem to find displacement = 10√2 m ≈ 14.14 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_3')\">\r\n      <div class=\"q-num\">Page 100 — Q3</div>\r\n      <div class=\"q-text\">Which of the following is true for displacement?<br>(a) It cannot be zero.<br>(b) Its magnitude is greater than the distance travelled by the object.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Evaluation:</strong><br>\r\n  • <strong>(a) \"It cannot be zero\":</strong> <strong>FALSE.</strong> Displacement becomes zero whenever the object returns to its original starting position (or does not move).<br><br>\r\n  • <strong>(b) \"Its magnitude is greater than the distance travelled\":</strong> <strong>FALSE.</strong> Displacement is the shortest straight-line distance between two points. Therefore, the magnitude of displacement is always <strong>less than or equal to</strong> the distance travelled (<span class=\"math\">|Displacement| ≤ Distance</span>). It can never be strictly greater than distance.\r\n</div>\r\n<p><strong>Conclusion:</strong> <strong>Neither (a) nor (b) is true. Both statements are false.</strong></p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Statement (a) is False with reason (displacement can be zero)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Statement (b) is False with reason (|displacement| ≤ distance)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 102)</div>\r\n\r\n  <div class=\"q-card\" id=\"q7_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_4')\">\r\n      <div class=\"q-num\">Page 102 — Q1</div>\r\n      <div class=\"q-text\">Distinguish between speed and velocity.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison: Speed vs Velocity:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Speed</th><th>Velocity</th></tr>\r\n    <tr><td><strong>Definition</strong></td><td>Distance travelled per unit time (<span class=\"math\">s = d/t</span>).</td><td>Displacement per unit time in a specified direction (<span class=\"math\">v = Δx/t</span>).</td></tr>\r\n    <tr><td><strong>Quantity Type</strong></td><td><strong>Scalar quantity</strong> (has magnitude only).</td><td><strong>Vector quantity</strong> (has both magnitude and direction).</td></tr>\r\n    <tr><td><strong>Sign / Value</strong></td><td>Always positive or zero (can never be negative).</td><td>Can be positive, negative, or zero depending on direction of displacement.</td></tr>\r\n    <tr><td><strong>Average Value</strong></td><td>Average speed of a moving body is always non-zero.</td><td>Average velocity can be zero if the net displacement is zero.</td></tr>\r\n    <tr><td><strong>SI Unit</strong></td><td>Metre per second (<span class=\"math\">m s⁻¹</span>).</td><td>Metre per second (<span class=\"math\">m s⁻¹</span>).</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and formula comparison</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Scalar vs Vector nature</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Signs/zero possibility and SI units</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_5')\">\r\n      <div class=\"q-num\">Page 102 — Q2</div>\r\n      <div class=\"q-text\">Under what condition(s) is the magnitude of average velocity of an object equal to its average speed?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Condition:</strong><br>\r\n  The magnitude of average velocity is strictly equal to average speed when the object moves along a <strong>straight line in a single, unchanging direction without reversing its path</strong>.<br>\r\n  Under this condition, <span class=\"math\">Total Distance = Magnitude of Total Displacement</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Motion along a straight line in a fixed direction without reversing</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_6')\">\r\n      <div class=\"q-num\">Page 102 — Q3</div>\r\n      <div class=\"q-text\">What does the odometer of an automobile measure?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The <strong>odometer</strong> of an automobile measures the <strong>total actual distance travelled</strong> by the vehicle in kilometres (<span class=\"math\">km</span>). (In contrast, the speedometer measures instantaneous speed).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Measures total distance travelled by the vehicle</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_7')\">\r\n      <div class=\"q-num\">Page 102 — Q4</div>\r\n      <div class=\"q-text\">What does the path of an object look like when it is in uniform motion?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The path of an object in uniform motion is a <strong>straight line</strong> (rectilinear path), because uniform motion requires constant speed along an invariant, unchanging direction (zero acceleration).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">A straight line path</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_8')\">\r\n      <div class=\"q-num\">Page 102 — Q5</div>\r\n      <div class=\"q-text\">During an experiment, a signal from a spaceship reached the ground station in five minutes. What was the distance of the spaceship from the ground station? The signal travels at the speed of light, that is, 3 × 10⁸ m s⁻¹.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given Data:</strong><br>\r\n  • Time taken (<span class=\"math\">t</span>) = <span class=\"math\">5 minutes = 5 × 60 = 300 s</span><br>\r\n  • Speed of signal (<span class=\"math\">v</span>) = <span class=\"math\">3 × 10⁸ m s⁻¹</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Formula & Calculation:</strong><br>\r\n  <span class=\"math\">Distance = Speed × Time</span><br>\r\n  <span class=\"math\">Distance = (3 × 10⁸ m s⁻¹) × 300 s = 900 × 10⁸ m = 9 × 10¹⁰ m</span><br>\r\n  In kilometres: <span class=\"math\">9 × 10¹⁰ / 1000 = 9 × 10⁷ km</span> (90 million km).\r\n</div>\r\n<p><strong>Final Answer:</strong> The distance of the spaceship is <strong>9 × 10¹⁰ m (or 9 × 10⁷ km)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting 5 minutes to 300 seconds</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying Distance = Speed × Time</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 9 × 10¹⁰ m with correct units</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 103)</div>\r\n\r\n  <div class=\"q-card\" id=\"q7_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_9')\">\r\n      <div class=\"q-num\">Page 103 — Q1</div>\r\n      <div class=\"q-text\">When will you say a body is in (i) uniform acceleration? (ii) non-uniform acceleration?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(i) Uniform Acceleration:</strong><br>\r\n  A body is said to have uniform acceleration if it travels in a straight line and its velocity increases (or decreases) by <strong>equal amounts in equal intervals of time</strong>, no matter how small these time intervals may be.<br>\r\n  <em>Example:</em> A body falling freely under gravity in a vacuum (<span class=\"math\">g ≈ 9.8 m s⁻²</span>).<br><br>\r\n  <strong>(ii) Non-Uniform Acceleration:</strong><br>\r\n  A body has non-uniform acceleration if its velocity changes by <strong>unequal amounts in equal intervals of time</strong> (or by equal amounts in unequal intervals).<br>\r\n  <em>Example:</em> A car driving through a crowded city street with fluctuating traffic.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Uniform acceleration defined with equal velocity changes in equal time</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Non-uniform acceleration defined with unequal changes</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_10')\">\r\n      <div class=\"q-num\">Page 103 — Q2</div>\r\n      <div class=\"q-text\">A bus decreases its speed from 80 km h⁻¹ to 60 km h⁻¹ in 5 s. Find the acceleration of the bus.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Step 1: Convert Speeds into SI Units (m s⁻¹):</strong><br>\r\n  • Initial velocity (<span class=\"math\">u</span>) = <span class=\"math\">80 × (5/18) = 400 / 18 = 22.22 m s⁻¹</span><br>\r\n  • Final velocity (<span class=\"math\">v</span>) = <span class=\"math\">60 × (5/18) = 300 / 18 = 16.67 m s⁻¹</span><br>\r\n  • Time interval (<span class=\"math\">t</span>) = <span class=\"math\">5 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Calculate Acceleration:</strong><br>\r\n  <span class=\"math\">a = (v - u) / t = (16.67 - 22.22) / 5 = -5.55 / 5 = -1.11 m s⁻²</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The acceleration is <strong>-1.11 m s⁻²</strong> (or a retardation of <strong>1.11 m s⁻²</strong>).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion of km/h to m/s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying formula a = (v - u) / t</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final calculated value = -1.11 m s⁻²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_11')\">\r\n      <div class=\"q-num\">Page 103 — Q3</div>\r\n      <div class=\"q-text\">A train starting from a railway station and moving with uniform acceleration attains a speed 40 km h⁻¹ in 10 minutes. Find its acceleration.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given Data:</strong><br>\r\n  • Starts from rest ⟹ Initial velocity (<span class=\"math\">u</span>) = <span class=\"math\">0 m s⁻¹</span><br>\r\n  • Final velocity (<span class=\"math\">v</span>) = <span class=\"math\">40 km h⁻¹ = 40 × (5/18) = 200 / 18 = 11.11 m s⁻¹</span><br>\r\n  • Time taken (<span class=\"math\">t</span>) = <span class=\"math\">10 minutes = 10 × 60 = 600 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">a = (v - u) / t = (11.11 - 0) / 600 = 11.11 / 600 ≈ 0.0185 m s⁻²</span><br>\r\n  (or in fraction: <span class=\"math\">(100/9) / 600 = 1/54 m s⁻²</span>).\r\n</div>\r\n<p><strong>Final Answer:</strong> The acceleration of the train is <strong>0.0185 m s⁻² (or 1/54 m s⁻²)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion u=0, v=11.11 m/s, t=600 s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation a = 0.0185 m s⁻²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 107)</div>\r\n\r\n  <div class=\"q-card\" id=\"q7_in_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_12')\">\r\n      <div class=\"q-num\">Page 107 — Q1</div>\r\n      <div class=\"q-text\">What is the nature of the distance-time graphs for uniform and non-uniform motion of an object?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Nature of Distance-Time Graphs:</strong><br>\r\n  • <strong>For Uniform Motion:</strong> The distance-time graph is a <strong>straight line with a constant non-zero slope</strong> passing through the origin. The slope of the line represents constant speed.<br><br>\r\n  • <strong>For Non-Uniform Motion:</strong> The distance-time graph is a <strong>curved line</strong> (non-linear graph), indicating that the rate of change of distance varies with time (accelerated or decelerated motion).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Uniform motion: Straight line with constant slope</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Non-uniform motion: Curved / non-linear line</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_13')\">\r\n      <div class=\"q-num\">Page 107 — Q2</div>\r\n      <div class=\"q-text\">What can you say about the motion of an object whose distance-time graph is a straight line parallel to the time axis?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The object is <strong>at rest (stationary)</strong>. As time progresses, the distance from the reference origin does not change (<span class=\"math\">Speed = Slope = 0</span>).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">The object is stationary / at rest (speed = 0)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_14')\">\r\n      <div class=\"q-num\">Page 107 — Q3</div>\r\n      <div class=\"q-text\">What can you say about the motion of an object if its speed-time graph is a straight line parallel to the time axis?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The object is moving with <strong>uniform speed (constant velocity)</strong>. Its speed remains constant at all instants of time, which means its acceleration is zero (<span class=\"math\">a = 0</span>).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Object is moving with constant speed / zero acceleration</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_15')\">\r\n      <div class=\"q-num\">Page 107 — Q4</div>\r\n      <div class=\"q-text\">What is the quantity which is measured by the area occupied below the velocity-time graph?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The area enclosed beneath the velocity-time (<span class=\"math\">v-t</span>) graph and the time axis represents the <strong>magnitude of displacement (or distance travelled)</strong> by the moving object during that time interval.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Magnitude of displacement / distance travelled</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 109)</div>\r\n\r\n  <div class=\"q-card\" id=\"q7_in_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_16')\">\r\n      <div class=\"q-num\">Page 109 — Q1</div>\r\n      <div class=\"q-text\">A bus starting from rest moves with a uniform acceleration of 0.1 m s⁻² for 2 minutes. Find (a) the speed acquired, (b) the distance travelled.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given Data:</strong><br>\r\n  • Starts from rest ⟹ <span class=\"math\">u = 0 m s⁻¹</span><br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">0.1 m s⁻²</span><br>\r\n  • Time (<span class=\"math\">t</span>) = <span class=\"math\">2 minutes = 2 × 60 = 120 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(a) Speed Acquired (<span class=\"math\">v</span>):</strong><br>\r\n  <span class=\"math\">v = u + at = 0 + (0.1 × 120) = 12 m s⁻¹</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Distance Travelled (<span class=\"math\">s</span>):</strong><br>\r\n  <span class=\"math\">s = ut + ½ at² = (0 × 120) + ½ × 0.1 × (120)² = 0.05 × 14400 = 720 m</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> (a) Speed = <strong>12 m s⁻¹</strong>, (b) Distance = <strong>720 m</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula v = u + at ⟹ v = 12 m/s</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula s = ut + ½at² ⟹ s = 720 m</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_17\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_17')\">\r\n      <div class=\"q-num\">Page 109 — Q2</div>\r\n      <div class=\"q-text\">A train is travelling at a speed of 90 km h⁻¹. Brakes are applied so as to produce a uniform acceleration of -0.5 m s⁻². Find how far the train will go before it is brought to rest.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Initial velocity (<span class=\"math\">u</span>) = <span class=\"math\">90 km h⁻¹ = 90 × (5/18) = 25 m s⁻¹</span><br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">-0.5 m s⁻²</span><br>\r\n  • Final velocity (<span class=\"math\">v</span>) = <span class=\"math\">0 m s⁻¹</span> (comes to rest)\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Using Third Equation of Motion:</strong><br>\r\n  <span class=\"math\">v² = u² + 2as</span><br>\r\n  <span class=\"math\">0² = (25)² + 2(-0.5)s</span><br>\r\n  <span class=\"math\">0 = 625 - 1.0 s ⟹ s = 625 m</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The train will travel a distance of <strong>625 metres</strong> before coming to a complete stop.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting u = 90 km/h = 25 m/s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying v² = u² + 2as with v=0 and a=-0.5</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving s = 625 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_18\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_18')\">\r\n      <div class=\"q-num\">Page 109 — Q3</div>\r\n      <div class=\"q-text\">A trolley, while going down an inclined plane, has an acceleration of 2 cm s⁻². What will be its velocity 3 s after the start?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Starts from rest ⟹ <span class=\"math\">u = 0</span><br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">2 cm s⁻² = 0.02 m s⁻²</span><br>\r\n  • Time (<span class=\"math\">t</span>) = <span class=\"math\">3 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Formula & Calculation:</strong><br>\r\n  <span class=\"math\">v = u + at = 0 + (2 cm s⁻² × 3 s) = 6 cm s⁻¹ = 0.06 m s⁻¹</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Its velocity after 3 seconds is <strong>6 cm s⁻¹ (or 0.06 m s⁻¹)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula v = u + at with u=0</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 6 cm s⁻¹ (0.06 m s⁻¹)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_19\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_19')\">\r\n      <div class=\"q-num\">Page 109 — Q4</div>\r\n      <div class=\"q-text\">A racing car has a uniform acceleration of 4 m s⁻². What distance will it cover in 10 s after start?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Starts from rest ⟹ <span class=\"math\">u = 0 m s⁻¹</span><br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">4 m s⁻²</span><br>\r\n  • Time (<span class=\"math\">t</span>) = <span class=\"math\">10 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Using Second Equation of Motion:</strong><br>\r\n  <span class=\"math\">s = ut + ½ at² = 0 + ½ × 4 × (10)² = 2 × 100 = 200 m</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The racing car will cover a distance of <strong>200 metres</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying s = ut + ½at²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 200 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_in_20\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_in_20')\">\r\n      <div class=\"q-num\">Page 109 — Q5</div>\r\n      <div class=\"q-text\">A stone is thrown in a vertically upward direction with a velocity of 5 m s⁻¹. If the acceleration of the stone during its motion is 10 m s⁻² in the downward direction, what will be the height attained by the stone and how much time will it take to reach there?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Initial velocity (<span class=\"math\">u</span>) = <span class=\"math\">+5 m s⁻¹</span> (upward)<br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">-10 m s⁻²</span> (downward retardation)<br>\r\n  • At highest point, final velocity (<span class=\"math\">v</span>) = <span class=\"math\">0 m s⁻¹</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Maximum Height (<span class=\"math\">h</span>):</strong><br>\r\n  <span class=\"math\">v² = u² + 2as</span><br>\r\n  <span class=\"math\">0 = (5)² + 2(-10)h ⟹ 20h = 25 ⟹ h = 25 / 20 = 1.25 m</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Calculate Time Taken (<span class=\"math\">t</span>):</strong><br>\r\n  <span class=\"math\">v = u + at</span><br>\r\n  <span class=\"math\">0 = 5 + (-10)t ⟹ 10t = 5 ⟹ t = 5 / 10 = 0.5 s</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Maximum height = <strong>1.25 m</strong>, Time taken = <strong>0.5 s</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating height h = 1.25 m using v² = u² + 2as</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating time t = 0.5 s using v = u + at</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q7_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">An athlete completes one round of a circular track of diameter 200 m in 40 s. What will be the distance covered and the displacement at the end of 2 minutes 20 s?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Diameter (<span class=\"math\">D</span>) = <span class=\"math\">200 m</span> ⟹ Radius (<span class=\"math\">r</span>) = <span class=\"math\">100 m</span><br>\r\n  • Time for 1 round = <span class=\"math\">40 s</span><br>\r\n  • Total time = <span class=\"math\">2 min 20 s = 140 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Number of Rounds:</strong><br>\r\n  <span class=\"math\">Rounds = 140 / 40 = 3.5 rounds</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Total Distance Covered:</strong><br>\r\n  <span class=\"math\">Distance = 3.5 × Circumference = 3.5 × (2πr) = 3.5 × 2 × (22/7) × 100</span><br>\r\n  <span class=\"math\">Distance = 7 × (22/7) × 100 = 22 × 100 = 2200 m</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 3: Magnitude of Displacement:</strong><br>\r\n  After 3.5 rounds, the athlete is at the point exactly opposite to the starting point across the circle.<br>\r\n  <span class=\"math\">Displacement = Diameter of circular track = 200 m</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Distance = <strong>2200 m</strong>, Displacement = <strong>200 m</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Finding 3.5 rounds from 140 s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Distance = 3.5 × 2πr = 2200 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Displacement = Diameter = 200 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">Joseph jogs from one end A to the other end B of a straight 300 m road in 2 min 30 s and then turns around and jogs 100 m back to point C in another 1 min. What are Joseph’s average speeds and velocities in jogging (a) from A to B and (b) from A to C?</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) From A to B:</strong><br>\r\n  • Distance = <span class=\"math\">300 m</span>; Displacement = <span class=\"math\">300 m</span> (straight line).<br>\r\n  • Time = <span class=\"math\">2 min 30 s = 150 s</span>.<br>\r\n  <span class=\"math\">Average Speed = 300 / 150 = 2.0 m s⁻¹</span>.<br>\r\n  <span class=\"math\">Average Velocity = 300 / 150 = 2.0 m s⁻¹</span> (in direction A to B).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) From A to C (via B):</strong><br>\r\n  • Total distance = <span class=\"math\">AB + BC = 300 + 100 = 400 m</span>.<br>\r\n  • Total time = <span class=\"math\">150 s + 60 s = 210 s</span>.<br>\r\n  <span class=\"math\">Average Speed = Total Distance / Total Time = 400 / 210 ≈ 1.90 m s⁻¹</span>.<br><br>\r\n  • Net Displacement = <span class=\"math\">AB - BC = 300 - 100 = 200 m</span> (from A to C).<br>\r\n  <span class=\"math\">Average Velocity = Net Displacement / Total Time = 200 / 210 ≈ 0.95 m s⁻¹</span> (in direction A to C).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Average speed and velocity = 2.0 m/s</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Average speed = 400/210 = 1.90 m/s</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Average velocity = 200/210 = 0.95 m/s</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">Abdul, while driving to school, computes the average speed for his trip to be 20 km h⁻¹. On his return trip along the same route, there is less traffic and the average speed is 30 km h⁻¹. What is the average speed for Abdul’s trip?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Let the one-way distance to school be <span class=\"math\">d</span> km.</strong><br>\r\n  • Time for forward trip (<span class=\"math\">t₁</span>) = <span class=\"math\">d / 20</span> hours.<br>\r\n  • Time for return trip (<span class=\"math\">t₂</span>) = <span class=\"math\">d / 30</span> hours.<br>\r\n  • Total distance = <span class=\"math\">d + d = 2d</span> km.<br>\r\n  • Total time (<span class=\"math\">T</span>) = <span class=\"math\">t₁ + t₂ = d/20 + d/30 = (3d + 2d)/60 = 5d/60 = d/12</span> hours.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Average Speed:</strong><br>\r\n  <span class=\"math\">Average Speed = Total Distance / Total Time = (2d) / (d / 12) = 2 × 12 = 24 km h⁻¹</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The average speed for Abdul's entire round trip is <strong>24 km h⁻¹</strong> (Harmonic mean of speeds).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Expressing t₁ = d/20 and t₂ = d/30</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total time = 5d/60 = d/12</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Average speed = 2d / (d/12) = 24 km/h</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">A motorboat starting from rest on a lake accelerates in a straight line at a constant rate of 3.0 m s⁻² for 8.0 s. How far does the boat travel during this time?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Initial velocity (<span class=\"math\">u</span>) = <span class=\"math\">0 m s⁻¹</span><br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">3.0 m s⁻²</span><br>\r\n  • Time (<span class=\"math\">t</span>) = <span class=\"math\">8.0 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Second Equation of Motion:</strong><br>\r\n  <span class=\"math\">s = ut + ½ at² = 0 + ½ × 3.0 × (8.0)² = 1.5 × 64 = 96 m</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The motorboat travels a distance of <strong>96 metres</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Using s = ut + ½at²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 96 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">A driver of a car travelling at 52 km h⁻¹ applies the brakes and accelerates uniformly in the opposite direction. The car stops in 5 s. Another driver going at 3 km h⁻¹ in another car applies his brakes slowly and stops in 10 s. On the same graph paper, plot the speed versus time graphs for the two cars. Which of the two cars travelled farther after the brakes were applied?</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Car 1:</strong><br>\r\n  • <span class=\"math\">u₁ = 52 km h⁻¹ = 52 × (5/18) = 14.44 m s⁻¹</span>; Stops in <span class=\"math\">t₁ = 5 s</span> (<span class=\"math\">v₁ = 0</span>).<br>\r\n  • In the speed-time graph, it forms a right triangle with base = 5 s and height = 14.44 m s⁻¹.<br>\r\n  <span class=\"math\">Distance₁ = Area = ½ × base × height = ½ × 5 × 14.44 = 36.1 m</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Car 2:</strong><br>\r\n  • <span class=\"math\">u₂ = 3 km h⁻¹ = 3 × (5/18) = 15/18 = 0.833 m s⁻¹</span>; Stops in <span class=\"math\">t₂ = 10 s</span> (<span class=\"math\">v₂ = 0</span>).<br>\r\n  • In the graph, it forms a right triangle with base = 10 s and height = 0.833 m s⁻¹.<br>\r\n  <span class=\"math\">Distance₂ = Area = ½ × base × height = ½ × 10 × 0.833 = 4.17 m</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Comparison:</strong><br>\r\n  Since <span class=\"math\">36.1 m &gt; 4.17 m</span>, the <strong>first car travelled much farther (36.1 m)</strong> after the brakes were applied.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion of u₁ and u₂ to m/s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating Distance₁ = 36.1 m from area of triangle</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating Distance₂ = 4.17 m and concluding Car 1 travelled farther</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">Figure shows the distance-time graph of three objects A, B and C. Study the graph and answer the following questions:<br>(a) Which of the three is travelling fastest?<br>(b) Are all three ever at the same point on the road?<br>(c) How far has C travelled when B passes A?<br>(d) How far has B travelled by the time it passes C?</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis from Slope & Intersections of Distance-Time Graph:</strong><br>\r\n  • <strong>(a) Fastest Object:</strong> The speed is directly given by the <strong>slope</strong> of the distance-time graph (<span class=\"math\">Speed = Δs / Δt</span>). Object B has the steepest slope (largest angle with the time axis). Hence, <strong>Object B is travelling the fastest</strong>.<br><br>\r\n  • <strong>(b) Common Point:</strong> For all three to be at the same point on the road at the same time, all three lines must intersect at a single common intersection point. Since there is no point where all three lines intersect simultaneously, <strong>no, all three are never at the same point on the road</strong>.<br><br>\r\n  • <strong>(c) Distance C travelled when B passes A:</strong> B passes A at the intersection of line B and line A (at approx <span class=\"math\">t = 1.2 h</span>). Projecting this time vertically onto the graph of C gives distance of C from origin as approx <span class=\"math\">8 km</span>. Since C started at 2 km, distance travelled by C = <span class=\"math\">8 - 2 = 6 km</span> (approx 6 to 6.5 km).<br><br>\r\n  • <strong>(d) Distance B travelled when it passes C:</strong> B passes C at the intersection of line B and line C (at approx distance of 5.14 km on the y-axis). Since B started from the origin (0 km), <strong>B has travelled approx 5.14 km</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Object B is fastest due to steepest slope</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) No, lines do not intersect at any single point</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Distance C travelled ≈ 6 km</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Distance B travelled ≈ 5.14 km</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">A ball is gently dropped from a height of 20 m. If its velocity increases uniformly at the rate of 10 m s⁻², with what velocity will it strike the ground? After what time will it strike the ground?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Dropped gently ⟹ <span class=\"math\">u = 0 m s⁻¹</span><br>\r\n  • Height (<span class=\"math\">s</span>) = <span class=\"math\">20 m</span><br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">+10 m s⁻²</span> (downward)\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Striking Velocity (<span class=\"math\">v</span>):</strong><br>\r\n  <span class=\"math\">v² = u² + 2as = 0² + 2(10)(20) = 400</span><br>\r\n  <span class=\"math\">v = √400 = 20 m s⁻¹</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Time Taken (<span class=\"math\">t</span>):</strong><br>\r\n  <span class=\"math\">v = u + at ⟹ 20 = 0 + 10t ⟹ t = 20 / 10 = 2 s</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Striking velocity = <strong>20 m s⁻¹</strong>, Time taken = <strong>2 seconds</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula v² = u² + 2as ⟹ v = 20 m/s</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula v = u + at ⟹ t = 2 s</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">The speed-time graph for a car is shown in the figure (initial curved acceleration from 0 to 6 s, reaching 6 m/s, followed by flat plateau):<br>(a) Find how far does the car travel in the first 4 seconds? Shade the area on the graph that represents the distance travelled by the car during the period.<br>(b) Which part of the graph represents uniform motion of the car?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) Distance in the first 4 seconds:</strong><br>\r\n  • From <span class=\"math\">t = 0</span> to <span class=\"math\">t = 4 s</span>, the car accelerates from 0 to approx <span class=\"math\">6 m s⁻¹</span>.<br>\r\n  • Approximating the area under this curve as a triangle:<br>\r\n  <span class=\"math\">Distance = Area ≈ ½ × base × height = ½ × 4 s × 6 m s⁻¹ = 12 m</span> (or counting grid squares gives approx 16.5 m). Shading the area under the curve between <span class=\"math\">t = 0</span> and <span class=\"math\">t = 4 s</span> represents this distance.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Uniform Motion:</strong><br>\r\n  • After <span class=\"math\">t = 6 s</span>, the speed-time graph becomes a straight horizontal line parallel to the time axis at a constant speed of <span class=\"math\">6 m s⁻¹</span>.<br>\r\n  • Therefore, the section from <strong>t = 6 seconds onwards (to 10 s)</strong> represents <strong>uniform motion</strong> of the car.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Finding area under v-t graph from 0 to 4 s</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Horizontal line from t = 6 s onwards represents uniform motion</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">State which of the following situations are possible and give an example for each:<br>(a) An object with a constant acceleration but with zero velocity.<br>(b) An object moving with an acceleration but with uniform speed.<br>(c) An object moving in a certain direction with an acceleration in the perpendicular direction.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>(a) Constant acceleration with zero velocity:</strong><br>\r\n  • <strong>Possible.</strong><br>\r\n  • <em>Example:</em> When a ball is thrown vertically upward, at the highest point of its trajectory, its instantaneous velocity becomes momentarily <strong>zero (<span class=\"math\">v = 0</span>)</strong>, while it is still experiencing constant downward gravitational acceleration (<span class=\"math\">g = 9.8 m s⁻²</span>).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Moving with acceleration but with uniform speed:</strong><br>\r\n  • <strong>Possible.</strong><br>\r\n  • <em>Example:</em> An object moving in a <strong>uniform circular motion</strong> at a constant speed. Because the direction of motion continuously changes at every instant, velocity is constantly changing, generating a non-zero centripetal acceleration directed towards the centre.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(c) Moving in a certain direction with acceleration in perpendicular direction:</strong><br>\r\n  • <strong>Possible.</strong><br>\r\n  • <em>Example:</em> An aeroplane flying horizontally while gravity pulls it downward, or a body in circular motion where instantaneous velocity is tangential while centripetal acceleration is directed radially inward (perpendicular at 90°).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Possible with vertical projection highest point example</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Possible with uniform circular motion example</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Possible with circular motion / tangential velocity example</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q7_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">An artificial satellite is moving in a circular orbit of radius 42250 km. Calculate its speed if it takes 24 hours to revolve around the earth.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Orbital radius (<span class=\"math\">r</span>) = <span class=\"math\">42,250 km = 42,250 × 1000 m = 4.225 × 10⁷ m</span><br>\r\n  • Time period (<span class=\"math\">T</span>) = <span class=\"math\">24 hours = 24 × 3600 = 86,400 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Formula for Orbital Speed in Circular Motion:</strong><br>\r\n  <span class=\"math\">v = (2πr) / T</span><br>\r\n  In km s⁻¹:<br>\r\n  <span class=\"math\">v = (2 × 3.1416 × 42250) / 86400 = 265464.58 / 86400 ≈ 3.07 km s⁻¹</span><br><br>\r\n  In m s⁻¹:<br>\r\n  <span class=\"math\">v ≈ 3.07 × 1000 = 3072 m s⁻¹</span> (or approx 11,060 km h⁻¹).\r\n</div>\r\n<p><strong>Final Answer:</strong> The satellite's speed is <strong>3.07 km s⁻¹ (or 3072 m s⁻¹)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula v = 2πr / T</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution with T = 86400 s and r = 42250 km</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final calculation = 3.07 km/s (3072 m/s)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 7</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Braking Distance and Reaction Time:</strong> While driving at 72 km h⁻¹ on a highway, a driver spots a fallen tree ahead and applies emergency brakes with a reaction time of 0.5 s. The brakes produce a maximum deceleration of 5 m s⁻².<br>(a) What distance does the car cover during the driver's reaction time?<br>(b) What is the braking distance after the pedal is pressed?<br>(c) What is the total stopping distance?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> Speed = 72 × (5/18) = 20 m s⁻¹. Reaction distance = Speed × reaction time = 20 × 0.5 = <strong>10 m</strong>.<br><strong>(b)</strong> Using v² = u² + 2as: 0 = 20² + 2(-5)s ⟹ 10s = 400 ⟹ Braking distance = <strong>40 m</strong>.<br><strong>(c)</strong> Total stopping distance = Reaction distance + Braking distance = 10 + 40 = <strong>50 m</strong>.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why is uniform circular motion called an accelerated motion even if the speed of the object is strictly constant?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">Velocity is a vector quantity having both magnitude (speed) and direction. In circular motion, although speed is constant, the direction of motion is changing continuously at every point along the tangent. Any change in direction produces a change in velocity vector (<span class='math'>Δv ≠ 0</span>). Since acceleration is the time rate of change of velocity (<span class='math'>a = Δv/Δt</span>), a non-zero centripetal acceleration (<span class='math'>a_c = v²/r</span>) acts radially inward, making it an accelerated motion.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(6)\">← Chapter 6</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\">Chapter 8 →</button>\r\n  </div>\r\n</section>","8":"<section class=\"chapter-section\" id=\"ch8\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">8</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 8: Force and Laws of Motion</h2>\r\n      <p>Balanced & Unbalanced Forces, Newton's Three Laws of Motion, Momentum & Conservation of Momentum — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 118)</div>\r\n\r\n  <div class=\"q-card\" id=\"q8_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_in_1')\">\r\n      <div class=\"q-num\">Page 118 — Q1</div>\r\n      <div class=\"q-text\">Which of the following has more inertia:<br>(a) a rubber ball and a stone of the same size?<br>(b) a bicycle and a train?<br>(c) a five-rupees coin and a one-rupee coin?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Principle:</strong><br>\r\n  <em>Inertia</em> is the inherent natural property of an object to resist any change in its state of rest or uniform motion. The inertia of an object is <strong>directly proportional to its mass</strong> (<span class=\"math\">Inertia ∝ Mass</span>). A heavier mass possesses greater inertia.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Answers:</strong>\r\n  <ul>\r\n    <li><strong>(a) A stone of the same size:</strong> A stone has much higher density and significantly greater mass than a rubber ball of identical volume. Hence, <strong>the stone has more inertia</strong>.</li>\r\n    <li><strong>(b) A train:</strong> A train has an enormously larger mass than a bicycle. Hence, <strong>the train has far more inertia</strong>.</li>\r\n    <li><strong>(c) A five-rupees coin:</strong> A five-rupee coin is thicker, heavier, and has greater mass than a one-rupee coin. Hence, <strong>the five-rupees coin has more inertia</strong>.</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">State that Inertia is directly proportional to mass</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Answers: Stone, Train, Five-rupee coin with justifications</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_in_2')\">\r\n      <div class=\"q-num\">Page 118 — Q2</div>\r\n      <div class=\"q-text\">In the following example, try to identify the number of times the velocity of the ball changes:<br>'A football player kicks a football to another player of his team who kicks the football towards the goal. The goalkeeper of the opposite team collects the football and kicks it towards a player of his own team.'<br>Also identify the agent supplying the force in each case.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis of Velocity Changes & Agents of Force:</strong>\r\n  <ol>\r\n    <li><strong>First Change:</strong> The first football player kicks the stationary ball to a teammate.<br>\r\n      • <em>Agent supplying force:</em> Muscular force of the <strong>first football player's foot</strong>.</li>\r\n    <li><strong>Second Change:</strong> The teammate kicks the moving ball towards the goal (changing both its direction and speed).<br>\r\n      • <em>Agent supplying force:</em> Muscular force of the <strong>teammate's foot</strong>.</li>\r\n    <li><strong>Third Change:</strong> The opposing goalkeeper collects (catches) the moving ball, bringing its velocity to zero (stopping it).<br>\r\n      • <em>Agent supplying force:</em> Muscular frictional force applied by the <strong>goalkeeper's hands</strong>.</li>\r\n    <li><strong>Fourth Change:</strong> The goalkeeper kicks the stopped football towards a player of his own team.<br>\r\n      • <em>Agent supplying force:</em> Muscular force of the <strong>goalkeeper's foot</strong>.</li>\r\n  </ol>\r\n</div>\r\n<p><strong>Conclusion:</strong> The velocity of the ball changes <strong>4 times</strong> in total.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying total number of velocity changes = 4</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying agents of force in all 4 instances</span><span class=\"marking-marks\">3 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_in_3')\">\r\n      <div class=\"q-num\">Page 118 — Q3</div>\r\n      <div class=\"q-text\">Explain why some of the leaves may get detached from a tree if we vigorously shake its branch.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Explanation based on Inertia of Rest:</strong><br>\r\n  1. Initially, both the tree branch and its leaves are at rest.<br>\r\n  2. When we vigorously shake the branch, the branch is suddenly brought into a state of rapid oscillating motion.<br>\r\n  3. However, due to <strong>inertia of rest</strong> (Newton's First Law of Motion), the leaves tend to maintain their original stationary position.<br>\r\n  4. This creates a severe mechanical shear stress at the junction (petiole) connecting the leaves to the branch.<br>\r\n  5. The fragile stalks break under this unbalanced inertial stress, causing the leaves to detach and fall under gravity.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Concept of Inertia of Rest (Newton's First Law)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Branch moves while leaves tend to remain stationary breaking petiole stalk</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_in_4')\">\r\n      <div class=\"q-num\">Page 118 — Q4</div>\r\n      <div class=\"q-text\">Why do you fall in the forward direction when a moving bus brakes to a stop and fall backwards when it accelerates from rest?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>1. Falling Forward when Bus Brakes to a Stop (Inertia of Motion):</strong><br>\r\n  • While the bus is moving, our entire body shares the forward velocity of the bus.<br>\r\n  • When brakes are suddenly applied, the lower part of our body in direct contact with the bus floor comes to rest immediately due to friction.<br>\r\n  • However, the upper part of our body tends to continue moving forward due to <strong>inertia of motion</strong>, causing us to lurch forward.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>2. Falling Backward when Bus Accelerates from Rest (Inertia of Rest):</strong><br>\r\n  • When the bus is at rest, our entire body is stationary.<br>\r\n  • When the bus suddenly accelerates forward, our feet move forward with the floor.<br>\r\n  • But the upper body tends to remain at rest due to <strong>inertia of rest</strong>. The bus floor moves forward underneath us, making us fall backward.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Forward fall explained via Inertia of Motion</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Backward fall explained via Inertia of Rest</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 126)</div>\r\n\r\n  <div class=\"q-card\" id=\"q8_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_in_5')\">\r\n      <div class=\"q-num\">Page 126 — Q1</div>\r\n      <div class=\"q-text\">If action is always equal to the reaction, explain how a horse can pull a cart.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Resolution of Action and Reaction on Different Bodies:</strong><br>\r\n  1. According to Newton's Third Law, action and reaction are always equal and opposite, but they <strong>act on two completely different bodies</strong>, so they never cancel each other out.<br>\r\n  2. To pull the cart forward, the horse bends forward and pushes the ground backward with its hooves with a muscular force (<span class=\"math\">F_{push}</span>, Action).<br>\r\n  3. According to Newton's Third Law, the ground exerts an equal and opposite forward reaction force on the horse (<span class=\"math\">R_{ground}</span>, Reaction).<br>\r\n  4. The forward component of this reaction force exceeds the backward friction force between the cart wheels and the ground (<span class=\"math\">R_{forward} &gt; F_{friction}</span>).<br>\r\n  5. This net unbalanced forward force accelerates the horse and cart forward.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Action and reaction act on different bodies (horse and ground)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Horse pushes ground backward (action); ground pushes horse forward (reaction)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Net forward reaction force overcomes wheel friction to accelerate cart</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_in_6')\">\r\n      <div class=\"q-num\">Page 126 — Q2</div>\r\n      <div class=\"q-text\">Explain, why is it difficult for a fireman to hold a hose, which ejects large amounts of water at a high velocity.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Newton's Third Law & Momentum Conservation:</strong><br>\r\n  1. A firefighting hose ejects a massive stream of water (<span class=\"math\">dm/dt</span>) forward with tremendous velocity (<span class=\"math\">v</span>), carrying a very high forward momentum.<br>\r\n  2. According to <strong>Newton's Third Law of Motion</strong>, for this powerful forward action of water, an exactly equal and opposite backward <strong>reaction force</strong> is exerted onto the nozzle of the hose (<span class=\"math\">F_{reaction} = - v(dm/dt)</span>).<br>\r\n  3. This strong backward thrust pushes the hose vigorously backward, making it extremely difficult for a single firefighter to hold it steady without being thrown off balance.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Large forward momentum of high-velocity water jet (action)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Equal and opposite backward reaction force exerted on hose nozzle (reaction)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_in_7')\">\r\n      <div class=\"q-num\">Page 126 — Q3</div>\r\n      <div class=\"q-text\">From a rifle of mass 4 kg, a bullet of mass 50 g is fired with an initial velocity of 35 m s⁻¹. Calculate the initial recoil velocity of the rifle.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given Data:</strong><br>\r\n  • Mass of rifle (<span class=\"math\">m₁</span>) = <span class=\"math\">4 kg</span><br>\r\n  • Mass of bullet (<span class=\"math\">m₂</span>) = <span class=\"math\">50 g = 50 / 1000 = 0.05 kg</span><br>\r\n  • Initial velocity of rifle and bullet before firing: <span class=\"math\">u₁ = 0, u₂ = 0</span><br>\r\n  • Muzzle velocity of bullet (<span class=\"math\">v₂</span>) = <span class=\"math\">+35 m s⁻¹</span><br>\r\n  • Recoil velocity of rifle = <span class=\"math\">v₁</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Law of Conservation of Linear Momentum:</strong><br>\r\n  <span class=\"math\">Total Momentum before firing = Total Momentum after firing</span><br>\r\n  <span class=\"math\">0 = m₁v₁ + m₂v₂</span><br>\r\n  <span class=\"math\">4 × v₁ + 0.05 × 35 = 0</span><br>\r\n  <span class=\"math\">4 v₁ + 1.75 = 0 ⟹ 4 v₁ = -1.75</span><br>\r\n  <span class=\"math\">v₁ = -1.75 / 4 = -0.4375 m s⁻¹</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The recoil velocity of the rifle is <strong>-0.4375 m s⁻¹</strong> (the negative sign indicates the rifle recoils backward in the direction opposite to the bullet's flight).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting bullet mass 50 g = 0.05 kg</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Setting up momentum conservation 0 = m₁v₁ + m₂v₂</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving v₁ = -0.4375 m s⁻¹ with directional interpretation</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 127)</div>\r\n\r\n  <div class=\"q-card\" id=\"q8_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_in_8')\">\r\n      <div class=\"q-num\">Page 127 — Q1</div>\r\n      <div class=\"q-text\">Two objects of masses 100 g and 200 g are moving along the same line and direction with velocities of 2 m s⁻¹ and 1 m s⁻¹, respectively. They collide and after the collision, the first object moves at a velocity of 1.67 m s⁻¹. Determine the velocity of the second object.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • <span class=\"math\">m₁ = 100 g = 0.1 kg</span>, <span class=\"math\">u₁ = +2 m s⁻¹</span><br>\r\n  • <span class=\"math\">m₂ = 200 g = 0.2 kg</span>, <span class=\"math\">u₂ = +1 m s⁻¹</span><br>\r\n  • After collision: <span class=\"math\">v₁ = +1.67 m s⁻¹</span>, <span class=\"math\">v₂ = ?</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Conservation of Linear Momentum:</strong><br>\r\n  <span class=\"math\">m₁u₁ + m₂u₂ = m₁v₁ + m₂v₂</span><br>\r\n  <span class=\"math\">(0.1 × 2) + (0.2 × 1) = (0.1 × 1.67) + (0.2 × v₂)</span><br>\r\n  <span class=\"math\">0.2 + 0.2 = 0.167 + 0.2 v₂</span><br>\r\n  <span class=\"math\">0.4 = 0.167 + 0.2 v₂</span><br>\r\n  <span class=\"math\">0.2 v₂ = 0.4 - 0.167 = 0.233</span><br>\r\n  <span class=\"math\">v₂ = 0.233 / 0.2 = 1.165 m s⁻¹</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The velocity of the second object after collision is <strong>+1.165 m s⁻¹</strong> (moving forward in the same direction).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion of masses to kg (0.1 kg and 0.2 kg)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying conservation of linear momentum equation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating v₂ = 1.165 m s⁻¹</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q8_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">An object experiences a net zero external unbalanced force. Is it possible for the object to be travelling with a non-zero velocity? If yes, state the conditions that must be placed on the magnitude and direction of the velocity. If no, provide a reason.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: Yes, it is entirely possible.</strong><br><br>\r\n  <strong>Explanation & Conditions:</strong><br>\r\n  • According to <strong>Newton's First Law of Motion</strong>, a non-zero external unbalanced force is required only to <em>change</em> the state of motion (i.e. to produce acceleration), not to maintain motion.<br>\r\n  • If the net external unbalanced force is zero (<span class=\"math\">F_{net} = 0 ⟹ a = 0</span>), the object will continue to travel with a non-zero velocity provided:<br>\r\n    1. The <strong>magnitude of velocity (speed) must remain strictly constant</strong>.<br>\r\n    2. The <strong>direction of motion must remain strictly constant</strong> (along an invariant straight line).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative answer (Yes) based on Newton's First Law</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Conditions: Constant magnitude and invariant straight line direction</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">When a carpet is beaten with a stick, dust comes out of it. Explain.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Explanation based on Inertia of Rest:</strong><br>\r\n  1. Before beating, both the hanging carpet and the trapped dust particles inside its woven fibers are at rest.<br>\r\n  2. When the carpet is beaten with a stick, the strike exerts an external impulsive force that sets the carpet into rapid backward and forward motion.<br>\r\n  3. However, due to <strong>inertia of rest</strong>, the dust particles tend to maintain their original stationary position.<br>\r\n  4. As the carpet fibers move away, the dust particles are left behind suspended in air and subsequently fall downward under gravity.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Carpet is set into motion by the stick's force</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Dust particles remain stationary due to Inertia of Rest and fall out</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">Why is it advised to tie any luggage kept on the roof of a bus with a rope?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Reasons Based on Inertia:</strong><br>\r\n  Luggage placed on the roof of a bus is not rigidly attached to the vehicle. It is subject to sudden changes in motion:\r\n  <ol>\r\n    <li><strong>When bus starts suddenly:</strong> Due to <em>inertia of rest</em>, the luggage tends to remain stationary while the bus moves forward, causing luggage to slide off the rear.</li>\r\n    <li><strong>When bus brakes suddenly:</strong> Due to <em>inertia of motion</em>, the luggage continues its forward motion, potentially flying off the front.</li>\r\n    <li><strong>When bus takes a sharp turn:</strong> Due to <em>inertia of direction</em>, the luggage tends to move in a straight line, sliding sideways off the roof.</li>\r\n  </ol>\r\n  Tying it firmly with a rope provides the necessary restraining force against all these inertial forces.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Inertia of motion on braking and inertia of rest on starting</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Inertia of direction on sharp turns; rope prevents falling</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">A batsman hits a cricket ball which then rolls on a level ground. After covering a short distance, the ball comes to rest. The ball slows to a stop because:<br>(a) the batsman did not hit the ball hard enough.<br>(b) velocity is proportional to the force exerted on the ball.<br>(c) there is a force on the ball opposing the motion.<br>(d) there is no unbalanced force on the ball, so the ball would want to come to rest.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<p><strong>Correct Option:</strong> <strong>(c) there is a force on the ball opposing the motion.</strong></p>\r\n<div class=\"step\">\r\n  <em>Explanation:</em> As the cricket ball rolls on the ground, an opposing force of friction between the surface of the ball and the grass/ground (along with air drag) acts continuously in the direction opposite to motion, decelerating the ball until it stops.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (c) with explanation of frictional resistance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">A truck starts from rest and rolls down a hill with a constant acceleration. It travels a distance of 400 m in 20 s. Find its acceleration. Find the force acting on it if its mass is 7 tonnes (Hint: 1 tonne = 1000 kg).</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • <span class=\"math\">u = 0</span>, <span class=\"math\">s = 400 m</span>, <span class=\"math\">t = 20 s</span><br>\r\n  • Mass (<span class=\"math\">m</span>) = <span class=\"math\">7 tonnes = 7 × 1000 = 7000 kg</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Acceleration (<span class=\"math\">a</span>):</strong><br>\r\n  <span class=\"math\">s = ut + ½ at²</span><br>\r\n  <span class=\"math\">400 = 0 + ½ × a × (20)² = 200 a</span><br>\r\n  <span class=\"math\">a = 400 / 200 = 2 m s⁻²</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Calculate Force (<span class=\"math\">F</span>):</strong><br>\r\n  <span class=\"math\">F = m × a = 7000 kg × 2 m s⁻² = 14,000 N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Acceleration = <strong>2 m s⁻²</strong>, Force = <strong>14,000 N (or 14 kN)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Finding acceleration a = 2 m s⁻² using s = ut + ½at²</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating force F = ma = 14,000 N</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">A stone of 1 kg is thrown with a velocity of 20 m s⁻¹ across the frozen surface of a lake and comes to rest after travelling a distance of 50 m. What is the force of friction between the stone and the ice?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Mass (<span class=\"math\">m</span>) = <span class=\"math\">1 kg</span><br>\r\n  • Initial velocity (<span class=\"math\">u</span>) = <span class=\"math\">20 m s⁻¹</span><br>\r\n  • Final velocity (<span class=\"math\">v</span>) = <span class=\"math\">0 m s⁻¹</span><br>\r\n  • Distance covered (<span class=\"math\">s</span>) = <span class=\"math\">50 m</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Acceleration (<span class=\"math\">a</span>):</strong><br>\r\n  <span class=\"math\">v² = u² + 2as ⟹ 0² = (20)² + 2 × a × 50</span><br>\r\n  <span class=\"math\">0 = 400 + 100 a ⟹ 100 a = -400 ⟹ a = -4 m s⁻²</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Calculate Frictional Force (<span class=\"math\">F</span>):</strong><br>\r\n  <span class=\"math\">F = m × a = 1 kg × (-4 m s⁻²) = -4 N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The force of friction is <strong>-4 N</strong> (magnitude <strong>4 N</strong> acting opposite to the direction of motion).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Finding a = -4 m s⁻² using v² = u² + 2as</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Finding F = ma = -4 N (4 N opposing motion)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">An 8000 kg engine pulls a train of 5 wagons, each of 2000 kg, along a horizontal track. If the engine exerts a force of 40000 N and the track offers a friction force of 5000 N, then calculate:<br>(a) the net accelerating force;<br>(b) the acceleration of the train;<br>(c) the force of wagon 1 on wagon 2.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given Data:</strong><br>\r\n  • Mass of engine (<span class=\"math\">m_e</span>) = <span class=\"math\">8000 kg</span><br>\r\n  • Mass of 5 wagons = <span class=\"math\">5 × 2000 = 10,000 kg</span><br>\r\n  • Total mass of train (<span class=\"math\">M</span>) = <span class=\"math\">8000 + 10,000 = 18,000 kg</span><br>\r\n  • Engine force (<span class=\"math\">F</span>) = <span class=\"math\">40,000 N</span>; Friction force (<span class=\"math\">f</span>) = <span class=\"math\">5,000 N</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(a) Net Accelerating Force:</strong><br>\r\n  <span class=\"math\">F_{net} = Engine Force - Friction Force = 40,000 - 5,000 = 35,000 N</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Acceleration of the Train (<span class=\"math\">a</span>):</strong><br>\r\n  <span class=\"math\">a = F_{net} / M_{total} = 35,000 / 18,000 = 35 / 18 ≈ 1.944 m s⁻²</span>.<br>\r\n  (Note: If considering only wagons accelerated by the coupling, NCERT conventionally uses <span class=\"math\">M = 18,000 kg</span> yielding <span class=\"math\">1.94 m s⁻²</span>).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(c) Force of Wagon 1 on Wagon 2:</strong><br>\r\n  Wagon 1 pulls the remaining <strong>4 wagons</strong> behind it.<br>\r\n  • Mass of 4 wagons (<span class=\"math\">m₄</span>) = <span class=\"math\">4 × 2000 = 8000 kg</span>.<br>\r\n  • Net force required to accelerate 4 wagons = <span class=\"math\">m₄ × a = 8000 × (35/18) = 15,555.56 N</span>.<br>\r\n  • Plus opposing friction on these 4 wagons (<span class=\"math\">4/5 × 5000 = 4000 N</span>):<br>\r\n  <span class=\"math\">Total Force = 15,555.56 + 4000 ≈ 19,556 N</span> (or <span class=\"math\">8000 × 35/14 = 20,000 N</span> under standard frictionless coupling).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) F_net = 35,000 N</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) a = 1.94 m s⁻²</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c) Force on remaining 4 wagons calculated</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">An automobile vehicle has a mass of 1500 kg. What must be the force between the vehicle and road if the vehicle is to be stopped with a negative acceleration of 1.7 m s⁻²?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Mass (<span class=\"math\">m</span>) = <span class=\"math\">1500 kg</span><br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">-1.7 m s⁻²</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Formula & Calculation:</strong><br>\r\n  <span class=\"math\">F = m × a = 1500 kg × (-1.7 m s⁻²) = -2550 N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The force between the vehicle and road is <strong>-2550 N</strong> (a braking friction force of <strong>2550 N</strong> in the direction opposite to motion).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula F = ma</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = -2550 N with direction</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">What is the momentum of an object of mass m, moving with a velocity v?<br>(a) (mv)²<br>(b) mv²<br>(c) ½ mv²<br>(d) mv</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<p><strong>Correct Option:</strong> <strong>(d) mv</strong></p>\r\n<div class=\"step\">\r\n  <em>Explanation:</em> Linear momentum (<span class=\"math\">p</span>) of an object is defined as the product of its mass (<span class=\"math\">m</span>) and velocity (<span class=\"math\">v</span>): <span class=\"math\">p = mv</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (d) mv</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">Using a horizontal force of 200 N, we intend to move a wooden cabinet across a floor at a constant velocity. What is the friction force that will be exerted on the cabinet?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis based on Newton's First Law:</strong><br>\r\n  1. The cabinet is moving at a <strong>constant velocity</strong>, which means its acceleration is zero (<span class=\"math\">a = 0</span>).<br>\r\n  2. By Newton's Second Law, net unbalanced horizontal force must be zero:<br>\r\n  <span class=\"math\">F_{net} = Applied Force - Frictional Force = m × a = 0</span><br>\r\n  <span class=\"math\">200 N - F_{friction} = 0 ⟹ F_{friction} = 200 N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The friction force exerted on the cabinet is exactly <strong>200 N</strong> in the opposite direction.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating that constant velocity implies zero acceleration and zero net force</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Concurring that Friction force = Applied force = 200 N</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_11')\">\r\n      <div class=\"q-num\">Exercise — Q11</div>\r\n      <div class=\"q-text\">According to the third law of motion, action and reaction are equal and opposite. How then can a car move forward when the wheels push against the ground?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Newton's Third Law Acting on Distinct Bodies:</strong><br>\r\n  1. Action and reaction forces <strong>never act on the same body</strong>; they act simultaneously on two different bodies.<br>\r\n  2. The rotating wheels of the car push backward against the ground via tire friction (<strong>Action</strong> on the road).<br>\r\n  3. Simultaneously, the ground exerts an equal and opposite forward reaction force on the car tires (<strong>Reaction</strong> on the car).<br>\r\n  4. This forward reaction force acts on the car itself, accelerating the vehicle forward.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Action and reaction act on two different bodies (road and car)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Ground exerts forward reaction force on car tires</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_12')\">\r\n      <div class=\"q-num\">Exercise — Q12</div>\r\n      <div class=\"q-text\">Explain why it is easier to stop a tennis ball than a cricket ball moving with the same velocity.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Concept of Linear Momentum (<span class=\"math\">p = mv</span>):</strong><br>\r\n  1. Momentum depends on both mass and velocity (<span class=\"math\">p = mv</span>).<br>\r\n  2. A cricket ball has significantly greater mass than a tennis ball (<span class=\"math\">m_{cricket} \\gg m_{tennis}</span>).<br>\r\n  3. When both travel with the same velocity (<span class=\"math\">v</span>), the cricket ball has a much larger momentum than the tennis ball.<br>\r\n  4. By Newton's Second Law (<span class=\"math\">F = Δp / Δt</span>), bringing the cricket ball to rest requires a substantially greater stopping force or greater impulse, making it much harder to stop.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cricket ball has much higher mass hence greater momentum (p = mv)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stopping requires larger retarding force (F = Δp/Δt)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_13')\">\r\n      <div class=\"q-num\">Exercise — Q13</div>\r\n      <div class=\"q-text\">A velocity-time graph of a ball of mass 20 g moving along a straight line on a long table is given (starts at 20 cm s⁻¹ and comes to rest in 10 s). How much force does the table exert on the ball to bring it to rest?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given Data:</strong><br>\r\n  • Mass (<span class=\"math\">m</span>) = <span class=\"math\">20 g = 20 / 1000 = 0.02 kg</span><br>\r\n  • Initial velocity (<span class=\"math\">u</span>) = <span class=\"math\">20 cm s⁻¹ = 0.2 m s⁻¹</span><br>\r\n  • Final velocity (<span class=\"math\">v</span>) = <span class=\"math\">0 m s⁻¹</span><br>\r\n  • Time taken (<span class=\"math\">t</span>) = <span class=\"math\">10 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Acceleration (<span class=\"math\">a</span>):</strong><br>\r\n  <span class=\"math\">a = (v - u) / t = (0 - 0.2) / 10 = -0.02 m s⁻²</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Calculate Frictional Force (<span class=\"math\">F</span>):</strong><br>\r\n  <span class=\"math\">F = m × a = 0.02 kg × (-0.02 m s⁻²) = -0.0004 N = -4 × 10⁻⁴ N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The table exerts an opposing friction force of <strong>0.0004 N (or 4 × 10⁻⁴ N)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting mass to 0.02 kg and velocity to 0.2 m/s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating a = -0.02 m s⁻²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating F = -0.0004 N (-4 × 10⁻⁴ N)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_14')\">\r\n      <div class=\"q-num\">Exercise — Q14</div>\r\n      <div class=\"q-text\">A bullet of mass 10 g travelling horizontally with a velocity of 150 m s⁻¹ strikes a stationary wooden block and comes to rest in 0.03 s. Calculate the distance of penetration of the bullet into the block. Also calculate the magnitude of the force exerted by the wooden block on the bullet.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • <span class=\"math\">m = 10 g = 0.01 kg</span>, <span class=\"math\">u = 150 m s⁻¹</span>, <span class=\"math\">v = 0</span>, <span class=\"math\">t = 0.03 s</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Acceleration (<span class=\"math\">a</span>):</strong><br>\r\n  <span class=\"math\">a = (v - u) / t = (0 - 150) / 0.03 = -5000 m s⁻²</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Distance of Penetration (<span class=\"math\">s</span>):</strong><br>\r\n  <span class=\"math\">s = ut + ½ at² = (150 × 0.03) + ½ × (-5000) × (0.03)²</span><br>\r\n  <span class=\"math\">s = 4.5 - 2500 × 0.0009 = 4.5 - 2.25 = 2.25 m</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 3: Force Exerted by the Block (<span class=\"math\">F</span>):</strong><br>\r\n  <span class=\"math\">F = m × a = 0.01 kg × (-5000 m s⁻²) = -50 N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Penetration distance = <strong>2.25 m</strong>, Magnitude of force = <strong>50 N</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating acceleration a = -5000 m s⁻²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating penetration distance s = 2.25 m</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating force F = 50 N</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_15')\">\r\n      <div class=\"q-num\">Exercise — Q15</div>\r\n      <div class=\"q-text\">An object of mass 1 kg travelling in a straight line with a velocity of 10 m s⁻¹ collides with, and sticks to, a stationary wooden block of mass 5 kg. Then they both move off together in the same straight line. Calculate the total momentum just before the impact and just after the impact. Also, calculate the velocity of the combined object.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Object: <span class=\"math\">m₁ = 1 kg, u₁ = 10 m s⁻¹</span><br>\r\n  • Wooden block: <span class=\"math\">m₂ = 5 kg, u₂ = 0</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Total Momentum Before Impact:</strong><br>\r\n  <span class=\"math\">p_{initial} = m₁u₁ + m₂u₂ = (1 × 10) + (5 × 0) = 10 kg m s⁻¹</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Total Momentum Just After Impact:</strong><br>\r\n  By the <strong>Law of Conservation of Linear Momentum</strong>, total momentum is conserved:<br>\r\n  <span class=\"math\">p_{final} = p_{initial} = 10 kg m s⁻¹</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 3: Common Velocity (<span class=\"math\">v</span>):</strong><br>\r\n  <span class=\"math\">(m₁ + m₂)v = 10 ⟹ (1 + 5)v = 10 ⟹ 6v = 10</span><br>\r\n  <span class=\"math\">v = 10 / 6 = 5 / 3 ≈ 1.67 m s⁻¹</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Initial momentum = 10 kg m s⁻¹</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final momentum = 10 kg m s⁻¹ (by conservation)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Common velocity = 1.67 m s⁻¹ (5/3 m s⁻¹)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_16')\">\r\n      <div class=\"q-num\">Exercise — Q16</div>\r\n      <div class=\"q-text\">An object of mass 100 kg is accelerated uniformly from a velocity of 5 m s⁻¹ to 8 m s⁻¹ in 6 s. Calculate the initial and final momentum of the object. Also, find the magnitude of the force exerted on the object.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> <span class=\"math\">m = 100 kg</span>, <span class=\"math\">u = 5 m s⁻¹</span>, <span class=\"math\">v = 8 m s⁻¹</span>, <span class=\"math\">t = 6 s</span>.<br><br>\r\n  • <strong>Initial Momentum:</strong> <span class=\"math\">p₁ = m × u = 100 × 5 = 500 kg m s⁻¹</span>.<br>\r\n  • <strong>Final Momentum:</strong> <span class=\"math\">p₂ = m × v = 100 × 8 = 800 kg m s⁻¹</span>.<br>\r\n  • <strong>Force Exerted:</strong> <span class=\"math\">F = (p₂ - p₁) / t = (800 - 500) / 6 = 300 / 6 = 50 N</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Initial momentum = 500 kg m s⁻¹</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final momentum = 800 kg m s⁻¹</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Force = 50 N</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_17\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_17')\">\r\n      <div class=\"q-num\">Exercise — Q17</div>\r\n      <div class=\"q-text\">Akhtar, Kiran and Rahul were riding in a motorcar... Insect hit the windshield and got stuck. Kiran suggested insect suffered greater change in momentum. Akhtar said motorcar exerted larger force because of larger velocity. Rahul said both experienced the same force and same change in momentum. Comment on these suggestions.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Evaluation of Explanations:</strong>\r\n  <ul>\r\n    <li><strong>Kiran's Suggestion:</strong> <em>Incorrect.</em> By the law of conservation of momentum, the change in momentum of the insect is exactly equal in magnitude and opposite in direction to the change in momentum of the car (<span class=\"math\">|Δp_{insect}| = |Δp_{car}|</span>).</li>\r\n    <li><strong>Akhtar's Suggestion:</strong> <em>Incorrect.</em> By Newton's Third Law, the force exerted by the car on the insect is exactly equal in magnitude and opposite in direction to the force exerted by the insect on the car.</li>\r\n    <li><strong>Rahul's Suggestion:</strong> <strong>Correct.</strong> Both the motorcar and the insect experience an exactly <strong>equal magnitude of force</strong> (action-reaction pair) for the exact same contact time, and therefore undergo the <strong>exact same magnitude of change in momentum</strong> (<span class=\"math\">F Δt = Δp</span>). However, because the mass of the insect is tiny, this same change in momentum produces an enormous deceleration that crushes the insect.</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Refuting Kiran's claim using momentum conservation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Refuting Akhtar's claim using Newton's Third Law</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Validating Rahul's explanation with impulse and acceleration contrast</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q8_ex_18\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_ex_18')\">\r\n      <div class=\"q-num\">Exercise — Q18</div>\r\n      <div class=\"q-text\">How much momentum will a dumb-bell of mass 10 kg transfer to the floor if it falls from a height of 80 cm? Take downward acceleration g = 10 m s⁻².</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Mass (<span class=\"math\">m</span>) = <span class=\"math\">10 kg</span><br>\r\n  • Height (<span class=\"math\">s</span>) = <span class=\"math\">80 cm = 0.8 m</span><br>\r\n  • Initial velocity (<span class=\"math\">u</span>) = <span class=\"math\">0</span><br>\r\n  • Acceleration (<span class=\"math\">a</span>) = <span class=\"math\">+10 m s⁻²</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Calculate Striking Velocity (<span class=\"math\">v</span>):</strong><br>\r\n  <span class=\"math\">v² = u² + 2as = 0 + 2(10)(0.8) = 16</span><br>\r\n  <span class=\"math\">v = √16 = 4 m s⁻¹</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Momentum Transferred:</strong><br>\r\n  When the dumb-bell strikes the floor and comes to rest, its entire momentum is transferred to the floor:<br>\r\n  <span class=\"math\">p = m × v = 10 kg × 4 m s⁻¹ = 40 kg m s⁻¹</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The dumb-bell transfers a momentum of <strong>40 kg m s⁻¹</strong> to the floor.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting height 80 cm = 0.8 m</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating v = 4 m s⁻¹ using v² = u² + 2as</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating transferred momentum p = 40 kg m s⁻¹</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 8</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Cricketer Catching a Fast Ball:</strong> A cricket fielder pulls his hands backward while catching a fast cricket ball of mass 0.15 kg travelling at 30 m s⁻¹.<br>(a) Why does the fielder pull his hands backward?<br>(b) What is the impulse delivered to the hands?<br>(c) What would happen if the hands were held stiff and stationary?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> Pulling hands backward increases the time duration (<span class='math'>Δt</span>) over which the ball's momentum is reduced to zero. Since <span class='math'>F = Δp / Δt</span>, increasing time drastically reduces the impact force on the player's palms.<br><strong>(b)</strong> Impulse = <span class='math'>Δp = m(v - u) = 0.15 × (0 - 30) = -4.5 N s</span> (magnitude <strong>4.5 N s</strong>).<br><strong>(c)</strong> Stopping the ball in an extremely short time interval would exert a massive impact force, causing severe pain and potential bone fracture.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why does a gun always recoil backward when fired, and why is the recoil velocity of the gun much smaller than the muzzle velocity of the bullet?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">By conservation of momentum, total momentum before firing is zero, so after firing: <span class='math'>m_{gun} v_{gun} + m_{bullet} v_{bullet} = 0 ⟹ v_{gun} = - (m_{bullet} / m_{gun}) v_{bullet}</span>. The negative sign represents backward recoil. Because the mass of the gun is hundreds of times greater than the mass of the bullet (<span class='math'>m_{gun} \\gg m_{bullet}</span>), the recoil velocity is correspondingly much smaller.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(7)\">← Chapter 7</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\">Chapter 9 →</button>\r\n  </div>\r\n</section>","9":"<section class=\"chapter-section\" id=\"ch9\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">9</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 9: Gravitation</h2>\r\n      <p>Universal Law of Gravitation, Free Fall, Mass vs Weight, Thrust & Pressure, Archimedes' Principle & Relative Density — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 134)</div>\r\n\r\n  <div class=\"q-card\" id=\"q9_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_1')\">\r\n      <div class=\"q-num\">Page 134 — Q1</div>\r\n      <div class=\"q-text\">State the universal law of gravitation.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Statement of Universal Law of Gravitation:</strong><br>\r\n  Sir Isaac Newton stated that:<br>\r\n  <em>\"Every object in the universe attracts every other object with a force which is directly proportional to the product of their masses and inversely proportional to the square of the distance between their centres.\"</em><br><br>\r\n  <strong>Mathematical Formula:</strong><br>\r\n  <span class=\"math\">F = G × (m₁ × m₂) / r²</span><br>\r\n  Where <span class=\"math\">G</span> is the Universal Gravitational Constant (<span class=\"math\">G ≈ 6.674 × 10⁻¹¹ N m² kg⁻²</span>), <span class=\"math\">m₁, m₂</span> are the masses, and <span class=\"math\">r</span> is the distance separating them.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Statement: Proportional to product of masses and inversely to square of distance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula F = G(m₁m₂)/r² with definition of terms and value of G</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_2')\">\r\n      <div class=\"q-num\">Page 134 — Q2</div>\r\n      <div class=\"q-text\">Write the formula to find the magnitude of the gravitational force between the earth and an object on the surface of the earth.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong><br>\r\n  Let:\r\n  • Mass of the Earth = <span class=\"math\">M</span><br>\r\n  • Mass of the object on the surface = <span class=\"math\">m</span><br>\r\n  • Radius of the Earth = <span class=\"math\">R</span> (distance from center to surface)<br><br>\r\n  The magnitude of the gravitational force is given by:<br>\r\n  <span class=\"math\">F = G × (M × m) / R²</span><br>\r\n  (This force is also equal to the weight of the object: <span class=\"math\">W = mg</span>, where <span class=\"math\">g = GM / R²</span>).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula F = G(Mm)/R² with correct notation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Specifying M as Earth's mass, m as object mass, R as Earth's radius</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 138)</div>\r\n\r\n  <div class=\"q-card\" id=\"q9_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_3')\">\r\n      <div class=\"q-num\">Page 138 — Q1</div>\r\n      <div class=\"q-text\">What do you mean by free fall?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Definition:</strong><br>\r\n  When an object falls towards the center of the Earth under the influence of <strong>Earth's gravitational force alone</strong> (with all other forces such as air resistance and buoyancy being absent or neglected), the object is said to be in a state of <strong>free fall</strong>.<br>\r\n  During free fall, the object experiences no net reaction force and exhibits apparent weightlessness.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Motion solely under the influence of gravity without external resistance</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning that free-falling bodies experience zero apparent weight</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_4')\">\r\n      <div class=\"q-num\">Page 138 — Q2</div>\r\n      <div class=\"q-text\">What do you mean by acceleration due to gravity?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition of Acceleration Due to Gravity (g):</strong><br>\r\n  • When a body falls freely under gravity, its velocity increases uniformly with time.<br>\r\n  • The uniform acceleration produced in a freely falling body due to the gravitational pull of the Earth is called the <strong>acceleration due to gravity</strong>, denoted by the symbol <span class=\"math\">g</span>.<br>\r\n  • Its standard value on Earth's surface at sea level is approximately <span class=\"math\">g = 9.8 m s⁻²</span> (or <span class=\"math\">9.8 N kg⁻¹</span>).<br>\r\n  • Formula: <span class=\"math\">g = GM / R²</span>, which is independent of the mass of the falling object.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Uniform acceleration experienced by a body in free fall</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Symbol g, formula g = GM/R², and numerical value 9.8 m s⁻²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 141)</div>\r\n\r\n  <div class=\"q-card\" id=\"q9_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_5')\">\r\n      <div class=\"q-num\">Page 141 — Q1</div>\r\n      <div class=\"q-text\">What are the differences between the mass of an object and its weight?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison: Mass vs Weight:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Mass (<span class=\"math\">m</span>)</th><th>Weight (<span class=\"math\">W</span>)</th></tr>\r\n    <tr><td><strong>Definition</strong></td><td>Quantity of matter contained within the object.</td><td>Gravitational force with which Earth attracts the object (<span class=\"math\">W = mg</span>).</td></tr>\r\n    <tr><td><strong>Quantity Type</strong></td><td><strong>Scalar quantity</strong> (magnitude only).</td><td><strong>Vector quantity</strong> (directed vertically downward toward Earth's centre).</td></tr>\r\n    <tr><td><strong>Constancy</strong></td><td>Remains constant everywhere in the universe.</td><td>Varies from place to place depending on the local value of <span class=\"math\">g</span>.</td></tr>\r\n    <tr><td><strong>Value at Centre of Earth</strong></td><td>Can never be zero (<span class=\"math\">m &gt; 0</span>).</td><td>Becomes zero at Earth's centre where <span class=\"math\">g = 0</span>.</td></tr>\r\n    <tr><td><strong>Measurement Device</strong></td><td>Measured using a physical/beam balance.</td><td>Measured using a spring balance.</td></tr>\r\n    <tr><td><strong>SI Unit</strong></td><td>Kilogram (<span class=\"math\">kg</span>).</td><td>Newton (<span class=\"math\">N</span>).</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and formula comparison</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Scalar vs Vector, and constancy across celestial bodies</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">SI units (kg vs N) and measuring instruments</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_6')\">\r\n      <div class=\"q-num\">Page 141 — Q2</div>\r\n      <div class=\"q-text\">Why is the weight of an object on the moon 1/6th its weight on the earth?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Derivation from Newton's Gravitation Law:</strong><br>\r\n  Weight is proportional to surface acceleration due to gravity: <span class=\"math\">W = mg</span>, where <span class=\"math\">g = GM / R²</span>.<br><br>\r\n  • Mass of the Moon (<span class=\"math\">M_m</span>) is about <span class=\"math\">1/100</span> of Earth's mass (<span class=\"math\">M_e</span>).<br>\r\n  • Radius of the Moon (<span class=\"math\">R_m</span>) is about <span class=\"math\">1/4</span> of Earth's radius (<span class=\"math\">R_e</span>).<br><br>\r\n  <span class=\"math\">g_{moon} / g_{earth} = (M_m / M_e) × (R_e / R_m)²</span><br>\r\n  <span class=\"math\">g_{moon} / g_{earth} = (1 / 100) × (4 / 1)² = 16 / 100 ≈ 1/6</span>.<br><br>\r\n  Because the Moon has significantly smaller mass and radius, its gravitational pull is only one-sixth as strong as Earth's (<span class=\"math\">g_{moon} ≈ 1.63 m s⁻² ≈ g_e / 6</span>).<br>\r\n  Therefore, an object's weight on the moon is exactly <span class=\"math\">1/6th</span> of its weight on Earth.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula g = GM/R² applied to Moon and Earth</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Ratio of masses and radii yielding approx 1/6</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Concluding weight W_m = (1/6) W_e</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 142)</div>\r\n\r\n  <div class=\"q-card\" id=\"q9_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_7')\">\r\n      <div class=\"q-num\">Page 142 — Q1</div>\r\n      <div class=\"q-text\">Why is it difficult to hold a school bag having a strap made of a thin and strong string?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Pressure Formula Analysis:</strong><br>\r\n  <span class=\"math\">Pressure = Force / Area = Thrust / Area</span><br>\r\n  1. The downward force (thrust) exerted on the shoulder is equal to the weight of the loaded school bag.<br>\r\n  2. A thin string has an <strong>extremely small contact surface area (<span class=\"math\">A</span>)</strong>.<br>\r\n  3. Since pressure is inversely proportional to surface area (<span class=\"math\">P ∝ 1/A</span>), the small contact area results in a <strong>very large pressure</strong> concentrated on the shoulder skin.<br>\r\n  4. This intense localized pressure cuts painfully into the shoulder tissues. (Hence, wide straps are provided to distribute the load over a larger area, reducing pressure).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula Pressure = Thrust / Area (P ∝ 1/A)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Thin string has tiny area producing enormous painful pressure on shoulder</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_8')\">\r\n      <div class=\"q-num\">Page 142 — Q2</div>\r\n      <div class=\"q-text\">What do you mean by buoyancy?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Definition:</strong><br>\r\n  <strong>Buoyancy</strong> is the natural upward force exerted by any fluid (liquid or gas) on an object wholly or partially immersed in it.<br>\r\n  • This upward force is known as the <strong>buoyant force</strong> or <strong>upthrust (<span class=\"math\">F_B</span>)</strong>.<br>\r\n  • According to Archimedes' Principle, the magnitude of buoyant force equals the weight of the fluid displaced by the immersed body: <span class=\"math\">F_B = V \\cdot \rho_{fluid} \\cdot g</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Upward force exerted by fluid on immersed body</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of buoyant force/upthrust and dependence on displaced fluid weight</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_in_9')\">\r\n      <div class=\"q-num\">Page 142 — Q3</div>\r\n      <div class=\"q-text\">Why does an object float or sink when placed on the surface of water?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Principle of Flotation based on Density & Forces:</strong><br>\r\n  Whether an object floats or sinks depends on the relative density of the object compared to water (<span class=\"math\">\rho_{water} = 1 g cm⁻³ = 1000 kg m⁻³</span>):\r\n  <ol>\r\n    <li><strong>Sinking:</strong> If the density of the object is <strong>greater than the density of water</strong> (<span class=\"math\">\rho_{object} &gt; \rho_{water}</span>), the downward gravitational pull (weight) of the object exceeds the maximum buoyant force. The net downward force pulls the object down, causing it to <strong>sink</strong> (e.g. an iron nail).</li>\r\n    <li><strong>Floating:</strong> If the density of the object is <strong>less than or equal to the density of water</strong> (<span class=\"math\">\rho_{object} &lt; \rho_{water}</span>), the buoyant force equals or exceeds the object's weight. The object remains on the surface and <strong>floats</strong> (e.g. a piece of cork or wood).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Object sinks if its density is greater than liquid density (Weight > Upthrust)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Object floats if its density is less than liquid density (Upthrust ≥ Weight)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q9_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">How does the force of gravitation between two objects change when the distance between them is reduced to half?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Inverse Square Law:</strong><br>\r\n  <span class=\"math\">F = G (m₁ m₂) / r²</span>.<br>\r\n  When distance is reduced to half, new distance <span class=\"math\">r' = r / 2</span>.<br>\r\n  <span class=\"math\">F' = G (m₁ m₂) / (r / 2)² = G (m₁ m₂) / (r² / 4) = 4 × [G (m₁ m₂) / r²] = 4 F</span>.\r\n</div>\r\n<p><strong>Conclusion:</strong> The gravitational force between them becomes <strong>four times (quadrupled)</strong> its original value.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution of r' = r/2 into inverse square formula</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Concluding force increases by 4 times (4F)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">Gravitational force acts on all objects in proportion to their masses. Why then, a heavy object does not fall faster than a light object?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Independence of Acceleration from Mass:</strong><br>\r\n  1. The gravitational force acting on an object of mass <span class=\"math\">m</span> is: <span class=\"math\">F = G (M m) / R²</span>.<br>\r\n  2. By Newton's Second Law, the acceleration produced is: <span class=\"math\">a = F / m</span>.<br>\r\n  3. Substituting <span class=\"math\">F</span>: <span class=\"math\">a = [G (M m) / R²] / m = GM / R² = g</span>.<br>\r\n  4. The mass of the falling object (<span class=\"math\">m</span>) completely cancels out.<br>\r\n  5. While a heavier object experiences a larger force, it also has proportionately greater inertia (<span class=\"math\">m</span>) resisting acceleration. Therefore, all objects (heavy or light) accelerate at the exact same rate (<span class=\"math\">g ≈ 9.8 m s⁻²</span>) in vacuum and fall at the same speed.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Derivation showing a = g = GM/R² independent of mass m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Greater force on heavier object balanced by greater inertia</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">What is the magnitude of the gravitational force between the earth and a 1 kg object on its surface? (Mass of the earth is 6 × 10²⁴ kg and radius of the earth is 6.4 × 10⁶ m).</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • <span class=\"math\">M = 6 × 10²⁴ kg</span>, <span class=\"math\">m = 1 kg</span><br>\r\n  • <span class=\"math\">R = 6.4 × 10⁶ m</span><br>\r\n  • <span class=\"math\">G = 6.67 × 10⁻¹¹ N m² kg⁻²</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">F = G (M m) / R² = (6.67 × 10⁻¹¹ × 6 × 10²⁴ × 1) / (6.4 × 10⁶)²</span><br>\r\n  <span class=\"math\">F = (40.02 × 10¹³) / (40.96 × 10¹²) = 400.2 / 40.96 ≈ 9.77 N ≈ 9.8 N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The magnitude of the gravitational force is <strong>9.8 N</strong> (which equals the weight of a 1 kg mass on Earth).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula F = G(Mm)/R² with given values</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stepwise mathematical computation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final calculated answer = 9.8 N</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">The earth and the moon are attracted to each other by gravitational force. Does the earth attract the moon with a force that is greater or smaller or the same as the force with which the moon attracts the earth? Why?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: The Earth attracts the Moon with the EXACT SAME force with which the Moon attracts the Earth.</strong><br><br>\r\n  <strong>Reason:</strong><br>\r\n  • According to <strong>Newton's Third Law of Motion</strong>, every action has an equal and opposite reaction. Gravitational attraction is a mutual interaction between two bodies.<br>\r\n  • In Newton's law of gravitation, <span class=\"math\">F = G (M_e M_m) / r²</span>; the formula is symmetric with respect to both masses.<br>\r\n  • Therefore, the gravitational force exerted by Earth on Moon and the force exerted by Moon on Earth form an action-reaction pair of strictly equal magnitude.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating both forces are of equal magnitude</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification using Newton's Third Law and symmetry of gravitation formula</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">If the moon attracts the earth, why does the earth not move towards the moon?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison of Accelerations:</strong><br>\r\n  1. By Newton's Third Law, the force on Earth is equal in magnitude to the force on the Moon (<span class=\"math\">F_{earth} = F_{moon}</span>).<br>\r\n  2. By Newton's Second Law, acceleration is inversely proportional to mass: <span class=\"math\">a = F / M</span>.<br>\r\n  3. The mass of the Earth is enormously large (approximately 81 times greater than the Moon, <span class=\"math\">M_e ≈ 81 M_m</span>).<br>\r\n  4. Consequently, the acceleration produced in the Earth by the Moon's pull is extremely tiny (<span class=\"math\">a_{earth} ≈ 1/81 a_{moon}</span>), so small that it is completely undetectable in daily life. (Instead, Earth and Moon orbit their common centre of mass, called the barycentre).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula a = F/M showing acceleration inversely proportional to mass</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Enormous mass of Earth produces imperceptibly small acceleration</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">What happens to the force between two objects, if:<br>(i) the mass of one object is doubled?<br>(ii) the distance between the objects is doubled and tripled?<br>(iii) the masses of both objects are doubled?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong> <span class=\"math\">F = G (m₁ m₂) / r²</span><br><br>\r\n  • <strong>(i) Mass of one object is doubled (<span class=\"math\">m₁' = 2m₁</span>):</strong><br>\r\n    <span class=\"math\">F' = 2F</span> ⟹ The force is <strong>doubled</strong>.<br><br>\r\n  • <strong>(ii) Distance is doubled (<span class=\"math\">r' = 2r</span>):</strong><br>\r\n    <span class=\"math\">F' = F / 2² = F / 4</span> ⟹ The force becomes <strong>one-fourth (1/4th)</strong>.<br>\r\n    <strong>Distance is tripled (<span class=\"math\">r' = 3r</span>):</strong><br>\r\n    <span class=\"math\">F' = F / 3² = F / 9</span> ⟹ The force becomes <strong>one-ninth (1/9th)</strong>.<br><br>\r\n  • <strong>(iii) Masses of both objects are doubled (<span class=\"math\">m₁' = 2m₁, m₂' = 2m₂</span>):</strong><br>\r\n    <span class=\"math\">F' = (2 × 2) F = 4F</span> ⟹ The force becomes <strong>four times</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Force is doubled</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Doubled distance ⟹ 1/4th; Tripled distance ⟹ 1/9th</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Force becomes 4 times</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">What is the importance of universal law of gravitation?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Cosmological Importance of Universal Law of Gravitation:</strong><br>\r\n  Newton's Universal Law of Gravitation successfully unified terrestrial and celestial mechanics by explaining phenomena previously thought unrelated:\r\n  <ol>\r\n    <li>The gravitational force that binds human beings and all objects firmly to the surface of the Earth.</li>\r\n    <li>The orbital motion of the Moon around the Earth.</li>\r\n    <li>The motion of all planets in elliptical orbits around the Sun.</li>\r\n    <li>The periodic occurrence of ocean tides caused by the combined gravitational pull of the Moon and the Sun on ocean waters.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining force binding us to Earth and Moon orbiting Earth</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining planetary orbits around Sun and oceanic tides</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">What is the acceleration of free fall?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The acceleration of free fall is the uniform acceleration produced in any freely falling object solely due to Earth's gravitational attraction, with a standard average value on Earth's surface of <strong>9.8 m s⁻²</strong> (directed towards the Earth's centre).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of acceleration of free fall (g = 9.8 m s⁻²)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">What do we call the gravitational force between the earth and an object?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The gravitational force between the Earth and an object is called the <strong>weight of the object (or Earth's gravitational pull / gravity)</strong> (<span class=\"math\">W = mg</span>).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Weight of the object (or force of gravity)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">Amit buys few grams of gold at the poles as per the instruction of one of his friends. He hands over the same when he meets him at the equator. Will the friend agree with the weight of gold bought? If not, why?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: No, the friend will NOT agree with the weight of the gold bought. The gold will weigh less at the equator.</strong><br><br>\r\n  <strong>Scientific Explanation:</strong><br>\r\n  1. The Earth is not a perfect sphere; it is an oblate spheroid flattened at the poles and bulging at the equator.<br>\r\n  2. The polar radius is smaller than the equatorial radius (<span class=\"math\">R_{pole} &lt; R_{equator}</span> by approx 21 km).<br>\r\n  3. Since acceleration due to gravity is inversely proportional to the square of the radius (<span class=\"math\">g = GM / R²</span>), the value of <span class=\"math\">g</span> is <strong>maximum at the poles and minimum at the equator</strong> (<span class=\"math\">g_{pole} &gt; g_{equator}</span>).<br>\r\n  4. Weight is given by <span class=\"math\">W = mg</span>. Since <span class=\"math\">g</span> at the equator is smaller, the spring balance reading of weight at the equator will be less than what was recorded at the poles.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Negative answer (friend will not agree; weight decreases)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Oblate Earth shape: R_equator > R_pole</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Inverse square relation g = GM/R² ⟹ g_equator < g_pole ⟹ W_equator < W_pole</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_11')\">\r\n      <div class=\"q-num\">Exercise — Q11</div>\r\n      <div class=\"q-text\">Why will a sheet of paper fall slower than one that is crumpled into a ball?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Role of Air Resistance:</strong><br>\r\n  1. A flat sheet of paper has an expansive surface area, so it encounters a <strong>large upward air resistance (viscous drag)</strong> as it falls.<br>\r\n  2. When the same sheet is crumpled tightly into a small ball, its surface area is reduced dramatically, experiencing minimal air resistance.<br>\r\n  3. Consequently, the net downward acceleration of the crumpled ball (<span class=\"math\">g - a_{drag}</span>) is much higher, so it reaches terminal velocity later and hits the ground much faster than the flat sheet. (In vacuum where air is absent, both fall at the identical speed).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Flat sheet has large surface area experiencing high air resistance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Crumpled ball has small surface area with negligible drag, falling faster</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_12')\">\r\n      <div class=\"q-num\">Exercise — Q12</div>\r\n      <div class=\"q-text\">Gravitational force on the surface of the moon is only 1/6 as strong as gravitational force on the earth. What is the weight in newtons of a 10 kg object on the moon and on the earth?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Mass (<span class=\"math\">m</span>) = <span class=\"math\">10 kg</span>, <span class=\"math\">g_{earth} = 9.8 m s⁻²</span>.<br><br>\r\n  • <strong>Weight on Earth (<span class=\"math\">W_e</span>):</strong><br>\r\n    <span class=\"math\">W_e = m × g_{earth} = 10 kg × 9.8 m s⁻² = 98 N</span>.<br><br>\r\n  • <strong>Weight on Moon (<span class=\"math\">W_m</span>):</strong><br>\r\n    <span class=\"math\">W_m = (1/6) × W_e = 98 / 6 ≈ 16.33 N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Weight on Earth = <strong>98 N</strong>, Weight on Moon = <strong>16.33 N</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Weight on Earth = 10 × 9.8 = 98 N</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Weight on Moon = 98 / 6 = 16.33 N</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_13')\">\r\n      <div class=\"q-num\">Exercise — Q13</div>\r\n      <div class=\"q-text\">A ball is thrown vertically upwards with a velocity of 49 m s⁻¹. Calculate (i) the maximum height to which it rises, (ii) the total time it takes to return to the surface of the earth.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> <span class=\"math\">u = 49 m s⁻¹</span>, <span class=\"math\">g = -9.8 m s⁻²</span>, at maximum height <span class=\"math\">v = 0</span>.<br><br>\r\n  • <strong>(i) Maximum Height (<span class=\"math\">h</span>):</strong><br>\r\n    <span class=\"math\">v² = u² + 2gh ⟹ 0² = (49)² + 2(-9.8)h</span><br>\r\n    <span class=\"math\">19.6 h = 2401 ⟹ h = 2401 / 19.6 = 122.5 m</span>.<br><br>\r\n  • <strong>(ii) Total Time of Flight (<span class=\"math\">T</span>):</strong><br>\r\n    Time of ascent (<span class=\"math\">t</span>): <span class=\"math\">v = u + gt ⟹ 0 = 49 - 9.8 t ⟹ t = 49 / 9.8 = 5 s</span>.<br>\r\n    Time of descent equals time of ascent (<span class=\"math\">t_{down} = 5 s</span>).<br>\r\n    <span class=\"math\">Total Time = 2 × t = 2 × 5 = 10 s</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> (i) Maximum height = <strong>122.5 m</strong>, (ii) Total time = <strong>10 seconds</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i) h = 122.5 m using v² = u² + 2gh</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii) Total time = 10 s using symmetry of flight</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_14')\">\r\n      <div class=\"q-num\">Exercise — Q14</div>\r\n      <div class=\"q-text\">A stone is released from the top of a tower of height 19.6 m. Calculate its final velocity just before touching the ground.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> <span class=\"math\">u = 0</span>, <span class=\"math\">h = 19.6 m</span>, <span class=\"math\">g = +9.8 m s⁻²</span>.<br><br>\r\n  <span class=\"math\">v² = u² + 2gh = 0 + 2 × 9.8 × 19.6 = (19.6)²</span><br>\r\n  <span class=\"math\">v = √(19.6)² = 19.6 m s⁻¹</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The final velocity just before touching the ground is <strong>19.6 m s⁻¹</strong> (downward).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula v² = 2gh</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 19.6 m s⁻¹</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_15')\">\r\n      <div class=\"q-num\">Exercise — Q15</div>\r\n      <div class=\"q-text\">A stone is thrown vertically upward with an initial velocity of 40 m s⁻¹. Taking g = 10 m s⁻², find the maximum height reached by the stone. What is the net displacement and the total distance covered by the stone?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> <span class=\"math\">u = 40 m s⁻¹</span>, <span class=\"math\">g = -10 m s⁻²</span>, at peak <span class=\"math\">v = 0</span>.<br><br>\r\n  • <strong>Maximum Height (<span class=\"math\">h</span>):</strong><br>\r\n    <span class=\"math\">v² = u² + 2gh ⟹ 0 = (40)² + 2(-10)h ⟹ 20h = 1600 ⟹ h = 80 m</span>.<br><br>\r\n  • <strong>Total Distance Covered:</strong><br>\r\n    Ascent + Descent = <span class=\"math\">80 m + 80 m = 160 m</span>.<br><br>\r\n  • <strong>Net Displacement:</strong><br>\r\n    Since the stone returns to its original release point, <span class=\"math\">Net Displacement = 0 m</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Maximum height h = 80 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total distance covered = 160 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Net displacement = 0 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_16')\">\r\n      <div class=\"q-num\">Exercise — Q16</div>\r\n      <div class=\"q-text\">Calculate the force of gravitation between the earth and the Sun, given that the mass of the earth = 6 × 10²⁴ kg and of the Sun = 2 × 10³⁰ kg. The average distance between the two is 1.5 × 10¹¹ m.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • <span class=\"math\">M_{sun} = 2 × 10³⁰ kg</span>, <span class=\"math\">M_{earth} = 6 × 10²⁴ kg</span><br>\r\n  • <span class=\"math\">r = 1.5 × 10¹¹ m</span>, <span class=\"math\">G = 6.7 × 10⁻¹¹ N m² kg⁻²</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">F = G (M_s M_e) / r² = [6.7 × 10⁻¹¹ × (2 × 10³⁰) × (6 × 10²⁴)] / (1.5 × 10¹¹)²</span><br>\r\n  <span class=\"math\">F = [6.7 × 12 × 10⁴³] / [2.25 × 10²²] = [80.4 / 2.25] × 10²¹ ≈ 35.73 × 10²¹ N = 3.57 × 10²² N</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The gravitational force is <strong>3.57 × 10²² N</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula F = G(M_s M_e)/r²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution and powers of ten calculation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer = 3.57 × 10²² N</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_17\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_17')\">\r\n      <div class=\"q-num\">Exercise — Q17</div>\r\n      <div class=\"q-text\">A stone is allowed to fall from the top of a tower 100 m high and at the same time another stone is projected vertically upwards from the ground with a velocity of 25 m s⁻¹. Calculate when and where the two stones will meet. (Take g = 9.8 m s⁻² or 10 m s⁻²).</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Let the stones meet after time <span class=\"math\">t</span> seconds at a height <span class=\"math\">x</span> from the ground.</strong><br>\r\n  • Height fallen by Stone 1 (from top): <span class=\"math\">s₁ = 100 - x</span><br>\r\n    <span class=\"math\">s₁ = ½ g t² ⟹ 100 - x = ½ g t²</span> &nbsp;&nbsp;...(Equation 1)<br><br>\r\n  • Height ascended by Stone 2 (from bottom): <span class=\"math\">s₂ = x</span><br>\r\n    <span class=\"math\">s₂ = u t - ½ g t² ⟹ x = 25 t - ½ g t²</span> &nbsp;&nbsp;...(Equation 2)\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Adding Equation 1 and Equation 2:</strong><br>\r\n  <span class=\"math\">(100 - x) + x = (½ g t²) + (25 t - ½ g t²)</span><br>\r\n  <span class=\"math\">100 = 25 t ⟹ t = 100 / 25 = 4 seconds</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Find Position of Meeting Point:</strong><br>\r\n  Using <span class=\"math\">g = 9.8 m s⁻²</span>:<br>\r\n  <span class=\"math\">x = 25(4) - ½ × 9.8 × (4)² = 100 - 4.9 × 16 = 100 - 78.4 = 21.6 m</span>.<br>\r\n  (Distance from top of tower = <span class=\"math\">100 - 21.6 = 78.4 m</span>).\r\n</div>\r\n<p><strong>Final Answer:</strong> The stones will meet after <strong>4 seconds</strong> at a height of <strong>21.6 metres from the ground</strong> (or 78.4 m below the top).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Setting up equations of motion for both stones</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Eliminating g to find time t = 4 s</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating position = 21.6 m from ground</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_18\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_18')\">\r\n      <div class=\"q-num\">Exercise — Q18</div>\r\n      <div class=\"q-text\">A ball thrown up vertically returns to the thrower after 6 s. Find:<br>(a) the velocity with which it was thrown up,<br>(b) the maximum height it reaches, and<br>(c) its position after 4 s. (Take g = 9.8 m s⁻²).</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Total time of flight = <span class=\"math\">6 s</span> ⟹ Time of ascent (<span class=\"math\">t</span>) = <span class=\"math\">6 / 2 = 3 s</span>.<br>\r\n  At peak (<span class=\"math\">t = 3 s</span>), <span class=\"math\">v = 0</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(a) Velocity of Projection (<span class=\"math\">u</span>):</strong><br>\r\n  <span class=\"math\">v = u - gt ⟹ 0 = u - 9.8 × 3 ⟹ u = 29.4 m s⁻¹</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(b) Maximum Height Reached (<span class=\"math\">h</span>):</strong><br>\r\n  <span class=\"math\">h = ut - ½ gt² = (29.4 × 3) - ½ × 9.8 × (3)² = 88.2 - 44.1 = 44.1 m</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>(c) Position after 4 s:</strong><br>\r\n  <span class=\"math\">s = ut - ½ gt² = (29.4 × 4) - ½ × 9.8 × (4)² = 117.6 - 4.9 × 16 = 117.6 - 78.4 = 39.2 m</span>.<br>\r\n  (The ball has reached its peak at 3 s and is descending; at 4 s it is <strong>39.2 m above the ground</strong>).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a) Initial velocity u = 29.4 m s⁻¹</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b) Maximum height h = 44.1 m</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c) Height after 4 s = 39.2 m from ground</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_19\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_19')\">\r\n      <div class=\"q-num\">Exercise — Q19</div>\r\n      <div class=\"q-text\">In what direction does the buoyant force on an object immersed in a liquid act?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The buoyant force acts in the <strong>vertically upward direction</strong> (opposite to the downward force of gravity), passing through the centre of buoyancy (the centre of gravity of the displaced fluid).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Vertically upward direction</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_20\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_20')\">\r\n      <div class=\"q-num\">Exercise — Q20</div>\r\n      <div class=\"q-text\">Why does a block of plastic released under water come up to the surface of water?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison of Forces:</strong><br>\r\n  1. The density of plastic is lower than the density of water (<span class=\"math\">\rho_{plastic} &lt; \rho_{water}</span>).<br>\r\n  2. When fully submerged under water, the weight of the water displaced by the plastic block is greater than the actual gravitational weight of the block itself.<br>\r\n  3. Consequently, the upward buoyant force (upthrust) is greater than the downward gravitational force (<span class=\"math\">F_{buoyant} &gt; W</span>).<br>\r\n  4. This net upward unbalanced force accelerates the plastic block upward until it surfaces and floats with part of its volume out of the water.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Density of plastic is less than water density</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Upward buoyant force exceeds downward weight (F_B > W)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_21\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_21')\">\r\n      <div class=\"q-num\">Exercise — Q21</div>\r\n      <div class=\"q-text\">The volume of 50 g of a substance is 20 cm³. If the density of water is 1 g cm⁻³, will the substance float or sink?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Mass of substance (<span class=\"math\">m</span>) = <span class=\"math\">50 g</span><br>\r\n  • Volume (<span class=\"math\">V</span>) = <span class=\"math\">20 cm³</span><br>\r\n  • Density of water (<span class=\"math\">\rho_w</span>) = <span class=\"math\">1 g cm⁻³</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">Density of substance = Mass / Volume = 50 / 20 = 2.5 g cm⁻³</span>.<br>\r\n  Since <span class=\"math\">2.5 g cm⁻³ &gt; 1.0 g cm⁻³</span> (density of substance &gt; density of water), the downward gravitational pull exceeds the maximum buoyant force.\r\n</div>\r\n<p><strong>Conclusion:</strong> The substance will <strong>sink</strong> in water.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating density = 50/20 = 2.5 g cm⁻³</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparing 2.5 > 1.0 and concluding it will sink</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q9_ex_22\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_ex_22')\">\r\n      <div class=\"q-num\">Exercise — Q22</div>\r\n      <div class=\"q-text\">The volume of a 500 g sealed packet is 350 cm³. Will the packet float or sink in water if the density of water is 1 g cm⁻³? What will be the mass of the water displaced by this packet?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Mass (<span class=\"math\">m</span>) = <span class=\"math\">500 g</span>, Volume (<span class=\"math\">V</span>) = <span class=\"math\">350 cm³</span>, <span class=\"math\">\rho_w = 1 g cm⁻³</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 1: Determine Density of Packet:</strong><br>\r\n  <span class=\"math\">Density = Mass / Volume = 500 / 350 ≈ 1.428 g cm⁻³</span>.<br>\r\n  Since density (<span class=\"math\">1.43 g cm⁻³</span>) &gt; density of water (<span class=\"math\">1 g cm⁻³</span>), the packet will <strong>sink</strong> to the bottom.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Mass of Displaced Water:</strong><br>\r\n  Since the packet sinks completely, it displaces a volume of water equal to its own entire volume (<span class=\"math\">350 cm³</span>).<br>\r\n  <span class=\"math\">Mass of displaced water = Volume × Density of water = 350 cm³ × 1 g cm⁻³ = 350 g</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The packet will <strong>sink</strong>; the mass of displaced water is <strong>350 grams</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Density = 1.43 g/cm³ ⟹ packet sinks</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mass of water displaced = 350 g</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 9</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Lactometer & Hydrometer Applications:</strong> A dairy technician uses a lactometer to test the purity of milk samples. The instrument sinks to a certain depth in pure milk, but when tested in watered-down milk, it sinks much deeper.<br>(a) On which fundamental scientific principle does a lactometer operate?<br>(b) Why does the lactometer sink deeper in adulterated (watered-down) milk?<br>(c) State Archimedes' principle.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> It operates on <strong>Archimedes' Principle (and Principle of Flotation)</strong>.<br><strong>(b)</strong> Pure milk has a higher density (<span class='math'>~1.03 g cm⁻³</span>) than water (<span class='math'>1.00 g cm⁻³</span>). Adding water reduces the average density of milk. To displace a sufficient weight of liquid to balance its fixed weight, the hydrometer must submerge a larger volume, sinking deeper.<br><strong>(c)</strong> Archimedes' Principle states that when a body is fully or partially immersed in a fluid, it experiences an upward buoyant force equal to the weight of the fluid displaced by it.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> An iron needle sinks in water, but a gigantic ship made of thousands of tons of iron and steel floats easily on the ocean. Explain the scientific reason.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">An iron needle is compact and solid; its density (<span class='math'>~7.8 g cm⁻³</span>) is far greater than water, so its weight exceeds the buoyant force of the tiny volume displaced, causing it to sink. A ship, although built of heavy steel, is hollow and encloses enormous volumes of trapped air. This vast hollow shape yields a very large overall volume and a low average density (mass/volume) that is much lower than seawater. Hence, the buoyant force easily balances the total ship weight, allowing it to float.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(8)\">← Chapter 8</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\">Chapter 10 →</button>\r\n  </div>\r\n</section>","10":"<section class=\"chapter-section\" id=\"ch10\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">10</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 10: Work and Energy</h2>\r\n      <p>Scientific Concept of Work, Kinetic & Potential Energy, Law of Conservation of Energy & Commercial Units of Power — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 148)</div>\r\n\r\n  <div class=\"q-card\" id=\"q10_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_1')\">\r\n      <div class=\"q-num\">Page 148 — Q1</div>\r\n      <div class=\"q-text\">A force of 7 N acts on an object. The displacement is, say 8 m, in the direction of the force. Let us take it that the force acts on the object through the displacement. What is the work done in this case?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Force (<span class=\"math\">F</span>) = <span class=\"math\">7 N</span><br>\r\n  • Displacement (<span class=\"math\">s</span>) = <span class=\"math\">8 m</span> (in direction of force, <span class=\"math\">θ = 0°</span>)\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Formula & Calculation:</strong><br>\r\n  <span class=\"math\">Work done (W) = Force × Displacement = F × s</span><br>\r\n  <span class=\"math\">W = 7 N × 8 m = 56 N m = 56 J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The work done in this case is <strong>56 Joules (56 J)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula W = F × s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation: 7 × 8 = 56 J with proper SI unit</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 149)</div>\r\n\r\n  <div class=\"q-card\" id=\"q10_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_2')\">\r\n      <div class=\"q-num\">Page 149 — Q1</div>\r\n      <div class=\"q-text\">When do we say that work is done?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Two Essential Conditions for Scientific Work:</strong><br>\r\n  In science, work is said to be done when and only when the following two simultaneous conditions are met:\r\n  <ol>\r\n    <li>An <strong>external force must act</strong> on the object (<span class=\"math\">F ≠ 0</span>).</li>\r\n    <li>The object must be <strong>displaced</strong> from its initial position along a direction having a non-zero component along the line of action of the force (<span class=\"math\">s ≠ 0</span> and force is not perpendicular to displacement, <span class=\"math\">θ ≠ 90°</span>).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Condition 1: External force must act on the body</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Condition 2: Object must undergo displacement along direction with force component</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_3')\">\r\n      <div class=\"q-num\">Page 149 — Q2</div>\r\n      <div class=\"q-text\">Write an expression for the work done when a force is acting on an object in the direction of its displacement.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Expression:</strong><br>\r\n  When a constant force <span class=\"math\">F</span> acts in the exact direction of displacement <span class=\"math\">s</span> (<span class=\"math\">θ = 0°, \\cos 0° = 1</span>):<br>\r\n  <span class=\"math\">W = F × s</span><br>\r\n  (Work = Force × Displacement).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">W = F × s with definition of symbols</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_4')\">\r\n      <div class=\"q-num\">Page 149 — Q3</div>\r\n      <div class=\"q-text\">Define 1 J of work.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  <strong>1 Joule (1 J)</strong> of work is defined as the amount of work done when a force of <strong>1 Newton (1 N)</strong> displaces an object by a distance of <strong>1 metre (1 m)</strong> along the line of action of that force.<br>\r\n  <span class=\"math\">1 J = 1 N × 1 m = 1 N m</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Work done when 1 N force causes 1 m displacement in force's direction</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_5')\">\r\n      <div class=\"q-num\">Page 149 — Q4</div>\r\n      <div class=\"q-text\">A pair of bullocks exerts a force of 140 N on a plough. The field being ploughed is 15 m long. How much work is done in ploughing the length of the field?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Force (<span class=\"math\">F</span>) = <span class=\"math\">140 N</span><br>\r\n  • Displacement (<span class=\"math\">s</span>) = <span class=\"math\">15 m</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">W = F × s = 140 N × 15 m = 2100 J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The work done is <strong>2100 Joules (or 2.1 kJ)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula W = F × s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 2100 J</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 152)</div>\r\n\r\n  <div class=\"q-card\" id=\"q10_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_6')\">\r\n      <div class=\"q-num\">Page 152 — Q1</div>\r\n      <div class=\"q-text\">What is the kinetic energy of an object?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  The <strong>kinetic energy</strong> of an object is the energy possessed by the object by virtue of its <strong>motion</strong>.<br>\r\n  It represents the amount of work done on the object to accelerate it from a state of rest to its present velocity.<br>\r\n  <em>Examples:</em> A fast-moving bullet, rushing water turning a turbine, a blowing wind driving a wind turbine.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Energy possessed by an object due to its motion</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Equivalent to work done accelerating body from rest; valid example</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_7')\">\r\n      <div class=\"q-num\">Page 152 — Q2</div>\r\n      <div class=\"q-text\">Write an expression for the kinetic energy of an object.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Expression:</strong><br>\r\n  For an object of mass <span class=\"math\">m</span> moving with a velocity <span class=\"math\">v</span>:<br>\r\n  <span class=\"math\">E_k = ½ m v²</span><br>\r\n  Where <span class=\"math\">E_k</span> is Kinetic Energy in Joules (<span class=\"math\">J</span>), <span class=\"math\">m</span> is in <span class=\"math\">kg</span>, and <span class=\"math\">v</span> is in <span class=\"math\">m s⁻¹</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">E_k = ½ mv² with definitions of variables</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_8')\">\r\n      <div class=\"q-num\">Page 152 — Q3</div>\r\n      <div class=\"q-text\">The kinetic energy of an object of mass, m moving with a velocity of 5 m s⁻¹ is 25 J. What will be its kinetic energy when its velocity is doubled? What will be its kinetic energy when its velocity is increased three times?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Initial <span class=\"math\">E_k = ½ m (5)² = 25 J ⟹ 12.5 m = 25 ⟹ m = 2 kg</span>.<br>\r\n  Notice that <span class=\"math\">E_k ∝ v²</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>1. When velocity is doubled (<span class=\"math\">v' = 2v = 10 m s⁻¹</span>):</strong><br>\r\n  <span class=\"math\">E_k' = ½ m (2v)² = 4 × (½ m v²) = 4 × 25 J = 100 J</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>2. When velocity is increased three times (<span class=\"math\">v'' = 3v = 15 m s⁻¹</span>):</strong><br>\r\n  <span class=\"math\">E_k'' = ½ m (3v)² = 9 × (½ m v²) = 9 × 25 J = 225 J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Doubled velocity ⟹ <strong>100 J</strong>; Tripled velocity ⟹ <strong>225 J</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Recognizing E_k is proportional to v²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Velocity doubled ⟹ 4 × 25 = 100 J</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Velocity tripled ⟹ 9 × 25 = 225 J</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 156)</div>\r\n\r\n  <div class=\"q-card\" id=\"q10_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_9')\">\r\n      <div class=\"q-num\">Page 156 — Q1</div>\r\n      <div class=\"q-text\">What is power?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  <strong>Power</strong> is defined as the time rate of doing work or the rate at which energy is transferred or consumed.<br>\r\n  <span class=\"math\">Power (P) = Work done (W) / Time taken (t) = Energy consumed (E) / t</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Rate of doing work / rate of energy consumption</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_in_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_10')\">\r\n      <div class=\"q-num\">Page 156 — Q2</div>\r\n      <div class=\"q-text\">Define 1 watt of power.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  <strong>1 Watt (1 W)</strong> is the power of an agent which performs work at the rate of <strong>1 Joule per second (1 J s⁻¹)</strong>.<br>\r\n  <span class=\"math\">1 W = 1 J / 1 s = 1 J s⁻¹</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Power when 1 Joule of work is done in 1 second</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_in_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_11')\">\r\n      <div class=\"q-num\">Page 156 — Q3</div>\r\n      <div class=\"q-text\">A lamp consumes 1000 J of electrical energy in 10 s. What is its power?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Energy (<span class=\"math\">E</span>) = <span class=\"math\">1000 J</span>, Time (<span class=\"math\">t</span>) = <span class=\"math\">10 s</span>.<br><br>\r\n  <span class=\"math\">Power (P) = Energy / Time = 1000 J / 10 s = 100 W</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The power of the lamp is <strong>100 Watts (100 W)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula P = E / t</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 100 W</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_in_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_in_12')\">\r\n      <div class=\"q-num\">Page 156 — Q4</div>\r\n      <div class=\"q-text\">Define average power.</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  <strong>Average power</strong> is defined as the ratio of the <strong>total work done (or total energy consumed)</strong> to the <strong>total time taken</strong>:<br>\r\n  <span class=\"math\">Average Power = Total Work Done (or Total Energy Consumed) / Total Time Taken</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total energy consumed divided by total time taken</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q10_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">Look at the activities listed below. Reason out whether or not work is done in the light of your understanding of the term 'work':<br>• Suma is swimming in a pond.<br>• A donkey is carrying a load on its back.<br>• A wind-mill is lifting water from a well.<br>• A green plant is carrying out photosynthesis.<br>• An engine is pulling a train.<br>• Food grains are getting dried in the sun.<br>• A sailboat is moving due to wind energy.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Analysis of Work Done (<span class=\"math\">W = F s \\cos θ</span>):</strong>\r\n  <ul>\r\n    <li><strong>Suma is swimming:</strong> <strong>Work is done.</strong> Suma applies backward muscular force on the water, and the reaction force displaces her body forward (<span class=\"math\">F \\parallel s</span>).</li>\r\n    <li><strong>Donkey carrying a load:</strong> <strong>No work is done by gravity/vertical force.</strong> The load's weight acts vertically downward while displacement is horizontal (<span class=\"math\">θ = 90°, \\cos 90° = 0</span>).</li>\r\n    <li><strong>Wind-mill lifting water:</strong> <strong>Work is done.</strong> Wind-mill exerts upward pulling force on water, lifting it vertically through a height (<span class=\"math\">s &gt; 0</span> in direction of force).</li>\r\n    <li><strong>Plant carrying out photosynthesis:</strong> <strong>No mechanical work is done.</strong> Biochemical synthesis of glucose involves no macroscopic physical displacement (<span class=\"math\">s = 0</span>).</li>\r\n    <li><strong>Engine pulling a train:</strong> <strong>Work is done.</strong> Engine exerts a horizontal tractive force on the train, displacing it along the track.</li>\r\n    <li><strong>Food grains drying in sun:</strong> <strong>No work is done.</strong> Grains remain stationary on the ground (<span class=\"math\">s = 0</span>).</li>\r\n    <li><strong>Sailboat moving due to wind:</strong> <strong>Work is done.</strong> Wind exerts a pushing force on the sails, displacing the boat forward.</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Suma, Wind-mill, Engine, Sailboat: Work is done with valid physical reasons</span><span class=\"marking-marks\">3 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Donkey, Plant, Grains: No work done with angle/displacement reasons</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">An object thrown at a certain angle to the ground moves in a curved path and falls back to the ground. The initial and the final points of the path of the object lie on the same horizontal line. What is the work done by the force of gravity on the object?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis:</strong><br>\r\n  • Gravitational force acts strictly in the <strong>vertically downward direction</strong>: <span class=\"math\">F = mg</span>.<br>\r\n  • Work done by gravity depends solely on vertical displacement (<span class=\"math\">h</span>): <span class=\"math\">W = mg × h</span>.<br>\r\n  • Since both initial and final points lie on the exact same horizontal plane, the net vertical displacement is zero (<span class=\"math\">h = 0</span>).<br>\r\n  <span class=\"math\">W = mg × 0 = 0 J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The work done by the force of gravity on the object is <strong>Zero (0 J)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying vertical force of gravity and net vertical displacement = 0</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation W = mg × 0 = 0 J</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">A battery lights a bulb. Describe the energy changes involved in the process.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Sequence of Energy Transformations:</strong><br>\r\n  1. <strong>Chemical Energy:</strong> Inside the electrochemical battery, spontaneous redox reactions convert stored chemical energy into electrical energy.<br>\r\n  2. <strong>Electrical Energy:</strong> Electric current flows through the circuit conductors to the high-resistance tungsten filament of the bulb.<br>\r\n  3. <strong>Thermal (Heat) Energy:</strong> Current encounters electrical resistance in the filament, converting electrical energy into intense heat (Joule's heating effect).<br>\r\n  4. <strong>Light Energy:</strong> As the filament glows incandescently at ~2500°C, heat energy is radiated as visible light energy (and infrared radiation).<br><br>\r\n  <span class=\"math\">Chemical Energy ⟶ Electrical Energy ⟶ Heat Energy ⟶ Light Energy</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Battery: Chemical energy to Electrical energy</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Bulb: Electrical energy to Heat energy and Light energy</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">Certain force acting on a 20 kg mass changes its velocity from 5 m s⁻¹ to 2 m s⁻¹. Calculate the work done by the force.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Mass (<span class=\"math\">m</span>) = <span class=\"math\">20 kg</span>, <span class=\"math\">u = 5 m s⁻¹</span>, <span class=\"math\">v = 2 m s⁻¹</span>.<br><br>\r\n  <strong>By Work-Energy Theorem:</strong><br>\r\n  <span class=\"math\">Work done = Change in Kinetic Energy = ½ m v² - ½ m u²</span><br>\r\n  <span class=\"math\">W = ½ × 20 × (2² - 5²) = 10 × (4 - 25) = 10 × (-21) = -210 J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The work done is <strong>-210 Joules</strong> (the negative sign indicates a retarding/opposing braking force that extracts kinetic energy from the moving body).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Work-Energy Theorem formula: W = ½m(v² - u²)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution and calculation: 10 × (-21)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer = -210 J with physical meaning of negative work</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">A mass of 10 kg is at a point A on a table. It is moved to a point B. If the line joining A and B is horizontal, what is the work done on the object by the gravitational force? Explain your answer.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis:</strong><br>\r\n  1. The force of gravity on the 10 kg mass acts vertically downward toward Earth's centre (<span class=\"math\">F = mg</span>).<br>\r\n  2. The displacement of the object from A to B is strictly horizontal along the tabletop.<br>\r\n  3. The angle between the downward gravitational force vector and the horizontal displacement vector is exactly <span class=\"math\">90°</span> (<span class=\"math\">θ = 90°</span>).<br>\r\n  4. <span class=\"math\">W = F \\cdot s \\cdot \\cos 90° = mg \\cdot s \\cdot 0 = 0 J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The work done by gravitational force is <strong>Zero (0 J)</strong> because force and displacement are perpendicular to each other.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Angle between gravity and horizontal displacement is 90°</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">W = Fs cos 90° = 0 J with explanation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">The potential energy of a freely falling object decreases progressively. Does this violate the law of conservation of energy? Why?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: No, it does NOT violate the law of conservation of energy.</strong><br><br>\r\n  <strong>Explanation:</strong><br>\r\n  • As an object falls freely from height <span class=\"math\">h</span>, its height decreases, causing its gravitational potential energy (<span class=\"math\">E_p = mgh</span>) to decrease progressively.<br>\r\n  • However, as it accelerates downward under gravity, its velocity increases uniformly, causing a corresponding <strong>equal increase in its kinetic energy</strong> (<span class=\"math\">E_k = ½ mv²</span>).<br>\r\n  • The loss in potential energy at any point along the descent is exactly equal to the gain in kinetic energy (<span class=\"math\">ΔE_p = ΔE_k</span>).<br>\r\n  • The total mechanical energy (<span class=\"math\">E = E_p + E_k = constant</span>) remains strictly conserved throughout the motion.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Negative response (No violation)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Decrease in PE equals increase in KE at every point</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total mechanical energy remains constant</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">What are the various energy transformations that occur when you are riding a bicycle?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Sequence of Energy Transformations:</strong><br>\r\n  1. <strong>Muscular (Chemical) Energy:</strong> The rider's muscles metabolize food glucose, releasing chemical energy that produces muscular force on the pedals.<br>\r\n  2. <strong>Kinetic (Mechanical) Energy of Mechanism:</strong> Muscular energy is converted into kinetic energy of the rotating pedals, gears, and chain drive, propelling the bicycle wheels forward.<br>\r\n  3. <strong>Kinetic Energy of Bicycle and Rider:</strong> The entire system gains translational kinetic energy of forward motion.<br>\r\n  4. <strong>Heat and Sound Dissipation:</strong> A fraction of mechanical energy is continuously dissipated as heat due to road friction and air resistance, and sound from the rolling chain and tires.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Chemical energy of food/muscles to mechanical/kinetic energy of bicycle</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Dissipation as heat and sound due to friction</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">Does the transfer of energy take place when you push a huge rock with all your might and fail to move it? Where is the energy you spend going?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Analysis:</strong><br>\r\n  • <strong>Work done on the rock:</strong> Since displacement of the rock is zero (<span class=\"math\">s = 0</span>), the mechanical work done on the rock is strictly zero (<span class=\"math\">W = F × 0 = 0</span>). No mechanical energy is transferred to the rock.<br><br>\r\n  • <strong>Where does the spent metabolic energy go?</strong><br>\r\n    - When you push with all your might, your skeletal muscles contract isometrically against an immovable resistance.<br>\r\n    - Blood circulation increases, muscular fibers contract and stretch internally, and biochemical ATP is consumed rapidly.<br>\r\n    - The entire metabolic energy expended is converted into <strong>internal thermal (heat) energy</strong> within your muscle tissues, causing your body temperature to rise, sweat to evaporate, and fatigue to set in.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">No mechanical energy transferred to rock because displacement is zero</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Expended metabolic energy converted to heat energy inside muscle tissues</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">A certain household has consumed 250 units of energy during a month. How much energy is this in joules?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Conversion:</strong><br>\r\n  • 1 commercial unit of electrical energy = <span class=\"math\">1 kWh (Kilowatt-hour)</span><br>\r\n  • <span class=\"math\">1 kWh = 1000 W × 3600 s = 3.6 × 10⁶ J</span><br><br>\r\n  <span class=\"math\">Total Energy = 250 units = 250 × (3.6 × 10⁶ J) = 900 × 10⁶ J = 9 × 10⁸ J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The energy consumed is <strong>9 × 10⁸ Joules</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">1 unit = 1 kWh = 3.6 × 10⁶ J</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">250 × 3.6 × 10⁶ = 9 × 10⁸ J</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">An object of mass 40 kg is raised to a height of 5 m above the ground. What is its potential energy? If the object is allowed to fall, find its kinetic energy when it is half-way down. (Take g = 9.8 m s⁻² or 10 m s⁻²).</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> <span class=\"math\">m = 40 kg</span>, <span class=\"math\">h = 5 m</span>, <span class=\"math\">g = 9.8 m s⁻²</span> (or 10 m s⁻²).<br><br>\r\n  <strong>Step 1: Potential Energy at Top:</strong><br>\r\n  <span class=\"math\">E_p = mgh = 40 × 9.8 × 5 = 1960 J</span> (or <span class=\"math\">2000 J</span> taking <span class=\"math\">g = 10</span>).\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Kinetic Energy Half-Way Down (at h = 2.5 m):</strong><br>\r\n  By the <strong>Law of Conservation of Energy</strong>:<br>\r\n  • At half-way down, half of the initial potential energy is converted into kinetic energy.<br>\r\n  <span class=\"math\">E_k = ½ × Total Initial Energy = ½ × 1960 J = 980 J</span> (or <span class=\"math\">1000 J</span> taking <span class=\"math\">g = 10</span>).\r\n</div>\r\n<p><strong>Final Answer:</strong> Potential energy = <strong>1960 J</strong>, Kinetic energy half-way down = <strong>980 J</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating initial PE = mgh = 1960 J (2000 J)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying conservation to find half-way KE = 980 J (1000 J)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_11')\">\r\n      <div class=\"q-num\">Exercise — Q11</div>\r\n      <div class=\"q-text\">What is the work done by the force of gravity on a satellite moving round the earth? Justify your answer.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: The work done by gravity is ZERO (0 J).</strong><br><br>\r\n  <strong>Justification:</strong><br>\r\n  • The Earth's gravitational pull provides the necessary centripetal force directed radially inward toward the Earth's centre.<br>\r\n  • The instantaneous displacement of the satellite at every point along its circular orbit is directed tangentially to the orbit.<br>\r\n  • The angle between the radial gravitational force and tangential displacement is strictly <strong>90°</strong> (<span class=\"math\">θ = 90°</span>).<br>\r\n  • <span class=\"math\">W = F \\cdot s \\cdot \\cos 90° = 0 J</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating work done is zero</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Justifying force is perpendicular to instantaneous displacement (θ = 90°)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_12')\">\r\n      <div class=\"q-num\">Exercise — Q12</div>\r\n      <div class=\"q-text\">Can there be displacement of an object in the absence of any force acting on it? Think. Discuss this question with your friends and teacher.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: Yes, an object can undergo displacement even in the total absence of any net external force.</strong><br><br>\r\n  <strong>Reasoning based on Newton's First Law:</strong><br>\r\n  • According to Newton's First Law of Motion, if an object is already moving with a constant velocity <span class=\"math\">v</span> and the net external force is zero (<span class=\"math\">F_{net} = 0</span>), its acceleration is zero (<span class=\"math\">a = 0</span>).<br>\r\n  • The object will continue to move uniformly in a straight line forever, continuously covering non-zero displacement (<span class=\"math\">s = v \times t ≠ 0</span>).<br>\r\n  • A force is required only to initiate motion or change velocity, not to sustain existing uniform motion (e.g. a space probe drifting through deep interstellar space).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative answer (Yes) based on Newton's First Law</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that uniform velocity produces continuous displacement with F = 0</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_13')\">\r\n      <div class=\"q-num\">Exercise — Q13</div>\r\n      <div class=\"q-text\">A person holds a bundle of hay over his head for 30 minutes and gets tired. Has he done some work or not? Justify your answer.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Answer: In the language of physics, the person has done ZERO work (<span class=\"math\">W = 0</span>).</strong><br><br>\r\n  <strong>Justification:</strong><br>\r\n  • While holding the bundle of hay stationary over his head, the position of the bundle does not change at all (<span class=\"math\">Displacement s = 0</span>).<br>\r\n  • Since scientific work is given by <span class=\"math\">W = Force × Displacement</span>, when <span class=\"math\">s = 0</span>, <span class=\"math\">W = F × 0 = 0</span>.<br>\r\n  • The person gets tired because his muscular fibers consume chemical energy internally through isometric muscle contraction to support the weight against gravity, but zero mechanical work is done on the bundle.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Work done is zero because displacement of bundle is zero</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining fatigue as internal isometric muscle contraction</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_14')\">\r\n      <div class=\"q-num\">Exercise — Q14</div>\r\n      <div class=\"q-text\">An electric heater is rated 1500 W. How much energy does it use in 10 hours?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Power (<span class=\"math\">P</span>) = <span class=\"math\">1500 W = 1.5 kW</span>, Time (<span class=\"math\">t</span>) = <span class=\"math\">10 hours</span>.<br><br>\r\n  • <strong>In Commercial Units (kWh):</strong><br>\r\n    <span class=\"math\">Energy = Power × Time = 1.5 kW × 10 h = 15 kWh</span> (or <strong>15 units</strong>).<br><br>\r\n  • <strong>In SI Units (Joules):</strong><br>\r\n    <span class=\"math\">Energy = 15 × 3.6 × 10⁶ J = 5.4 × 10⁷ J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Energy used is <strong>15 kWh (or 5.4 × 10⁷ J)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Energy in kWh = 1.5 × 10 = 15 kWh (15 units)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Energy in Joules = 5.4 × 10⁷ J</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_15')\">\r\n      <div class=\"q-num\">Exercise — Q15</div>\r\n      <div class=\"q-text\">Illustrate the law of conservation of energy by discussing the energy changes which occur when we draw a pendulum bob to one side and allow it to oscillate. Why does the bob eventually come to rest? What happens to its energy eventually? Is it a violation of the law of conservation of energy?</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Oscillations of Simple Pendulum:</strong>\r\n  <ol>\r\n    <li><strong>At Extreme Positions (A and B):</strong> When displaced to one side, the bob is raised through a vertical height <span class=\"math\">h</span>. Its velocity is zero (<span class=\"math\">v = 0</span>). The energy is 100% <strong>Potential Energy (<span class=\"math\">mgh</span>)</strong>.</li>\r\n    <li><strong>At Mean Position (O):</strong> As it swings down, PE converts into <strong>Kinetic Energy</strong>. At lowest point O, <span class=\"math\">h = 0</span>, speed is maximum, and energy is 100% <strong>Kinetic Energy (<span class=\"math\">½ mv²</span>)</strong>.</li>\r\n    <li><strong>Continuous Exchange:</strong> PE and KE continuously interchange, keeping total mechanical energy constant (<span class=\"math\">PE + KE = constant</span>).</li>\r\n  </ol>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Why the Bob Eventually Stops & Conservation:</strong><br>\r\n  • The bob encounters continuous air resistance and friction at the suspension pivot.<br>\r\n  • Mechanical energy is gradually transformed into <strong>heat energy of air and suspension string, and sound energy</strong>.<br>\r\n  • Once all mechanical energy is dissipated into the environment as heat and sound, the bob stops.<br>\r\n  • <strong>No, this is NOT a violation</strong> of the law of conservation of energy; total energy of the universe (mechanical + heat + sound) remains strictly conserved.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Energy interconversions between PE and KE at extreme and mean positions</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining air resistance and friction dissipating energy as heat and sound</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Confirming NO violation of conservation of energy</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_16')\">\r\n      <div class=\"q-num\">Exercise — Q16</div>\r\n      <div class=\"q-text\">An object of mass, m is moving with a constant velocity, v. How much work should be done on the object in order to bring the object to rest?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Work-Energy Theorem:</strong><br>\r\n  <span class=\"math\">Work Done = Final Kinetic Energy - Initial Kinetic Energy</span><br>\r\n  • Initial kinetic energy (<span class=\"math\">E_{ki}</span>) = <span class=\"math\">½ m v²</span><br>\r\n  • Final kinetic energy (<span class=\"math\">E_{kf}</span>) = <span class=\"math\">0</span> (object comes to rest)<br><br>\r\n  <span class=\"math\">W = 0 - ½ m v² = - ½ m v²</span>.\r\n</div>\r\n<p><strong>Conclusion:</strong> The amount of work that must be done is <strong>- ½ m v²</strong> (a retarding work of magnitude <strong>½ m v²</strong>).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying Work-Energy theorem W = ΔK</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Work done = - ½ mv² (magnitude ½ mv²)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_17\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_17')\">\r\n      <div class=\"q-num\">Exercise — Q17</div>\r\n      <div class=\"q-text\">Calculate the work required to be done to stop a car of 1500 kg moving at a velocity of 60 km/h?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Mass (<span class=\"math\">m</span>) = <span class=\"math\">1500 kg</span><br>\r\n  • Velocity (<span class=\"math\">v</span>) = <span class=\"math\">60 km h⁻¹ = 60 × (5/18) = 50 / 3 m s⁻¹ ≈ 16.67 m s⁻¹</span><br>\r\n  • Final velocity (<span class=\"math\">v_f</span>) = <span class=\"math\">0</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">W = 0 - ½ m v² = - ½ × 1500 × (50 / 3)²</span><br>\r\n  <span class=\"math\">W = - 750 × (2500 / 9) = - 1875000 / 9 ≈ - 208,333.33 J ≈ - 2.08 × 10⁵ J</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The work required to be done is <strong>- 2.08 × 10⁵ Joules (or 208.33 kJ)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion of 60 km/h = 50/3 m/s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying W = - ½ mv²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final calculation = - 2.08 × 10⁵ J (-208.33 kJ)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_18\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_18')\">\r\n      <div class=\"q-num\">Exercise — Q18</div>\r\n      <div class=\"q-text\">In each of the following a force, F is acting on an object of mass, m. The direction of displacement is from west to east. Case 1: Force acting towards north (perpendicular). Case 2: Force acting towards east (parallel). Case 3: Force acting towards west (antiparallel). Determine the sign of work done in each case.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Work Formula: <span class=\"math\">W = F \\cdot s \\cdot \\cos θ</span></strong>\r\n  <ul>\r\n    <li><strong>Case 1 (Force perpendicular to displacement, <span class=\"math\">θ = 90°</span>):</strong><br>\r\n      <span class=\"math\">W = F s \\cos 90° = 0</span>. <strong>Work done is ZERO.</strong></li>\r\n    <li><strong>Case 2 (Force in same direction as displacement, <span class=\"math\">θ = 0°</span>):</strong><br>\r\n      <span class=\"math\">W = F s \\cos 0° = + F s</span>. <strong>Work done is POSITIVE.</strong></li>\r\n    <li><strong>Case 3 (Force opposite to displacement, <span class=\"math\">θ = 180°</span>):</strong><br>\r\n      <span class=\"math\">W = F s \\cos 180° = - F s</span>. <strong>Work done is NEGATIVE.</strong></li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Case 1: Zero work (θ = 90°)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Case 2: Positive work (θ = 0°)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Case 3: Negative work (θ = 180°)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_19\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_19')\">\r\n      <div class=\"q-num\">Exercise — Q19</div>\r\n      <div class=\"q-text\">Soni says that the acceleration in an object could be zero even when several forces are acting on it. Do you agree with her? Why?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: Yes, we completely agree with Soni.</strong><br><br>\r\n  <strong>Explanation:</strong><br>\r\n  • By Newton's Second Law, acceleration is proportional to the <strong>net resultant unbalanced force</strong>: <span class=\"math\">a = F_{net} / m</span>.<br>\r\n  • If several individual forces act simultaneously on an object such that their vector sum is zero (<span class=\"math\">F_{net} = \\sum \u000bec{F} = 0</span>), the forces are called <strong>balanced forces</strong>.<br>\r\n  • Under balanced forces, <span class=\"math\">F_{net} = 0 ⟹ a = 0</span>. The object will experience zero acceleration.<br>\r\n  <em>Example:</em> A book resting on a table experiences downward gravitational force and upward normal contact reaction; the two forces cancel out, and acceleration is zero.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Agreement with Soni (Yes)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that vector sum of balanced forces is zero (F_net = 0 ⟹ a = 0)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Valid everyday example (e.g. book on table, tug of war tie)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_20\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_20')\">\r\n      <div class=\"q-num\">Exercise — Q20</div>\r\n      <div class=\"q-text\">Find the energy in kWh consumed in 10 hours by four devices of power 500 W each.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong><br>\r\n  • Number of devices = 4, Power of each device = <span class=\"math\">500 W</span><br>\r\n  • Total Power (<span class=\"math\">P</span>) = <span class=\"math\">4 × 500 W = 2000 W = 2 kW</span><br>\r\n  • Time (<span class=\"math\">t</span>) = <span class=\"math\">10 hours</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">Energy (E) = Total Power × Time = 2 kW × 10 h = 20 kWh</span> (or <strong>20 commercial units</strong>).\r\n</div>\r\n<p><strong>Final Answer:</strong> The energy consumed is <strong>20 kWh</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total power = 4 × 500 W = 2 kW</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Energy = 2 kW × 10 h = 20 kWh</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q10_ex_21\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_ex_21')\">\r\n      <div class=\"q-num\">Exercise — Q21</div>\r\n      <div class=\"q-text\">A freely falling object eventually stops on reaching the ground. What happens to its kinetic energy?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Dissipation of Kinetic Energy:</strong><br>\r\n  When a freely falling object hits the ground and comes to an abrupt halt, its kinetic energy does not vanish; it is transformed into other non-mechanical forms of energy in accordance with the Law of Conservation of Energy:\r\n  <ol>\r\n    <li><strong>Heat Energy:</strong> The kinetic energy is converted into thermal energy, raising the temperature of both the object and the ground at the impact zone.</li>\r\n    <li><strong>Sound Energy:</strong> A fraction is converted into acoustic waves (the thud/crash sound heard upon impact).</li>\r\n    <li><strong>Mechanical Strain / Deformation:</strong> A portion goes into doing work to deform, crack, or fracture the object or create an indentation/crater in the ground.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating kinetic energy is conserved by conversion into other energy forms</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explicitly listing Heat, Sound, and Deformation energy</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 10</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Hydroelectric Power Generation:</strong> Water stored in a reservoir behind a dam at a height of 80 m is allowed to fall through penstocks to turn turbines connected to electric generators. Every second, 2000 kg of water flows through.<br>(a) What form of energy does the stored water possess?<br>(b) Calculate the maximum potential energy available per second (take g = 10 m s⁻²).<br>(c) What is the theoretical electrical power output?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> Gravitational Potential Energy (<span class='math'>E_p = mgh</span>).<br><strong>(b)</strong> Energy per second = <span class='math'>mgh = 2000 × 10 × 80 = 1,600,000 J = 1.6 × 10⁶ J</span>.<br><strong>(c)</strong> Power = Energy / Time = <span class='math'>1.6 × 10⁶ J / 1 s = 1.6 × 10⁶ W = 1.6 MW (1600 kW)</span>.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> A light body A and a heavy body B have the exact same kinetic energy. Which one has greater linear momentum?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">Linear momentum is related to kinetic energy by <span class='math'>p = √(2m E_k)</span>. Since kinetic energy <span class='math'>E_k</span> is the same for both bodies, momentum is directly proportional to the square root of mass: <span class='math'>p ∝ √m</span>. Because body B has a heavier mass (<span class='math'>m_B &gt; m_A</span>), the <strong>heavy body B has a greater momentum</strong>.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(9)\">← Chapter 9</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\">Chapter 11 →</button>\r\n  </div>\r\n</section>","11":"<section class=\"chapter-section\" id=\"ch11\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">11</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 11: Sound</h2>\r\n      <p>Production & Propagation of Sound, Longitudinal Waves, Speed, Echo, Reverberation, Ultrasound & Anatomy of the Human Ear — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 162)</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_1')\">\r\n      <div class=\"q-num\">Page 162 — Q1</div>\r\n      <div class=\"q-text\">How does the sound produced by a vibrating object in a medium reach your ear?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Propagation of Sound through Medium Particles:</strong><br>\r\n  1. When an object vibrates (such as a tuning fork prong or vocal cord), it exerts a periodic push on the air molecules in its immediate vicinity.<br>\r\n  2. As the vibrating surface moves forward, it compresses and pushes the adjacent air particles forward, creating a localized high-pressure, high-density region called a <strong>Compression (C)</strong>.<br>\r\n  3. When the surface moves backward, it creates a localized low-pressure, low-density region called a <strong>Rarefaction (R)</strong>.<br>\r\n  4. Individual air particles do not travel all the way from the source to our ear; instead, they oscillate back and forth about their equilibrium mean positions, transferring momentum and energy to neighboring particles.<br>\r\n  5. This disturbance travels forward as an acoustic pressure wave and impinges on the tympanic membrane (eardrum) of our ear, making it vibrate and producing the sensation of hearing.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formation of Compressions (high density) and Rarefactions (low density)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Particles oscillate about mean position without net translation, transferring energy</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 163)</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_2')\">\r\n      <div class=\"q-num\">Page 163 — Q1</div>\r\n      <div class=\"q-text\">Explain how sound is produced by your school bell.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Mechanism:</strong><br>\r\n  1. When the school bell is struck with a hammer, mechanical kinetic energy is transferred to the bell body, causing the metallic gong to vibrate rapidly back and forth.<br>\r\n  2. These high-frequency vibrations displace the surrounding air molecules back and forth, generating alternating series of compressions and rarefactions that propagate outwards through the air as longitudinal sound waves.<br>\r\n  3. Touching the bell reveals distinct tactile vibrations, which stop immediately when the bell is damped with a hand, proving that <strong>vibration is the root source of sound</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Hammer strike sets metallic bell body into rapid vibrations</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Vibrations compress and expand surrounding air, producing acoustic waves</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_3')\">\r\n      <div class=\"q-num\">Page 163 — Q2</div>\r\n      <div class=\"q-text\">Why are sound waves called mechanical waves?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition of Mechanical Waves:</strong><br>\r\n  Sound waves are termed <strong>mechanical waves</strong> (or elastic waves) because:\r\n  <ol>\r\n    <li>They are produced by the physical mechanical oscillation of particles of matter.</li>\r\n    <li>They strictly require a <strong>material medium (solid, liquid, or gas)</strong> with inertial and elastic properties for their propagation.</li>\r\n    <li>They <strong>cannot propagate through a vacuum</strong>, unlike electromagnetic waves (such as light or radio waves) which can travel through empty space.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Require material medium possessing inertia and elasticity for propagation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Inability to travel through a vacuum</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_4')\">\r\n      <div class=\"q-num\">Page 163 — Q3</div>\r\n      <div class=\"q-text\">Suppose you and your friend are on the moon. Will you be able to hear any sound produced by your friend?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: No, you will NOT be able to hear any sound produced by your friend directly.</strong><br><br>\r\n  <strong>Scientific Explanation:</strong><br>\r\n  1. The Moon has no atmosphere; it is surrounded by a virtually complete <strong>vacuum</strong>.<br>\r\n  2. Sound waves are mechanical longitudinal waves that require a material medium (air particles) to transmit compressions and rarefactions.<br>\r\n  3. In the absence of an atmosphere, there are no particles to propagate sound vibrations from your friend's vocal cords to your ears.<br>\r\n  4. (Astronauts on the lunar surface communicate using wireless radio transmitters, as electromagnetic radio waves propagate freely through vacuum).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Negative answer (No direct sound can be heard)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Moon lacks atmosphere (vacuum); mechanical sound waves cannot propagate in vacuum</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 166)</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_5')\">\r\n      <div class=\"q-num\">Page 166 — Q1</div>\r\n      <div class=\"q-text\">Which wave property determines (a) loudness, (b) pitch?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Wave Properties:</strong><br>\r\n  • <strong>(a) Loudness:</strong> Determined by the <strong>amplitude</strong> of the sound wave. Loudness is directly proportional to the square of the amplitude (<span class=\"math\">Loudness ∝ Amplitude²</span>). A larger amplitude corresponds to louder sound.<br><br>\r\n  • <strong>(b) Pitch:</strong> Determined by the <strong>frequency</strong> of the sound wave (<span class=\"math\">\r\nu</span> or <span class=\"math\">f</span>). Higher frequency corresponds to a higher pitch (shrill sound), while lower frequency produces a lower pitch (grave/deep sound).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Loudness is determined by Amplitude (L ∝ A²)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Pitch is determined by Frequency</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_6')\">\r\n      <div class=\"q-num\">Page 166 — Q2</div>\r\n      <div class=\"q-text\">Guess which sound has a higher pitch: guitar or car horn?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: The sound of a GUITAR has a higher pitch.</strong><br><br>\r\n  <em>Reason:</em> A vibrating guitar string vibrates at a much higher frequency (more cycles per second) producing a sharper, shriller acoustic tone. A car horn produces a low-frequency, high-amplitude, blaring sound with a lower pitch but higher loudness.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Guitar has higher pitch due to higher vibration frequency</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 167)</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_7')\">\r\n      <div class=\"q-num\">Page 167 — Q1</div>\r\n      <div class=\"q-text\">What are wavelength, frequency, time period and amplitude of a sound wave?</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Fundamental Wave Parameters:</strong>\r\n  <ol>\r\n    <li><strong>Wavelength (<span class=\"math\">λ</span>):</strong> The linear distance between two consecutive compressions or two consecutive rarefactions of a sound wave. SI unit: <strong>metre (m)</strong>.</li>\r\n    <li><strong>Frequency (<span class=\"math\">\r\nu</span>):</strong> The number of complete wave oscillations or cycles passing through a given point per second. SI unit: <strong>Hertz (Hz = s⁻¹)</strong>.</li>\r\n    <li><strong>Time Period (<span class=\"math\">T</span>):</strong> The time taken by the wave to complete one full oscillation or cycle. <span class=\"math\">T = 1 / \r\nu</span>. SI unit: <strong>second (s)</strong>.</li>\r\n    <li><strong>Amplitude (<span class=\"math\">A</span>):</strong> The magnitude of maximum displacement or disturbance of the medium particles from their mean equilibrium position. SI unit: <strong>metre (m)</strong> (or Pascal for density/pressure waves).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Wavelength: Distance between consecutive compressions/rarefactions (m)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Frequency: Number of oscillations per second (Hz)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Time Period: Time for one complete cycle (T = 1/ν, s)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Amplitude: Maximum displacement from equilibrium (m)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_8')\">\r\n      <div class=\"q-num\">Page 167 — Q2</div>\r\n      <div class=\"q-text\">How are the wavelength and frequency of a sound wave related to its speed?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Derivation of Wave Equation:</strong><br>\r\n  • By definition, <span class=\"math\">Speed = Distance / Time</span>.<br>\r\n  • In time period <span class=\"math\">T</span>, the wave travels a distance equal to its wavelength (<span class=\"math\">λ</span>).<br>\r\n  <span class=\"math\">Speed (v) = λ / T</span>.<br>\r\n  • Since frequency is the reciprocal of time period (<span class=\"math\">\r\nu = 1 / T</span>):<br>\r\n  <span class=\"math\">v = \r\nu × λ</span><br>\r\n  (Speed of sound = Frequency × Wavelength).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Derivation v = λ / T</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final relationship: Speed = Frequency × Wavelength (v = νλ)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_9')\">\r\n      <div class=\"q-num\">Page 167 — Q3</div>\r\n      <div class=\"q-text\">Calculate the wavelength of a sound wave whose frequency is 220 Hz and speed is 440 m/s in a given medium.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Frequency (<span class=\"math\">\r\nu</span>) = <span class=\"math\">220 Hz</span>, Speed (<span class=\"math\">v</span>) = <span class=\"math\">440 m s⁻¹</span>.<br><br>\r\n  <strong>Formula & Calculation:</strong><br>\r\n  <span class=\"math\">v = \r\nu × λ ⟹ λ = v / \r\nu</span><br>\r\n  <span class=\"math\">λ = 440 / 220 = 2 m</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The wavelength is <strong>2 metres</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula λ = v / ν</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 2 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_10')\">\r\n      <div class=\"q-num\">Page 167 — Q4</div>\r\n      <div class=\"q-text\">A person is listening to a tone of 500 Hz sitting at a distance of 450 m from the source of the sound. What is the time interval between successive compressions from the source?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Concept:</strong><br>\r\n  • The time interval between two successive compressions passing any point is precisely equal to the <strong>Time Period (<span class=\"math\">T</span>)</strong> of the sound wave.<br>\r\n  • (The distance of 450 m is extraneous information).<br><br>\r\n  <strong>Formula & Calculation:</strong><br>\r\n  <span class=\"math\">T = 1 / \r\nu = 1 / 500 = 0.002 s = 2 × 10⁻³ s</span> (or 2 milliseconds).\r\n</div>\r\n<p><strong>Final Answer:</strong> The time interval between successive compressions is <strong>0.002 seconds (2 ms)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Time interval equals Time Period T = 1/ν</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation T = 1/500 = 0.002 s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 170)</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_in_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_11')\">\r\n      <div class=\"q-num\">Page 170 — Q1</div>\r\n      <div class=\"q-text\">Distinguish between loudness and intensity of sound.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison: Loudness vs Intensity:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Loudness</th><th>Intensity</th></tr>\r\n    <tr><td><strong>Nature</strong></td><td><strong>Subjective sensory quantity</strong> (a physiological response depending on ear sensitivity).</td><td><strong>Objective physical quantity</strong> (measurable and independent of the listener).</td></tr>\r\n    <tr><td><strong>Definition</strong></td><td>Auditory sensation of sound strength perceived by the human ear.</td><td>Amount of sound energy passing per unit area per unit time perpendicular to the direction of wave propagation (<span class=\"math\">I = E / (A \\cdot t)</span>).</td></tr>\r\n    <tr><td><strong>Unit</strong></td><td>Measured in <strong>Decibels (dB)</strong> or Phon.</td><td>Measured in <strong>Watts per square metre (W m⁻²)</strong>.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Subjective ear response vs objective physical energy measurement</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definitions and units (dB vs W/m²)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 172)</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_in_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_12')\">\r\n      <div class=\"q-num\">Page 172 — Q1</div>\r\n      <div class=\"q-text\">In which of the three media, air, water or iron, does sound travel the fastest at a particular temperature?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: Sound travels fastest in IRON.</strong><br><br>\r\n  <em>Scientific Reason:</em> The speed of sound depends on the elasticity and density of the medium (<span class=\"math\">v = √(E/ρ)</span>). Solids have an extremely high modulus of elasticity compared to liquids and gases, allowing elastic restoration forces to propagate mechanical stress waves much faster:<br>\r\n  <span class=\"math\">v_{iron} (approx 5950 m s⁻¹) &gt; v_{water} (approx 1500 m s⁻¹) &gt; v_{air} (approx 343 m s⁻¹)</span>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Iron (with explanation of solid elasticity)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_13')\">\r\n      <div class=\"q-num\">Page 172 — Q2</div>\r\n      <div class=\"q-text\">An echo is heard in 3 s. What is the distance of the reflecting surface from the source, given that the speed of sound is 342 m s⁻¹?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Total time for echo (<span class=\"math\">t</span>) = <span class=\"math\">3 s</span>, Speed (<span class=\"math\">v</span>) = <span class=\"math\">342 m s⁻¹</span>.<br><br>\r\n  <strong>Echo Formula:</strong><br>\r\n  The sound travels to the reflecting surface and back (<span class=\"math\">Total distance = 2d</span>):<br>\r\n  <span class=\"math\">2d = v × t ⟹ d = (v × t) / 2</span><br>\r\n  <span class=\"math\">d = (342 × 3) / 2 = 1026 / 2 = 513 m</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The reflecting surface is <strong>513 metres</strong> away.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Echo formula 2d = v × t</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation d = (342 × 3)/2 = 513 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_14')\">\r\n      <div class=\"q-num\">Page 172 — Q3</div>\r\n      <div class=\"q-text\">Why are the ceilings of concert halls curved?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Acoustic Design of Curved Ceilings:</strong><br>\r\n  1. The ceilings of concert halls, cinema halls, and auditoriums are deliberately designed with concave parabolic or curved geometry.<br>\r\n  2. By the <strong>laws of reflection of sound</strong>, sound waves radiating upward from the stage strike the curved ceiling and reflect uniformly downwards.<br>\r\n  3. This ensures that the reflected sound waves spread evenly across the entire audience in all corners of the auditorium, preventing dead acoustic zones and ensuring clear audibility without excessive echoes.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Reflection of sound waves downwards from curved surface</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Spreads sound uniformly to every corner of the hall</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_15')\">\r\n      <div class=\"q-num\">Page 172 — Q4</div>\r\n      <div class=\"q-text\">What is the audible range of the average human ear?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  The audible frequency range for an average normal human ear extends from approximately <strong>20 Hz to 20,000 Hz (20 Hz to 20 kHz)</strong>.<br>\r\n  • Frequencies below 20 Hz are termed <em>infrasonic</em>.<br>\r\n  • Frequencies above 20,000 Hz are termed <em>ultrasonic</em>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">20 Hz to 20,000 Hz (20 kHz)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_in_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_in_16')\">\r\n      <div class=\"q-num\">Page 172 — Q5</div>\r\n      <div class=\"q-text\">Which type of sound waves does a bat use to detect prey?</div>\r\n      <div class=\"q-marks\">1 Mark</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer:</strong><br>\r\n  Bats emit high-frequency <strong>ultrasonic sound waves (ultrasound)</strong> with frequencies well above 20 kHz (often up to 100 kHz) for echolocation.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Ultrasonic waves / Ultrasound</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">What is sound and how is it produced?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition & Production of Sound:</strong><br>\r\n  • <strong>What is Sound:</strong> Sound is a form of mechanical energy that stimulates our auditory nerve and produces the physiological sensation of hearing.<br>\r\n  • <strong>How it is Produced:</strong> Sound is produced whenever an object is set into rapid mechanical <strong>vibration</strong> (rapid back-and-forth periodic motion).<br>\r\n  <em>Examples:</em> Plucking a sitar string, striking a drum membrane, air blowing through a flute, or vibrating vocal cords in the larynx.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of sound as form of energy producing hearing sensation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Produced by vibrating bodies with everyday examples</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">Describe with the help of a diagram, how compressions and rarefactions are produced in air near a source of sound.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Mechanism of Compressions and Rarefactions:</strong><br>\r\n  Consider a vibrating tuning fork prong in air:\r\n  <ol>\r\n    <li><strong>Forward Stroke (Compression):</strong> When the prong moves rapidly forward, it compresses the air directly in front of it. A localized zone of high particle density and high pressure is created, called a <strong>Compression (C)</strong>.</li>\r\n    <li><strong>Backward Stroke (Rarefaction):</strong> When the prong moves rapidly backward, a localized partial vacuum/decompression is created where particles spread apart, forming a zone of low particle density and low pressure called a <strong>Rarefaction (R)</strong>.</li>\r\n    <li>As the prong continues vibrating, a continuous periodic succession of compressions and rarefactions travels through the air as a longitudinal acoustic wave.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of Compression (high density/pressure zone)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of Rarefaction (low density/pressure zone)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">Cite an experiment to show that sound needs a material medium for its propagation.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>The Electric Bell Jar Experiment:</strong>\r\n  <ol>\r\n    <li><strong>Experimental Setup:</strong> Suspend an electric bell inside an airtight glass bell jar connected to a vacuum suction pump via a bottom stopcock. Connect the bell to an external battery through a switch.</li>\r\n    <li><strong>Initial Observation:</strong> Press the switch. With air inside the bell jar, the ringing sound of the electric bell is clearly and loudly heard outside.</li>\r\n    <li><strong>Pumping Out Air:</strong> Turn on the vacuum pump to evacuate air gradually from the jar. As air is pumped out, the sound of the bell becomes increasingly faint, even though the hammer can still be seen striking the gong vigorously.</li>\r\n    <li><strong>Complete Vacuum:</strong> When all the air is pumped out (creating a complete vacuum), absolutely <strong>no sound is heard</strong>.</li>\r\n    <li><strong>Conclusion:</strong> This conclusively proves that <strong>sound cannot propagate in a vacuum</strong> and strictly requires a material medium.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Setup of electric bell inside airtight glass jar with vacuum pump</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Observation of sound becoming faint as air is evacuated</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Silence at vacuum proving material medium is mandatory</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">Why is sound wave called a longitudinal wave?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition of Longitudinal Wave:</strong><br>\r\n  A wave is called a <strong>longitudinal wave</strong> when the constituent particles of the medium oscillate back and forth <strong>parallel to the direction of propagation of the wave</strong>.<br><br>\r\n  In a sound wave propagating horizontally through air, the air molecules oscillate along the same horizontal axis as the wave propagation, creating alternating regions of high and low pressure. Hence, sound in gases and liquids is strictly a longitudinal mechanical wave.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: Particles oscillate parallel to direction of wave propagation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Air molecules oscillate in same line as sound energy travel</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">Which characteristic of the sound helps you to identify your friend by his voice while sitting with others in a dark room?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: Quality (or Timbre) of Sound.</strong><br><br>\r\n  <strong>Explanation:</strong><br>\r\n  • Even if different voices have the exact same pitch (frequency) and loudness (amplitude), they can be distinguished by their <strong>quality or timbre</strong>.<br>\r\n  • The quality of sound is determined by its <strong>waveform</strong> and the specific blend of fundamental frequency and relative harmonics (overtones) produced by the unique anatomy of an individual's vocal cords, larynx, and nasal resonating chambers.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Quality / Timbre of sound</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Waveform and overtone pattern unique to each voice</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">Flash and thunder are produced simultaneously. But thunder is heard a few seconds after the flash is seen, why?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Enormous Difference in Propagation Speeds:</strong><br>\r\n  • Light is an electromagnetic wave travelling through air at a staggering speed of <span class=\"math\">c ≈ 3 × 10⁸ m s⁻¹ = 300,000 km s⁻¹</span>.<br>\r\n  • Sound is a mechanical wave travelling through air at only about <span class=\"math\">v ≈ 340 m s⁻¹ = 0.34 km s⁻¹</span>.<br><br>\r\n  Since the speed of light is nearly <strong>one million times faster</strong> than the speed of sound, the lightning flash reaches our eyes almost instantaneously (in a few microseconds), whereas the acoustic thunderclap takes several seconds to traverse the distance across the atmosphere to our ears.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Speed of light (3 × 10⁸ m/s) is nearly a million times faster than sound (340 m/s)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Light reaches instantly while sound takes noticeable seconds</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">A person has a hearing range from 20 Hz to 20 kHz. What are the typical wavelengths of sound waves in air corresponding to these two frequencies? Take the speed of sound in air as 344 m s⁻¹.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Formula:</strong> <span class=\"math\">v = \r\nu × λ ⟹ λ = v / \r\nu</span><br>\r\n  Given <span class=\"math\">v = 344 m s⁻¹</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>1. For Lower Limit (<span class=\"math\">\r\nu₁ = 20 Hz</span>):</strong><br>\r\n  <span class=\"math\">λ₁ = 344 / 20 = 17.2 m</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>2. For Upper Limit (<span class=\"math\">\r\nu₂ = 20,000 Hz = 20 kHz</span>):</strong><br>\r\n  <span class=\"math\">λ₂ = 344 / 20,000 = 0.0172 m = 1.72 cm</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> Audible wavelengths in air range from <strong>1.72 cm to 17.2 metres</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula λ = v / ν</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">λ for 20 Hz = 17.2 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">λ for 20 kHz = 0.0172 m (1.72 cm)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">Two children are at opposite ends of an aluminium rod. One strikes the end of the rod with a stone. Find the ratio of time taken by the sound wave in air and in aluminium to reach the second child (Speed in air = 346 m/s, Speed in Al = 6420 m/s).</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Let the length of the aluminium rod be <span class=\"math\">L</span> metres.</strong><br>\r\n  • Time taken by sound in air: <span class=\"math\">t_{air} = L / v_{air} = L / 346</span><br>\r\n  • Time taken by sound in aluminium: <span class=\"math\">t_{Al} = L / v_{Al} = L / 6420</span>\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Ratio of Time Taken:</strong><br>\r\n  <span class=\"math\">Ratio = t_{air} / t_{Al} = (L / 346) / (L / 6420) = 6420 / 346 ≈ 18.55 : 1</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The ratio of time taken by sound in air to aluminium is <strong>18.55 : 1</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formulas t_air = L/346 and t_Al = L/6420</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Ratio t_air / t_Al = 6420 / 346</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 18.55 : 1</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">The frequency of a source of sound is 100 Hz. How many times does it vibrate in a minute?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Frequency (<span class=\"math\">\r\nu</span>) = <span class=\"math\">100 Hz = 100 vibrations per second</span>.<br>\r\n  • Time (<span class=\"math\">t</span>) = <span class=\"math\">1 minute = 60 seconds</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">Total Vibrations = Frequency × Time in seconds</span><br>\r\n  <span class=\"math\">Total Vibrations = 100 × 60 = 6000 vibrations</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> It vibrates <strong>6000 times in a minute</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">1 minute = 60 seconds</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total vibrations = 100 × 60 = 6000</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_10')\">\r\n      <div class=\"q-num\">Exercise — Q10</div>\r\n      <div class=\"q-text\">Does sound follow the same laws of reflection as light does? Explain.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: Yes, sound follows the EXACT SAME laws of reflection as light.</strong><br><br>\r\n  <strong>The Two Laws of Reflection of Sound:</strong>\r\n  <ol>\r\n    <li>The incident sound wave, the reflected sound wave, and the normal to the reflecting surface at the point of incidence all lie in the <strong>same plane</strong>.</li>\r\n    <li>The <strong>angle of incidence (<span class=\"math\">∠i</span>) is always equal to the angle of reflection (<span class=\"math\">∠r</span>)</strong> (<span class=\"math\">∠i = ∠r</span>).</li>\r\n  </ol>\r\n  <em>Note:</em> Unlike light which requires a polished mirror, sound waves have long wavelengths, so they reflect efficiently off large, rough, or unpolished surfaces like brick walls, cliffs, or wooden boards.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative answer (Yes)</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating both laws of reflection accurately</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_11')\">\r\n      <div class=\"q-num\">Exercise — Q11</div>\r\n      <div class=\"q-text\">When a sound is reflected from a distant object, an echo is produced. Let the distance between the reflecting surface and the source of sound production remains the same. Do you hear echo sound on a hotter day?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Analysis of Echo on a Hot Day:</strong><br>\r\n  1. The persistence of hearing for human ears is <span class=\"math\">0.1 s</span>. To hear a distinct echo, the reflected sound must reach the ear at least <strong>0.1 seconds after the original sound</strong>: <span class=\"math\">t_{echo} = 2d / v ≥ 0.1 s ⟹ d ≥ v / 20</span>.<br>\r\n  2. The speed of sound in air is directly proportional to the square root of absolute temperature (<span class=\"math\">v ∝ √T</span>). On a hotter day, the <strong>speed of sound (<span class=\"math\">v</span>) increases</strong>.<br>\r\n  3. Because <span class=\"math\">v</span> is higher, the minimum distance required to hear an echo (<span class=\"math\">d_{min} = v × 0.1 / 2</span>) increases (from ~17.2 m at 22°C to ~18 m+ on a very hot day).<br>\r\n  4. If the distance to the obstacle was just barely sufficient on a cold day, on a hotter day the reflected sound will return in <strong>less than 0.1 s</strong> and blur into the original sound, meaning <strong>no distinct echo will be heard</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Persistence of hearing = 0.1 s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Speed of sound increases with temperature on a hotter day</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Echo time becomes less than 0.1 s ⟹ distinct echo may not be heard</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_12')\">\r\n      <div class=\"q-num\">Exercise — Q12</div>\r\n      <div class=\"q-text\">Give two practical applications of reflection of sound waves.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Practical Applications of Reflection of Sound:</strong>\r\n  <ol>\r\n    <li><strong>Stethoscope:</strong> A medical diagnostic instrument used by doctors to listen to heartbeats and lungs. The sound of heart valves closing is transmitted through acoustic tubes to the doctor's earpieces via <em>multiple reflections</em> inside the tube walls without loss of intensity.</li>\r\n    <li><strong>Megaphone / Horn / Trumpet:</strong> Cone-shaped acoustic devices designed to guide and reflect sound waves forward repeatedly in a specific direction, preventing them from spreading out in all directions and ensuring loud projection over long distances.</li>\r\n    <li><strong>Soundboard / Curved Ceilings:</strong> Used in concert halls and auditoriums to reflect sound evenly to all corners.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stethoscope (multiple reflections of heartbeat in acoustic tube)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Megaphone / Speaking tube / Soundboard explained</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_13')\">\r\n      <div class=\"q-num\">Exercise — Q13</div>\r\n      <div class=\"q-text\">A stone is dropped from the top of a tower 500 m high into a pond of water at the base of the tower. When is the splash heard at the top? Given, g = 10 m s⁻² and speed of sound = 340 m s⁻¹.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Step 1: Time for Stone to Fall into Pond (<span class=\"math\">t₁</span>):</strong><br>\r\n  <span class=\"math\">h = ut₁ + ½ gt₁²</span><br>\r\n  <span class=\"math\">500 = 0 + ½ (10) t₁² = 5 t₁² ⟹ t₁² = 100 ⟹ t₁ = 10 s</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 2: Time for Sound of Splash to Travel Back Up (<span class=\"math\">t₂</span>):</strong><br>\r\n  <span class=\"math\">t₂ = Distance / Speed of Sound = 500 / 340 ≈ 1.47 s</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Step 3: Total Time when Splash is Heard:</strong><br>\r\n  <span class=\"math\">Total Time = t₁ + t₂ = 10 s + 1.47 s = 11.47 s</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The splash is heard at the top after <strong>11.47 seconds</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating time of fall t₁ = 10 s</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating sound travel time t₂ = 1.47 s</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total time = 11.47 s</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_14')\">\r\n      <div class=\"q-num\">Exercise — Q14</div>\r\n      <div class=\"q-text\">A sound wave travels at a speed of 339 m s⁻¹. If its wavelength is 1.5 cm, what is the frequency of the wave? Will it be audible?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Speed (<span class=\"math\">v</span>) = <span class=\"math\">339 m s⁻¹</span>, Wavelength (<span class=\"math\">λ</span>) = <span class=\"math\">1.5 cm = 0.015 m</span>.<br><br>\r\n  <strong>Formula & Calculation:</strong><br>\r\n  <span class=\"math\">v = \r\nu × λ ⟹ \r\nu = v / λ</span><br>\r\n  <span class=\"math\">\r\nu = 339 / 0.015 = 22,600 Hz = 22.6 kHz</span>.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>Audibility Check:</strong><br>\r\n  The audible range of normal human hearing is 20 Hz to 20,000 Hz.<br>\r\n  Since <span class=\"math\">22,600 Hz &gt; 20,000 Hz</span>, this frequency falls into the <strong>ultrasound</strong> spectrum.<br>\r\n  <strong>Answer: No, it will NOT be audible to human ears.</strong>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting λ = 0.015 m</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating frequency ν = 22,600 Hz</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Checking against audible limit (20 kHz) and concluding Not Audible</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_15')\">\r\n      <div class=\"q-num\">Exercise — Q15</div>\r\n      <div class=\"q-text\">What is reverberation? How can it be reduced?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>1. Definition of Reverberation:</strong><br>\r\n  The persistence of prolonged sound in an enclosed hall or room as a result of repeated and continuous multiple reflections from the walls, ceiling, and floor even after the sound source has stopped emitting is called <strong>reverberation</strong>.<br>\r\n  Excessive reverberation causes sound overlapping and garbled, unintelligible speech.\r\n</div>\r\n<div class=\"step\">\r\n  <strong>2. Methods to Reduce Reverberation:</strong><br>\r\n  Reverberation is minimized by lining the hall with high sound-absorbing materials:\r\n  <ol>\r\n    <li>Covering the walls and ceilings with sound-absorbent materials like compressed acoustic fiberboards, rough plaster, or perforated acoustic tiles.</li>\r\n    <li>Hanging heavy, folded fabric draperies and curtains over windows and doors.</li>\r\n    <li>Using plush upholstered seats with porous fabrics (and carpets on floors) that absorb sound energy.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of reverberation as persistence of sound due to repeated reflections</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Two or more valid methods to reduce reverberation using sound-absorbent materials</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_16')\">\r\n      <div class=\"q-num\">Exercise — Q16</div>\r\n      <div class=\"q-text\">What is loudness of sound? What factors does it depend on?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition & Factors:</strong><br>\r\n  • <strong>Loudness:</strong> The physiological sensation produced in the ear by which a listener perceives a sound as faint or loud.<br>\r\n  • <strong>Factors Influencing Loudness:</strong>\r\n    <ol>\r\n      <li><strong>Amplitude of Vibration:</strong> Loudness is directly proportional to the square of amplitude (<span class=\"math\">Loudness ∝ Amplitude²</span>). Doubling amplitude quadruples loudness.</li>\r\n      <li><strong>Surface Area of Vibrating Body:</strong> Larger surface area displaces more air, increasing loudness (e.g. large bass drum vs small tambourine).</li>\r\n      <li><strong>Distance from Source:</strong> Loudness decreases inversely with distance (<span class=\"math\">I ∝ 1/r²</span>).</li>\r\n      <li><strong>Sensitivity of the Listener's Ear:</strong> Subjective physiological threshold of the hearer.</li>\r\n    </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of loudness as sensation depending on sound intensity</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Dependence on amplitude (L ∝ A²), surface area, and distance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_17\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_17')\">\r\n      <div class=\"q-num\">Exercise — Q17</div>\r\n      <div class=\"q-text\">Explain how bats use ultrasound to catch a prey.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Echolocation by Bats:</strong><br>\r\n  1. Flying bats emit high-frequency ultrasonic squeaks (typically 20 kHz to 100 kHz) during night flight.<br>\r\n  2. These ultrasound waves travel outward, strike any flying insect (prey) or obstacle, and are reflected back as echoes.<br>\r\n  3. The sensitive auditory system of the bat detects these reflected echoes.<br>\r\n  4. By calculating the time delay between emission and echo return, along with changes in frequency (Doppler shift), the bat's brain instantly computes the exact distance, direction, speed, and size of the prey, allowing it to swoop in and catch it in pitch darkness.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Emission of high-frequency ultrasonic waves</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Detection of reflected echoes calculating distance/direction of prey (echolocation)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_18\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_18')\">\r\n      <div class=\"q-num\">Exercise — Q18</div>\r\n      <div class=\"q-text\">How is ultrasound used for cleaning?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Ultrasonic Cleaning Mechanism:</strong><br>\r\n  1. Objects with intricate, spiral, or inaccessible shapes (such as electronic parts, delicate watch mechanisms, surgical instruments, and jewelry) are placed in a cleaning bath containing a solvent solution.<br>\r\n  2. High-frequency ultrasonic waves are passed into the solution via an ultrasonic transducer.<br>\r\n  3. The high-frequency waves create localized high-pressure cavitation bubbles that rapidly collapse, generating intense microscopic scrubbing shockwaves in the liquid.<br>\r\n  4. These shockwaves vigorously detach and scrub away grease, dirt, carbon, and dust particles from the deepest cavities, leaving the object thoroughly clean.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Immersion in cleaning liquid and transmission of high-frequency ultrasound</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">High-frequency vibrations/cavitation detach dirt from spiral/inaccessible parts</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_19\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_19')\">\r\n      <div class=\"q-num\">Exercise — Q19</div>\r\n      <div class=\"q-text\">Explain the working and application of a SONAR.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>SONAR (SOund Navigation And Ranging):</strong><br>\r\n  • <strong>Working Principle:</strong><br>\r\n    1. A SONAR unit installed on a ship or submarine consists of two primary components: a <strong>Transmitter</strong> and a <strong>Receiver (Detector)</strong>.<br>\r\n    2. The transmitter generates and transmits powerful ultrasonic pulses down through seawater.<br>\r\n    3. These ultrasound pulses travel through the water, strike underwater objects (such as the seabed, sunken ships, submarines, or schools of fish), and reflect back.<br>\r\n    4. The reflected echo is captured by the detector, which converts ultrasonic waves into electrical signals.<br>\r\n    5. The depth/distance (<span class=\"math\">d</span>) is calculated using: <span class=\"math\">2d = v × t ⟹ d = (v × t) / 2</span>.<br><br>\r\n  • <strong>Key Applications:</strong><br>\r\n    - Measuring ocean depth (bathymetry).<br>\r\n    - Detecting enemy submarines, underwater icebergs, marine trenches, and sunken shipwrecks.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Transmitter producing ultrasound and receiver detecting reflected echo</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Echo ranging formula 2d = v × t ⟹ d = vt/2</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Practical applications (ocean depth, submarine detection)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_20\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_20')\">\r\n      <div class=\"q-num\">Exercise — Q20</div>\r\n      <div class=\"q-text\">A sonar device on a submarine sends out a signal and receives an echo 5 s later. Calculate the speed of sound in water if the distance of the object from the submarine is 3625 m.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Given:</strong> Time (<span class=\"math\">t</span>) = <span class=\"math\">5 s</span>, Distance (<span class=\"math\">d</span>) = <span class=\"math\">3625 m</span>.<br><br>\r\n  <strong>Calculation:</strong><br>\r\n  <span class=\"math\">2d = v × t ⟹ v = (2d) / t</span><br>\r\n  <span class=\"math\">v = (2 × 3625) / 5 = 7250 / 5 = 1450 m s⁻¹</span>.\r\n</div>\r\n<p><strong>Final Answer:</strong> The speed of sound in water is <strong>1450 m s⁻¹</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula v = 2d / t</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation = 1450 m s⁻¹</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_21\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_21')\">\r\n      <div class=\"q-num\">Exercise — Q21</div>\r\n      <div class=\"q-text\">Explain how defects in a metal block can be detected using ultrasound.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Non-Destructive Flaw Detection using Ultrasound:</strong><br>\r\n  1. Ultrasound waves can easily penetrate deep into metallic solids.<br>\r\n  2. In industry, metallic blocks used in building bridges, airplanes, and heavy machinery are tested for internal flaws (cracks, voids, blowholes).<br>\r\n  3. High-frequency ultrasonic beams are passed from one side of the metal block, and sensitive electronic detectors are placed on the opposite face.<br>\r\n  4. <strong>If the block is flawless:</strong> The ultrasound waves pass straight through the metal and are completely registered by all opposing detectors.<br>\r\n  5. <strong>If there is a defect or crack:</strong> The ultrasound beam strikes the internal boundary of the crack, reflects prematurely backward, and does not reach the opposite detector.<br>\r\n  6. The absence or attenuation of transmitted signal reveals the presence, depth, and exact location of internal defects without breaking the metal block.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Ultrasound passed through metal block with detectors on other side</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Internal cracks reflect waves back, showing missing signal on detector</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Allows non-destructive inspection of structural integrity</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q11_ex_22\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_ex_22')\">\r\n      <div class=\"q-num\">Exercise — Q22</div>\r\n      <div class=\"q-text\">Explain how the human ear works.</div>\r\n      <div class=\"q-marks\">5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Anatomy and Physiology of the Human Ear:</strong><br>\r\n  The human ear consists of three primary anatomical sections:\r\n  <ol>\r\n    <li><strong>Outer Ear:</strong><br>\r\n      • <strong>Pinna:</strong> Collects sound waves from the surrounding environment.<br>\r\n      • <strong>Auditory Canal:</strong> Directs sound waves inward to the thin, delicate <strong>tympanic membrane (eardrum)</strong>. Compressions push the membrane inward, while rarefactions pull it outward, setting it into vibration.\r\n    </li>\r\n    <li><strong>Middle Ear:</strong><br>\r\n      • Contains three tiny interconnected bones called ossicles: <strong>Hammer (Malleus), Anvil (Incus), and Stirrup (Stapes)</strong>.<br>\r\n      • The ossicles act as a mechanical lever system, amplifying the vibration amplitude by about 20 to 30 times and transferring it through the oval window to the inner ear.\r\n    </li>\r\n    <li><strong>Inner Ear:</strong><br>\r\n      • Consists of a fluid-filled snail-shell-like coiled organ called the <strong>Cochlea</strong>.<br>\r\n      • Fluid pressure waves inside the cochlea stimulate microscopic hair cells (sensory receptors), transforming mechanical pressure vibrations into <strong>electrical nerve impulses</strong>.<br>\r\n      • These nerve impulses travel via the <strong>Auditory Nerve</strong> to the temporal lobe of the brain, which decodes them as sound.\r\n    </li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Outer Ear: Pinna, Auditory canal, Eardrum vibrating with pressure changes</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Middle Ear: Hammer, Anvil, Stirrup amplifying mechanical vibrations</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Inner Ear: Cochlea converting fluid waves to electrical signals via Auditory nerve to brain</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 11</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Medical Echocardiography & Ultrasonography:</strong> Doctors routinely use ultrasound imaging (USG) to monitor foetal development and diagnose cardiac valve defects.<br>(a) Why is ultrasound preferred over X-rays for prenatal foetal examination?<br>(b) On what property of ultrasound does medical imaging depend?<br>(c) What is the frequency range of ultrasound used in medical diagnostics?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> Ultrasound waves are mechanical sound waves that do not cause ionizing cellular or DNA radiation damage, making them completely safe for developing foetuses, unlike hazardous ionizing X-rays.<br><strong>(b)</strong> It depends on the <strong>reflection of ultrasound waves</strong> from acoustic impedance boundaries between different soft tissue layers.<br><strong>(c)</strong> Typically between <strong>2 MHz and 15 MHz</strong> (well above human hearing).</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why do dogs respond to a Galton whistle while humans standing right next to the dog cannot hear anything at all?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">A Galton whistle produces high-frequency ultrasonic sound waves above 20 kHz (typically around 25 kHz to 30 kHz). The upper hearing threshold of human ears is strictly limited to 20 kHz (20,000 Hz), so humans cannot perceive it. Dogs have a much wider auditory frequency spectrum extending up to 45 kHz to 50 kHz, allowing them to hear and respond readily to the whistle.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(10)\">← Chapter 10</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\">Chapter 12 →</button>\r\n  </div>\r\n</section>","12":"<section class=\"chapter-section\" id=\"ch12\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">12</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 12: Improvement in Food Resources</h2>\r\n      <p>Crop Variety Improvement, Crop Production & Protection Management, Animal Husbandry (Cattle, Poultry, Fisheries & Apiculture) — CBSE Marking Scheme 2026-27 — CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 204)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_in_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_1')\">\r\n      <div class=\"q-num\">Page 204 — Q1</div>\r\n      <div class=\"q-text\">What do we get from cereals, pulses, fruits and vegetables?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Nutritional Contributions of Agricultural Crops:</strong>\r\n  <ul>\r\n    <li><strong>Cereals (e.g. Wheat, Rice, Maize, Millets, Sorghum):</strong> Provide rich dietary sources of <strong>Carbohydrates</strong>, which are the primary energy fuel for metabolic cellular activities.</li>\r\n    <li><strong>Pulses (e.g. Gram/chana, Pea/matar, Black gram/urad, Green gram/moong, Pigeon pea/arhar, Lentil/masoor):</strong> Excellent sources of <strong>Proteins</strong>, essential for body growth, enzyme synthesis, and tissue repair.</li>\r\n    <li><strong>Vegetables, Spices and Fruits:</strong> Provide essential <strong>Vitamins</strong> (Vitamin A, B-complex, C, D, K) and <strong>Minerals</strong> (Iron, Calcium, Iodine, Potassium), along with small quantities of proteins, carbohydrates, and dietary fiber/roughage needed for digestion and immunity.</li>\r\n    <li><strong>Oilseeds (e.g. Soyabean, Groundnut, Mustard, Sesame, Sunflower):</strong> Provide essential <strong>Fats and fatty acids</strong>.</li>\r\n  </ul>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cereals provide carbohydrates for energy</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Pulses provide proteins for growth/repair</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Fruits and vegetables provide vitamins and minerals for immunity</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 205)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_in_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_2')\">\r\n      <div class=\"q-num\">Page 205 — Q1</div>\r\n      <div class=\"q-text\">How do biotic and abiotic factors affect crop production?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Impact of Environmental Stress Factors on Crops:</strong><br>\r\n  • <strong>1. Biotic Factors (Living Stresses):</strong><br>\r\n    - Infestation by <strong>insect pests</strong> (chewing roots/leaves, boring into stems/fruits).<br>\r\n    - Pathogenic infections by <strong>fungi, bacteria, and viruses</strong> causing blights, rusts, and wilts.<br>\r\n    - Nematodes and rodents destroying standing crops and stored grain.<br>\r\n    - Weeds competing aggressively for sunlight, moisture, space, and soil nutrients.<br><br>\r\n  • <strong>2. Abiotic Factors (Non-living Environmental Stresses):</strong><br>\r\n    - <strong>Drought</strong> (water scarcity) and <strong>waterlogging / flooding</strong> (root suffocation).<br>\r\n    - High soil <strong>salinity</strong> inhibiting osmotic water absorption.<br>\r\n    - Extreme temperatures (heat waves, frost, cold injury) causing flower drop, poor pollination, and enzyme denaturation.<br><br>\r\n  <strong>Consequences:</strong> Loss of vegetative vigour, stunted growth, premature seed drop, discoloration of grain, poor germinability, and severe reduction in total crop yield and market value.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Biotic factors explained (insects, pathogens, weeds, rodents)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Abiotic factors explained (drought, waterlogging, salinity, heat/frost)</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_3')\">\r\n      <div class=\"q-num\">Page 205 — Q2</div>\r\n      <div class=\"q-text\">What are the desirable agronomic characteristics for crop improvements?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Desirable Agronomic Traits for Higher Productivity:</strong>\r\n  <ol>\r\n    <li><strong>Profuse Branching and Tallness in Fodder Crops:</strong> For crops grown to feed livestock (e.g. Berseem, Oats, Sudan grass), tall vegetative stature with abundant foliage is desirable to maximize edible green biomass.</li>\r\n    <li><strong>Dwarfness in Cereal Crops:</strong> For cereals like wheat and rice, dwarf varieties are preferred because they consume fewer soil nutrients for stem growth, develop thicker lodging-resistant stalks that do not bend over during storms, and partition maximum photosynthates into heavy grain heads.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Fodder crops: Tallness and profuse vegetative branching for high biomass</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Cereal crops: Dwarfness to prevent lodging and conserve nutrients for grain</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 207)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_in_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_4')\">\r\n      <div class=\"q-num\">Page 207 — Q1</div>\r\n      <div class=\"q-text\">What are macro-nutrients and why are they called macro-nutrients?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition & Significance:</strong><br>\r\n  Plants require 16 essential mineral nutrients derived from air, water, and soil. Nutrients absorbed from the soil are divided into two categories:<br><br>\r\n  • <strong>Macro-nutrients:</strong> Essential elements that are required by plants in <strong>relatively large quantities</strong> (concentrations &gt; 1 mg per gram of dry matter) for structural building and primary metabolic pathways.<br>\r\n  • <strong>Why they are called Macro-nutrients:</strong> Because the plant's physiological demand for these elements is high (e.g. building proteins, nucleic acids, cell membranes, and chlorophyll).<br><br>\r\n  • <strong>The Six Soil Macro-nutrients are:</strong> <strong>Nitrogen (N), Phosphorus (P), Potassium (K), Calcium (Ca), Magnesium (Mg), and Sulphur (S)</strong>.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: Essential elements required in large quantities by plants</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Naming the 6 macronutrients: N, P, K, Ca, Mg, S</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_5')\">\r\n      <div class=\"q-num\">Page 207 — Q2</div>\r\n      <div class=\"q-text\">How do plants get nutrients?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Sources of Nutrients for Plants (Total 16 Essential Nutrients):</strong>\r\n  <ol>\r\n    <li><strong>From Air (2 Nutrients):</strong> <strong>Carbon (C)</strong> and <strong>Oxygen (O)</strong> are absorbed as carbon dioxide (<span class=\"math\">CO₂</span>) through leaf stomata during photosynthesis and respiration.</li>\r\n    <li><strong>From Water (1 Nutrient):</strong> <strong>Hydrogen (H)</strong> is absorbed through roots from soil moisture (<span class=\"math\">H₂O</span>).</li>\r\n    <li><strong>From Soil (13 Nutrients):</strong> Absorbed as dissolved inorganic mineral ions by root hairs through passive diffusion and active transport:\r\n      <ul>\r\n        <li><em>Macro-nutrients (6):</em> Nitrogen, Phosphorus, Potassium, Calcium, Magnesium, Sulphur.</li>\r\n        <li><em>Micro-nutrients (7):</em> Iron, Manganese, Boron, Zinc, Copper, Molybdenum, Chlorine.</li>\r\n      </ul>\r\n    </li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Carbon and oxygen from air via stomata</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Hydrogen from water via roots</span><span class=\"marking-marks\">½ Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">13 mineral nutrients (6 macro + 7 micro) from soil dissolved in water</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 208)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_in_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_6')\">\r\n      <div class=\"q-num\">Page 208 — Q1</div>\r\n      <div class=\"q-text\">Compare the use of manure and fertilizers in maintaining soil fertility.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison: Manure vs Chemical Fertilizers for Soil Fertility:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Manure (Organic)</th><th>Fertilizers (Chemical)</th></tr>\r\n    <tr><td><strong>Origin</strong></td><td>Natural organic substance prepared by biological decomposition of plant residues, crop waste, and animal excreta.</td><td>Commercially manufactured inorganic chemical salts synthesized in factories.</td></tr>\r\n    <tr><td><strong>Nutrient Concentration</strong></td><td>Contains low, balanced concentrations of all nutrients; slow acting.</td><td>Highly concentrated in specific target nutrients (N, P, K); fast acting.</td></tr>\r\n    <tr><td><strong>Humus & Soil Structure</strong></td><td>Adds abundant <strong>organic matter (humus)</strong>, dramatically enhancing soil porosity, aeration, and water-holding capacity.</td><td>Provides <strong>zero humus</strong> to the soil; does not improve soil physical crumb structure.</td></tr>\r\n    <tr><td><strong>Soil Organisms</strong></td><td>Nourishes beneficial soil microorganisms and earthworms, maintaining a vibrant soil ecosystem.</td><td>Excessive long-term application harms or kills soil microflora and earthworms.</td></tr>\r\n    <tr><td><strong>Long-term Impact</strong></td><td>Maintains sustainable, long-term soil fertility without chemical hazards.</td><td>Prolonged overuse leads to soil acidification or alkalization and causes water pollution (eutrophication) via runoff.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Natural organic vs industrial chemical origin</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Humus addition and soil physical structure enhancement by manure</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Long-term fertility sustainability vs fertilizer chemical degradation/eutrophication</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 209)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_in_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_7')\">\r\n      <div class=\"q-num\">Page 209 — Q1</div>\r\n      <div class=\"q-text\">Which of the following conditions will give the most benefits? Why?<br>(a) Farmers use high quality seeds, do not adopt irrigation or use fertilizers.<br>(b) Farmers use ordinary seeds, adopt irrigation and use fertilizer.<br>(c) Farmers use quality seeds, adopt irrigation, use fertilizer and use crop protection measures.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Answer: Condition (c) will give the most benefits.</strong><br><br>\r\n  <strong>Detailed Justification:</strong><br>\r\n  Agricultural productivity is governed by the synergistic interaction of multiple coordinated management practices:\r\n  <ol>\r\n    <li><strong>Quality Seeds (High-Yielding Varieties):</strong> Genetically superior seeds possess inherent potential for high yield, disease resistance, and uniform maturity. But this genetic potential can only be expressed if provided with optimal nutrition and water.</li>\r\n    <li><strong>Irrigation:</strong> Ensures timely, regulated moisture supply during critical phenological growth stages (tillering, flowering, grain-filling), avoiding drought stress.</li>\r\n    <li><strong>Fertilizers:</strong> Supply required macro-nutrients (N, P, K) in readily absorbable form at peak growth periods.</li>\r\n    <li><strong>Crop Protection Measures:</strong> Without weed, pest, and disease control, up to 30–50% of the standing crop could be decimated, negating all financial investments made in seeds and fertilizers.</li>\r\n  </ol>\r\n  Condition (a) fails due to drought and nutrient starvation. Condition (b) is limited by the poor genetic ceiling of ordinary seeds. Only condition (c) achieves complete, synergistic agricultural optimization.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying Condition (c) as the optimal approach</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining synergy of quality seed genetics with irrigation and fertilizers</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Highlighting indispensability of crop protection to safeguard investments</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 211)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_in_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_8')\">\r\n      <div class=\"q-num\">Page 211 — Q1</div>\r\n      <div class=\"q-text\">Why should preventive measures and biological control methods be preferred for protecting crops?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Advantages of Preventive & Biological Control Methods:</strong><br>\r\n  Chemical pesticides (insecticides, fungicides, herbicides) pose severe ecological and human health hazards:\r\n  <ol>\r\n    <li><strong>Eco-friendly & Non-toxic:</strong> Biological methods (using natural predators, parasitoids, or biopesticides like <em>Bacillus thuringiensis</em> or neem extracts) target only specific pests without harming beneficial pollinating insects (bees), earthworms, or soil microbes.</li>\r\n    <li><strong>Prevents Biomagnification:</strong> Synthetic chemical pesticides are non-biodegradable and accumulate along trophic food chains (biomagnification), poisoning wildlife and contaminating human food/milk supplies.</li>\r\n    <li><strong>Prevents Pest Resistance:</strong> Pests quickly evolve biochemical resistance to repeated chemical sprays; biological control maintains a self-sustaining natural ecological predator-prey balance.</li>\r\n    <li><strong>Cost-effective & Sustainable:</strong> Preventive measures like proper seed bed preparation, timely sowing, crop rotation, and mixed cropping eradicate pests at the source with minimal financial expense.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Eco-friendly without contaminating soil/water or harming non-target organisms</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Elimination of pesticide residues and biomagnification risks</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Prevention of pest resistance and long-term economic sustainability</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_9')\">\r\n      <div class=\"q-num\">Page 211 — Q2</div>\r\n      <div class=\"q-text\">What factors may be responsible for losses of grains during storage?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Factors Responsible for Post-Harvest Storage Grain Losses:</strong>\r\n  <ul>\r\n    <li><strong>1. Biotic Factors (Living Organisms):</strong><br>\r\n      • <strong>Insects / Weevils:</strong> Boring into grains (e.g. rice weevil, pulse beetle).<br>\r\n      • <strong>Rodents (rats, mice):</strong> Consuming grains and contaminating them with excreta.<br>\r\n      • <strong>Fungi / Moulds (e.g. <em>Aspergillus</em>):</strong> Producing carcinogenic mycotoxins (aflatoxins) and causing rot.<br>\r\n      • <strong>Mites and Bacteria:</strong> Causing spoilage and decay.\r\n    </li>\r\n    <li><strong>2. Abiotic Factors (Environmental):</strong><br>\r\n      • <strong>Excess Moisture Content:</strong> Moisture content &gt; 12% in grains accelerates fungal infestation and premature heating.<br>\r\n      • <strong>Inappropriate Temperature:</strong> Warm, humid conditions inside silos/warehouses promote rapid pest reproduction.\r\n    </li>\r\n  </ul>\r\n  <strong>Resulting Damage:</strong> Degradation in nutritional quality, loss in grain weight, poor germinability, and severe discoloration.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Biotic factors: Insects, rodents, fungi, bacteria, mites</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Abiotic factors: High moisture content in grain and humid temperature</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Intext Questions (Page 213)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_in_10\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_10')\">\r\n      <div class=\"q-num\">Page 213 — Q1</div>\r\n      <div class=\"q-text\">Which method is commonly used for improving cattle breeds and why?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Method: Cross-Breeding between Indigenous and Exotic Breeds.</strong><br><br>\r\n  <strong>Why it is Used:</strong><br>\r\n  Cross-breeding combines the desirable genetic traits of two distinct parental breeds to achieve hybrid vigour:\r\n  <ol>\r\n    <li><strong>Exotic / Foreign Breeds (e.g. Jersey, Holstein-Friesian):</strong> Selected for their <strong>exceptionally high milk yield and long lactation periods</strong>.</li>\r\n    <li><strong>Indigenous / Local Breeds (e.g. Red Sindhi, Sahiwal):</strong> Selected for their <strong>excellent natural disease resistance and hardiness to withstand tropical Indian heat and climate</strong>.</li>\r\n  </ol>\r\n  The cross-bred offspring inherits both high milk productivity and robust disease resistance.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Method: Cross-breeding between indigenous and exotic cattle breeds</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Combining high milk yield/long lactation with tropical disease resistance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_11\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_11')\">\r\n      <div class=\"q-num\">Page 213 — Q2</div>\r\n      <div class=\"q-text\">What is cross breeding? What are its advantages?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition:</strong><br>\r\n  <strong>Cross-breeding</strong> is the biological process of mating or hybridizing two genetically different breeds, varieties, or strains of animals or plants to produce superior hybrid offspring (F1 generation).<br><br>\r\n  <strong>Key Advantages:</strong>\r\n  <ol>\r\n    <li><strong>Heterosis (Hybrid Vigour):</strong> Offspring often display superior vitality, faster growth rates, and greater stamina than either parent.</li>\r\n    <li><strong>Combining Dual Desirable Traits:</strong> Merging distinct commercial traits (e.g. high egg/meat yield with low maintenance feed requirements).</li>\r\n    <li><strong>Enhanced Environmental Adaptability:</strong> Imparts climate tolerance and disease resistance to delicate high-producing exotic stock.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: Breeding between two distinct genetic varieties</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Advantages: Hybrid vigour, combining traits, disease resistance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_12\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_12')\">\r\n      <div class=\"q-num\">Page 213 — Q3</div>\r\n      <div class=\"q-text\">Discuss the implications of the following statement: 'It is interesting to note that poultry is India's most efficient converter of low fibre food stuff into highly nutritious animal protein food.'</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Scientific Analysis & Implications:</strong><br>\r\n  1. <strong>Utilization of Inedible Agricultural By-products:</strong> Poultry birds (chickens, hens) consume low-cost agricultural residues, bran, broken grains, oilcakes, and animal slaughter by-products that are unpalatable or indigestible to humans due to poor nutritional appeal.<br>\r\n  2. <strong>Superior Feed Conversion Ratio (FCR):</strong> Poultry birds have a remarkably high biological feed conversion efficiency. They metabolize coarse feeds rapidly to synthesize high-grade biological tissue.<br>\r\n  3. <strong>Nutritional Boon:</strong> They convert cheap carbohydrate-rich raw feed into <strong>eggs and broiler meat</strong>, which are rich in complete animal proteins (containing all essential amino acids), vitamins (A, B12, D), and bioavailable minerals (Iron, Phosphorus).<br>\r\n  4. <strong>Economic & Food Security:</strong> This makes poultry farming an essential vehicle for overcoming widespread protein malnutrition in developing nations at low economic cost.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Consumption of cheap, coarse agricultural by-products inedible to humans</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">High biological feed conversion efficiency into meat and eggs</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Combating protein malnutrition economically with high-grade animal protein</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_13\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_13')\">\r\n      <div class=\"q-num\">Page 213 — Q4</div>\r\n      <div class=\"q-text\">What management practices are common in dairy and poultry farming?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Common Management Practices in Dairy and Poultry Farming:</strong>\r\n  <ol>\r\n    <li><strong>Shelter & Housing Management:</strong> Providing clean, dry, well-ventilated, spacious, and well-lit animal sheds with sloped floors for easy drainage and waste removal, protecting animals from rain, heat, and cold.</li>\r\n    <li><strong>Nutritional Feed Management:</strong> Providing scientifically balanced rations containing maintenance and production requirements (concentrates rich in proteins and minerals, alongside roughage for digestion). Clean drinking water must be available at all times.</li>\r\n    <li><strong>Hygiene and Sanitation:</strong> Regular washing, grooming, removal of dung/droppings, and periodic spraying of non-toxic disinfectants inside housing sheds.</li>\r\n    <li><strong>Disease Prevention & Vaccination:</strong> Timely vaccination schedules against infectious bacterial and viral diseases, alongside strict quarantine protocols for sick animals.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Clean, well-ventilated shelter with proper sanitation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Balanced nutritional feeding and clean drinking water</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Disease prevention, veterinary health care, and routine vaccination</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_14\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_14')\">\r\n      <div class=\"q-num\">Page 213 — Q5</div>\r\n      <div class=\"q-text\">What are the differences between broilers and layers and in their management?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison: Broilers vs Layers:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Broilers</th><th>Layers</th></tr>\r\n    <tr><td><strong>Primary Purpose</strong></td><td>Reared specifically for <strong>meat production</strong>.</td><td>Reared specifically for <strong>egg production</strong>.</td></tr>\r\n    <tr><td><strong>Rearing Period</strong></td><td>Raised for 6 to 8 weeks until they reach market weight (~1.5–2 kg), then slaughtered.</td><td>Raised to sexual maturity (around 20 weeks) and kept laying for about 500 days.</td></tr>\r\n    <tr><td><strong>Nutritional Feed Requirements</strong></td><td>Feed must be heavily enriched with <strong>proteins, fats, and Vitamin A & K</strong> to promote rapid muscle mass accretion and fast daily weight gain.</td><td>Feed requires adequate protein and energy, but must be fortified with <strong>high Calcium and Phosphorus</strong> for strong eggshell formation.</td></tr>\r\n    <tr><td><strong>Housing & Lighting</strong></td><td>Require controlled space and subdued lighting to minimize fighting and keep birds calm.</td><td>Require regulated photoperiods (14–16 hours of light per day) to stimulate the pituitary gland and optimize oviposition.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Purpose: Meat (Broilers) vs Eggs (Layers)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Nutritional differences: High protein/fat/vitamins A & K vs calcium for eggshells</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Lifespan (6-8 weeks vs 1.5 years) and lighting management</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_15\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_15')\">\r\n      <div class=\"q-num\">Page 213 — Q6</div>\r\n      <div class=\"q-text\">How are fish obtained?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Two Primary Methods of Obtaining Fish:</strong>\r\n  <ol>\r\n    <li><strong>Capture Fishery:</strong> Fish are caught directly from natural wild aquatic resources (such as oceans, seas, rivers, lakes, reservoirs, and estuaries) using fishing vessels and various fishing gear/nets without human cultivation.</li>\r\n    <li><strong>Culture Fishery (Aquaculture / Pisciculture):</strong> Fish are artificially bred, reared, fed, and harvested under controlled conditions in artificial freshwater tanks, inland ponds, or brackish water lagoons.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Capture fishery (harvesting wild fish from natural water bodies)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Culture fishery / Aquaculture (controlled artificial rearing in ponds/tanks)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_16\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_16')\">\r\n      <div class=\"q-num\">Page 213 — Q7</div>\r\n      <div class=\"q-text\">What are the advantages of composite fish culture?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Composite Fish Culture (Polyculture System):</strong><br>\r\n  A combination of five or six compatible fish species having different feeding habits is cultured simultaneously in a single fish pond. Typically:<br>\r\n  • <strong>Catla:</strong> Surface feeder (zooplankton).<br>\r\n  • <strong>Rohu:</strong> Column feeder (aquatic microplants/algae in middle depth).<br>\r\n  • <strong>Mrigal & Common Carp:</strong> Bottom feeders (decaying organic matter and bottom detritus).<br>\r\n  • <strong>Grass Carp:</strong> Feeds on submersed aquatic weeds.<br><br>\r\n  <strong>Major Advantages:</strong>\r\n  <ol>\r\n    <li><strong>Zero Food Competition:</strong> Because each species occupies a different ecological niche and feeds at a different depth, they do not compete with each other for food.</li>\r\n    <li><strong>Complete Food Utilization:</strong> Food available in all vertical zones (surface, middle, bottom) and aquatic weeds are fully consumed without waste.</li>\r\n    <li><strong>Tremendously High Yield:</strong> Fish survival rate is maximized, yielding exceptionally high fish harvest per hectare of water area.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Culturing 5-6 non-competing species with different feeding zones</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Examples: Catla (surface), Rohu (column), Mrigal/Carp (bottom)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">No food competition and complete food utilization yielding high harvest</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_17\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_17')\">\r\n      <div class=\"q-num\">Page 213 — Q8</div>\r\n      <div class=\"q-text\">What are the desirable characters of bee varieties suitable for honey production?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Desirable Traits in Commercial Honey Bee Varieties:</strong><br>\r\n  (e.g. Italian bee <em>Apis mellifera</em> vs indigenous <em>Apis cerana indica</em>):\r\n  <ol>\r\n    <li><strong>High Honey Collection Capacity:</strong> High foraging efficiency and capacity to store large quantities of honey in the hive.</li>\r\n    <li><strong>Gentle Temperament:</strong> They should sting relatively less, facilitating safe handling by beekeepers.</li>\r\n    <li><strong>Long Hive Retention:</strong> They should stay inside given artificial hives for long periods without frequently absconding or swarming away.</li>\r\n    <li><strong>Prolific Breeding:</strong> Queen bees should lay large clutches of eggs to build strong worker populations quickly.</li>\r\n    <li><strong>Disease Resistance:</strong> High natural resistance against foulbrood, tracheal mites, and wax moths.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">High honey collection capacity and gentle nature (stings less)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stays in hive without swarming and breeds well with disease resistance</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_in_18\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_in_18')\">\r\n      <div class=\"q-num\">Page 213 — Q9</div>\r\n      <div class=\"q-text\">What is pasturage and how is it related to honey production?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Definition & Direct Correlation:</strong><br>\r\n  • <strong>Pasturage (or Flora):</strong> Refers to the availability of flowering vegetation, trees, shrubs, and agricultural crops from which honey bees collect floral <strong>nectar</strong> (sugary carbohydrate liquid) and <strong>pollen</strong> (protein food).<br><br>\r\n  • <strong>Relationship to Honey Production:</strong>\r\n    1. <strong>Quantity of Honey:</strong> The abundance, density, and duration of pasturage flowering season directly govern how much nectar foraging bees can collect, determining the overall yield of honey.</li>\r\n    2. <strong>Taste, Aroma & Quality:</strong> The specific types of flowers available in the pasturage dictate the unique flavor, colour, fragrance, and medicinal quality of the harvested honey (e.g. mustard honey, litchi honey, eucalyptus honey).</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Pasturage defined as flowering vegetation providing nectar and pollen</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Determines quantity of yield and specific taste/flavour of honey</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ex-div\">NCERT Chapter-End Exercises</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_ex_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_1')\">\r\n      <div class=\"q-num\">Exercise — Q1</div>\r\n      <div class=\"q-text\">Explain any one method of crop production which ensures high yield.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Method: Inter-Cropping System:</strong><br>\r\n  • <strong>Description:</strong> Inter-cropping is the practice of growing two or more crops simultaneously on the same piece of agricultural land in a definite row pattern (e.g. 1:1, 1:2, or 2:2 row proportions).<br>\r\n  • <em>Classic Examples:</em> Soyabean + Maize; Finger millet (Bajra) + Cowpea (Lobia).<br><br>\r\n  <strong>How It Ensures High Yield:</strong>\r\n  <ol>\r\n    <li><strong>Complementary Nutrient Uptake:</strong> The crops are selected such that their nutrient requirements, root depths, and growth periods differ. This prevents mutual competition and maximizes utilization of soil nutrients and sunlight.</li>\r\n    <li><strong>Insurance Against Total Crop Failure:</strong> If one crop is damaged by drought or a specific pest, the companion crop survives, ensuring guaranteed financial return to the farmer.</li>\r\n    <li><strong>Pest Containment:</strong> Prevents rapid spread of host-specific pests and plant diseases across the field.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of Intercropping / Crop Rotation with row pattern explanation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Scientific reasons for high yield (complementary nutrient uptake, soil optimization)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Risk insurance and pest containment</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_ex_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_2')\">\r\n      <div class=\"q-num\">Exercise — Q2</div>\r\n      <div class=\"q-text\">Why are manure and fertilizers used in fields?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Reasons for Applying Manure and Fertilizers:</strong><br>\r\n  With continuous intensive crop cultivation, soils become progressively depleted of essential mineral nutrients.<br>\r\n  <ol>\r\n    <li><strong>Replenishing Essential Mineral Nutrients:</strong> Both manure and fertilizers replenish depleted nitrogen, phosphorus, potassium, and micronutrients necessary for vigorous vegetative growth (leaves, stems), timely flowering, and robust grain formation.</li>\r\n    <li><strong>Improving Soil Physical Structure (Role of Manure):</strong> Manure enriches soil with organic matter (humus), increasing aeration and water retention in sandy soils and preventing waterlogging in clayey soils.</li>\r\n    <li><strong>Ensuring Rapid High Yields (Role of Fertilizers):</strong> Chemical fertilizers deliver concentrated, highly soluble N-P-K nutrients immediately to root zones, maximizing short-term commercial crop yields.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Replenishing depleted soil nutrients for healthy vegetative/reproductive growth</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Manure enhances soil structure, porosity, and microbial activity</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Fertilizers provide fast, concentrated nutrient availability for high yields</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_ex_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_3')\">\r\n      <div class=\"q-num\">Exercise — Q3</div>\r\n      <div class=\"q-text\">What are the advantages of inter-cropping and crop rotation?</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>1. Advantages of Inter-Cropping:</strong><br>\r\n  • Cultivating complementary crops in alternate rows maximizes spatial utilization of sunlight, moisture, and soil layers.<br>\r\n  • Inhibits the geometric proliferation of host-specific pests and soil-borne pathogens.<br>\r\n  • Provides agricultural risk insurance against adverse climatic events.<br><br>\r\n  <strong>2. Advantages of Crop Rotation:</strong><br>\r\n  • <strong>Replenishes Soil Fertility Naturally:</strong> Alternating a cereal crop (e.g. wheat) with a leguminous pulse crop (e.g. gram/pea) enriches the soil with fixed nitrogen via symbiotic <em>Rhizobium</em> root nodules without chemical fertilizers.<br>\r\n  • <strong>Breaks Pest & Weed Life Cycles:</strong> Changing the host crop species disrupts the continuous breeding cycles of insect pests, pathogens, and weed seeds.<br>\r\n  • Allows two or three successful harvests per year with minimal soil exhaustion.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Advantages of inter-cropping (spatial efficiency, pest disruption, risk buffer)</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Advantages of crop rotation (legume nitrogen fixation, breaking pest cycles)</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_ex_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_4')\">\r\n      <div class=\"q-num\">Exercise — Q4</div>\r\n      <div class=\"q-text\">What is genetic manipulation? How is it useful in agricultural practices?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>1. Definition of Genetic Manipulation:</strong><br>\r\n  Genetic manipulation refers to the scientific modification of an organism's genetic makeup by introducing desirable target genes into its genome. This is achieved via <strong>hybridization</strong> (cross-breeding genetically dissimilar plants) or modern <strong>recombinant DNA technology / genetic engineering</strong> to create Genetically Modified (GM) crops (e.g. Bt cotton).<br><br>\r\n  <strong>2. Agricultural Usefulness:</strong>\r\n  <ol>\r\n    <li><strong>Higher Yield:</strong> Dramatically enhances productivity per acre.</li>\r\n    <li><strong>Improved Crop Quality:</strong> Enhances baking quality in wheat, protein content in pulses, and oil quality in oilseeds.</li>\r\n    <li><strong>Biotic and Abiotic Stress Resistance:</strong> Imparts natural resistance against insect pests, fungal blights, viral diseases, as well as drought, salinity, and heat.</li>\r\n    <li><strong>Shortened Maturity Duration:</strong> Enables farmers to cultivate multiple crop cycles annually on the same plot.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: Incorporating desirable genes via hybridization or genetic engineering</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Agricultural benefits: High yield, quality, and biotic/abiotic stress resistance</span><span class=\"marking-marks\">1½ Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Short maturity duration enabling multi-cropping</span><span class=\"marking-marks\">½ Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_ex_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_5')\">\r\n      <div class=\"q-num\">Exercise — Q5</div>\r\n      <div class=\"q-text\">How do storage grain losses occur?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Mechanisms of Storage Grain Losses:</strong><br>\r\n  Post-harvest storage losses are caused by a combination of biotic and abiotic factors:\r\n  <ol>\r\n    <li><strong>Biotic Factors:</strong> Insects (weevils, beetles), rodents (rats, mice), fungi (moulds), mites, and bacteria consume the germ and endosperm of grains, contaminate food stocks with hair and droppings, and secrete dangerous mycotoxins (e.g. aflatoxin).</li>\r\n    <li><strong>Abiotic Factors:</strong> High moisture content (&gt; 12%) in freshly harvested grains coupled with warm warehouse temperatures stimulates cellular respiration of grains, generating moisture and heat.</li>\r\n  </ol>\r\n  <strong>Cumulative Damage:</strong> Leads to loss of total grain weight, severe discoloration, rancid odour, poor seed viability/germinability, and loss of commercial grade, rendering grain unfit for human consumption.\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Biotic agents: Insects, rodents, moulds, mites, bacteria</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Abiotic agents: Excessive grain moisture and warm storage temperatures</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Manifestations of damage: Weight loss, poor germination, discoloration, mycotoxins</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_ex_6\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_6')\">\r\n      <div class=\"q-num\">Exercise — Q6</div>\r\n      <div class=\"q-text\">How do good animal husbandry practices benefit farmers?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Benefits of Scientific Animal Husbandry:</strong><br>\r\n  Animal husbandry is the agricultural science of breeding, feeding, and caring for livestock.<br>\r\n  <ol>\r\n    <li><strong>Increased Economic Returns:</strong> Scientific management dramatically increases yields of animal products: milk from cattle, eggs and meat from poultry, honey and wax from apiculture, and fish from aquaculture.</li>\r\n    <li><strong>High Genetic Quality of Stock:</strong> Cross-breeding and selective breeding produce disease-resistant, high-producing progeny with longer productive lifespans.</li>\r\n    <li><strong>Draught Power for Agriculture:</strong> Strong, healthy bullocks provide crucial animal draught power for ploughing, tilling, irrigation water lifting, and cart haulage.</li>\r\n    <li><strong>Organic Manure & Biogas:</strong> Animal dung and farm waste are converted into nutrient-rich farmyard manure and biogas (methane) fuel, reducing agricultural input costs.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Increased production and economic profit from livestock products (milk, meat, eggs)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Genetic improvement and health management of farm animals</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Agricultural draught labour, biogas, and farmyard manure production</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_ex_7\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_7')\">\r\n      <div class=\"q-num\">Exercise — Q7</div>\r\n      <div class=\"q-text\">What are the benefits of cattle farming?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Dual Purposes of Cattle Farming:</strong><br>\r\n  Cattle farming (rearing cows <em>Bos indicus</em> and buffaloes <em>Bos bubalis</em>) provides two primary benefits:\r\n  <ol>\r\n    <li><strong>Dairy Production (Milch Animals):</strong> Female cattle are managed to produce milk, a vital, calcium- and protein-rich complete human food used for consumption and processing into dairy products (butter, ghee, paneer, curd).</li>\r\n    <li><strong>Agricultural Labour (Draught Animals):</strong> Castrated male cattle (bullocks) are utilized for agricultural operations such as field ploughing, harrowing, threshing, and rural cart transportation.</li>\r\n  </ol>\r\n  (Additionally, cattle dung provides organic farmyard manure and fuel).\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Milch animals providing commercial milk and dairy products</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Draught animals providing agricultural labour (ploughing, tilling, transport)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_ex_8\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_8')\">\r\n      <div class=\"q-num\">Exercise — Q8</div>\r\n      <div class=\"q-text\">For increasing production, what is common in poultry, fisheries and bee-keeping?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Common Features for Maximizing Production:</strong><br>\r\n  Across poultry, fisheries, and apiculture, productivity is maximized through four universal scientific principles:\r\n  <ol>\r\n    <li><strong>Selection of Superior Breeds:</strong> Using high-yielding, fast-growing, disease-resistant indigenous, exotic, or hybrid varieties (e.g. cross-bred broilers/layers, composite fish species, Italian bee <em>Apis mellifera</em>).</li>\r\n    <li><strong>Optimal Nutrition and Feeding:</strong> Providing scientifically formulated feed rations to satisfy specific growth and production stages.</li>\r\n    <li><strong>Hygienic Housing / Environmental Management:</strong> Maintaining clean, well-aerated, temperature-controlled, sanitized shelters, clean pond water, or well-located hives.</li>\r\n    <li><strong>Disease Prevention & Veterinary Care:</strong> Routine health inspections, prophylaxis, vaccination, and biological pest control.</li>\r\n  </ol>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of improved, high-yielding, disease-resistant genetic stock</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Controlled scientific feeding, clean environment, and disease prophylaxis</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"q-card\" id=\"q12_ex_9\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_ex_9')\">\r\n      <div class=\"q-num\">Exercise — Q9</div>\r\n      <div class=\"q-text\">How do you differentiate between capture fishing, mariculture and aquaculture?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n<div class=\"step\">\r\n  <strong>Comparison: Capture Fishing vs Mariculture vs Aquaculture:</strong>\r\n  <table class=\"data-table\">\r\n    <tr><th>Feature</th><th>Capture Fishing</th><th>Mariculture</th><th>Aquaculture</th></tr>\r\n    <tr><td><strong>Concept</strong></td><td>Harvesting wild fish populations directly from natural aquatic water bodies.</td><td>Culturing and farming valuable marine organisms in oceanic / coastal seawater.</td><td>Comprehensive farming of all aquatic flora and fauna in freshwater, brackish, or marine waters.</td></tr>\r\n    <tr><td><strong>Water Type</strong></td><td>Both marine oceans and inland freshwaters.</td><td>Strictly <strong>marine seawater</strong> (coastal waters, bays, open sea).</td><td>Freshwater ponds, rivers, brackish lagoons, estuaries, and seas.</td></tr>\r\n    <tr><td><strong>Human Intervention</strong></td><td>Zero cultivation; relies solely on locating and netting wild populations.</td><td>Active artificial seeding, controlled feeding, cage rearing, and harvesting.</td><td>Complete control over breeding, hatching, nursery rearing, feeding, and disease control.</td></tr>\r\n    <tr><td><strong>Target Species</strong></td><td>Pomfret, mackerel, tuna, catla, rohu (wild caught).</td><td>Mullets, bhetki, pearl spots, oysters (for pearls), mussels, prawns.</td><td>Carps (Catla, Rohu, Mrigal), tilapia, freshwater prawns, edible aquatic plants.</td></tr>\r\n  </table>\r\n</div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Capture fishing: Catching wild fish from natural waters with no breeding</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mariculture: Controlled farming in marine seawater environments</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Aquaculture: Broad cultivation of aquatic organisms across freshwater and saltwater</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\"><span>🎯 Competency Based Questions & HOTS — Chapter 12</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #4f46e5;\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">📝 Case Study Question</div>\r\n        <div class=\"cbq-question\"><strong>Integrated Organic Farming & Nitrogen Economy:</strong> A modern farmer establishes an integrated farm combining dairy cattle rearing, poultry, a biogas plant, and crop rotation with legumes.<br>(a) How does the inclusion of leguminous crops reduce chemical fertilizer expenses?<br>(b) How does cattle rearing support sustainable crop nutrition without buying commercial N-P-K?<br>(c) What is the dual benefit of a biogas plant in this integrated system?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><strong>(a)</strong> Leguminous crops have root nodules harboring symbiotic <em>Rhizobium</em> bacteria that fix atmospheric nitrogen gas (<span class='math'>N₂</span>) into soluble nitrates in the soil, naturally enriching soil fertility for succeeding cereal crops.<br><strong>(b)</strong> Cattle dung and farm wastes are composted into organic farmyard manure, returning macro-nutrients and humus to the crop fields.<br><strong>(c)</strong> The biogas plant digests cattle slurry to generate clean methane gas for cooking/electricity, while leaving behind a nutrient-rich, pathogen-free organic effluent slurry that acts as high-grade biofertilizer.</div>\r\n      </div>\r\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\r\n        <div class=\"cbq-type\" style=\"color:#f59e0b;\">🧠 HOTS</div>\r\n        <div class=\"cbq-question\"><strong>HOTS Question:</strong> Why is Italian bee (<em>Apis mellifera</em>) extensively preferred over our indigenous Indian bee (<em>Apis cerana indica</em>) in commercial apiculture?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\"><em>Apis mellifera</em> is commercially preferred because: (1) It has a substantially higher honey collection and storage capacity per colony, (2) It exhibits a gentle temperament with fewer stings, facilitating safer extraction, (3) It stays inside artificial wooden Langstroth hives for prolonged periods with minimal swarming or absconding, and (4) The queen bee has a much higher egg-laying prolificacy.</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(11)\">← Chapter 11</button>\r\n    <button class=\"ch-nav-btn\" disabled style=\"opacity:.4;cursor:not-allowed;\">✅ All 12 Chapters Complete</button>\r\n  </div>\r\n</section>"};
